.carousel-btn{position:absolute;top:50%;transform:translateY(-50%);width:28px;height:28px;border-radius:50%;border:0;background:rgba(255,255,255,.92);display:flex;align-items:center;justify-content:center;box-shadow:0 2px 6px rgba(0,0,0,.15);z-index:2;opacity:0;transition:opacity var(--ease)}
.post:hover .carousel-btn,.post:focus-within .carousel-btn{opacity:1}
.carousel-btn.left{left:8px}
.carousel-btn.right{right:8px}
.post.sel{border-color:#8fa6dd;box-shadow:0 0 0 1px #8fa6dd inset}
.bulk{display:flex;align-items:center;gap:10px;flex-wrap:wrap;background:var(--tint);border:1px solid var(--tint-border);border-radius:var(--r-card);padding:10px 14px}
.bulk strong{margin-right:auto;font-weight:600;color:var(--navy)}
.table td.cb,.table th.cb{width:40px;text-align:center}
.table td.cb input{accent-color:var(--brand)}
.title-btn{background:none;border:0;padding:0;text-align:left;color:var(--ink-strong);font-weight:500}
.title-btn:hover{color:var(--link);text-decoration:underline}
.pi-bar{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:12px}
.pi-grid{display:grid;grid-template-columns:260px minmax(0,1fr);gap:16px;align-items:start}
.pi-mini{width:48px;height:60px;border-radius:6px;overflow:hidden;border:2px solid transparent;padding:0;background:var(--chip)}
.pi-mini img{width:100%;height:100%;object-fit:cover;display:block}
.pi-mini.active{border-color:var(--brand)}
.thumb-strip{display:flex;gap:6px;overflow-x:auto;padding-bottom:2px}
.age-chart{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px;height:130px}
.age-chart > div{display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%;gap:6px}
.age-chart span{display:block;width:100%;max-width:36px;background:var(--tint-border);border-radius:6px 6px 2px 2px}
.age-chart small{font-size:11px;color:var(--muted-2)}
.dot-warn{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--warn);margin-left:4px;vertical-align:middle}
.drawer.wide{width:min(980px,100vw)}
@media (max-width:900px){.pi-grid,.kpis5,.reports{grid-template-columns:1fr}.matrix{grid-template-columns:110px repeat(6,minmax(0,1fr))}}
@media (prefers-reduced-motion:reduce){.compact-inner{transition:none}}

/* ── Overview insight cards ─────────────────────────────────────────────── */
.insight{padding:14px 16px;gap:10px;border-radius:var(--r-card)}
.insight.pos{background:#f5fbf8;border-color:#cfeadd;border-left:3px solid #2aa874}
.insight.caution{background:#fffaf2;border-color:#f3e0bf;border-left:3px solid #e9a64c}
.insight h3{gap:10px;font-size:13.5px;font-weight:600}
.insight h3 .mark{margin-right:0;width:22px;height:22px;vertical-align:middle}
.insight ul{padding-left:0;list-style:none;gap:8px;font-size:13px;color:var(--ink-2);line-height:1.5}
.insight li{position:relative;padding-left:14px}
.insight li::before{content:'';position:absolute;left:2px;top:.6em;width:5px;height:5px;border-radius:50%}
.insight.pos li::before{background:#2aa874}
.insight.caution li::before{background:#e9a64c}
.takeaway{background:#fff;border:1px solid #e3e7ef;padding:12px 14px 12px 17px;position:relative;overflow:hidden;line-height:1.5}
.takeaway::before{content:'';position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--brand)}
.takeaway .eyebrow{color:var(--brand)}

/* ── Brands worked with card ────────────────────────────────────────────── */
.brands-card{background:linear-gradient(180deg,#f1faf5 0%,#fff 62%);border-color:#d3ebdd}
.brands-desc{font-size:12.5px;color:var(--muted);margin:2px 0 12px;line-height:1.5}
.brands-sum{display:flex;align-items:center;gap:12px;margin-bottom:10px}
.avatar-stack{display:flex;align-items:center;flex:none}
.avatar-stack .brand-mark{width:34px;height:34px;border-radius:50%;border:2px solid #fff;margin-left:-8px;font-size:12px;box-shadow:0 1px 2px rgba(17,24,39,.08)}
.avatar-stack .brand-mark:first-child{margin-left:0}
.avatar-more{width:34px;height:34px;border-radius:50%;margin-left:-8px;border:2px solid #fff;background:#2aa874;color:#fff;display:inline-flex;align-items:center;justify-content:center;font-size:12px;font-weight:600;flex:none}
.brands-sum strong{display:block;font-size:14px;color:var(--ink-strong);font-weight:600}
.brands-sum .sub{display:block;font-size:12px;color:var(--muted-2);margin-top:1px}

/* ── Overview summary: open layout (no boxes) ───────────────────────────── */
.insights{gap:28px;padding-top:4px}
.insight{background:none;border:0;border-top:1px solid var(--line);border-radius:0;padding:14px 0 0;gap:10px}
.insight.pos,.insight.caution{background:none;border-color:var(--line);border-left:0}
.insight h3{font-size:13px;font-weight:600;color:var(--ink-strong);gap:8px;letter-spacing:0}
.insight h3 .mark{display:none}
.insight h3::before{content:'';width:7px;height:7px;border-radius:50%;flex:none}
.insight.pos h3::before{background:#2aa874}
.insight.caution h3::before{background:#e9a64c}
.insight ul{gap:8px;font-size:13.5px;color:var(--ink-2);line-height:1.6}
.insight li{padding-left:16px}
.insight li::before{left:0;top:.62em;width:4px;height:4px;background:var(--muted-3)!important}
.takeaway{background:none;border:0;border-top:1px solid var(--line);border-radius:0;padding:14px 0 0;overflow:visible;display:grid;grid-template-columns:auto 1fr;gap:16px;align-items:baseline;font-size:13.5px;color:var(--ink-2);line-height:1.6}
.takeaway::before{display:none}
.takeaway .eyebrow{color:var(--muted-2);font-size:11px;letter-spacing:.06em;text-transform:uppercase;font-weight:600}

/* ── Overview summary: icon-led points ──────────────────────────────────── */
.insights{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:28px;padding-top:0;border-top:0}
.pts{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:10px;font-size:13.5px;color:var(--ink-2);line-height:1.55}
.pts li{display:flex;gap:10px;align-items:flex-start}
.pt-ico{flex:none;width:14px;height:20px;display:inline-flex;align-items:center;justify-content:center;font-weight:700;font-size:13px}
.pt-ico.star-ico{color:#e9a64c}
.pt-ico.star-ico svg{width:13px;height:13px}
.pt-ico.bang{color:#c2410c}
.pts strong{color:var(--ink-strong);font-weight:600}
.takeaway{display:flex;gap:10px;align-items:flex-start;font-size:13.5px;color:var(--ink-strong);line-height:1.6;border-top:1px solid var(--line);padding:14px 0 0;margin:0;background:none;border-radius:0;border-left:0;border-right:0;overflow:visible}
.takeaway::before{display:none}
.takeaway .ai-ico{color:var(--brand);margin-top:3px}

.takeaway{border-top:0;border-bottom:1px solid var(--line);padding:0 0 14px}

/* ── Summary section: colorful gradient ─────────────────────────────────── */
.summary{background:linear-gradient(135deg,#eef2ff 0%,#f1f5fd 50%,#fdf0f5 100%);border-color:#e0e6f5}

/* ── Overview section titles inside their boxes ─────────────────────────── */
.section-head.in-card{margin:0 0 12px;padding-bottom:12px;border-bottom:1px solid var(--line-soft)}
.summary > .section-head.in-card{margin:0;padding:0 0 12px;border-bottom:1px solid rgba(17,24,39,.08)}

/* ── Design review pass: summary hierarchy ──────────────────────────────── */
.summary > .takeaway{border:0;padding:0;margin:0;background:none;font-size:15px;font-weight:600;color:var(--ink-strong);line-height:1.45;align-items:center;gap:12px}
.summary > .takeaway .ai-ico{width:30px!important;height:30px!important;padding:7px;box-sizing:border-box;border-radius:9px;background:#fff;color:var(--brand);box-shadow:0 1px 2px rgba(17,24,39,.08);flex:none;margin:0}
.summary > p{font-size:14px;line-height:1.65;color:var(--ink-2);max-width:72ch}
.summary .pts{font-size:13.5px}
.report-score{display:flex;flex-direction:column;gap:8px;min-width:120px}
.score-track{display:block;height:5px;border-radius:3px;background:var(--chip);overflow:hidden;width:100%}
.score-track i{display:block;height:100%;border-radius:3px}
.report-score{display:block;min-width:120px}
.score-track{margin-top:8px}

/* ── Rail cards: plain titles, open rows, size contrast ─────────────────── */
.rail-card{padding:16px 18px}
.rail-head{border-bottom:0;padding:0 0 8px;margin-bottom:0}
.rail-head h3{font-size:15px;font-weight:600;color:var(--ink-strong);text-transform:none;letter-spacing:0}
.rail-card .info{border:0;padding:8px 0;align-items:baseline;gap:16px}
.rail-card .info > span:first-child{font-size:12.5px;color:var(--muted-2);flex:none}
.rail-card .info > strong,.rail-card .info > span:last-child{font-size:14px;font-weight:600;color:var(--ink-strong);text-align:right;min-width:0}
.rail-card .note-box{font-size:13px;color:var(--ink-2);margin:6px 0 10px;line-height:1.5}
.rail-card .rail-actions{margin-top:4px}

/* ── Rail values: regular weight, distinct colour; plain Brands card ────── */
.rail-card .info > strong,.rail-card .info > span:last-child{font-weight:400;color:var(--navy)}
.brands-card{background:#fff;border-color:var(--line)}

/* ── Performance snapshot: per-metric charts ───────────────────────────── */
.snap-card h2{display:flex;align-items:center}
.deeplink{display:inline-flex;align-items:center;justify-content:center;width:26px;height:26px;margin-left:8px;border-radius:7px;color:var(--link);opacity:0;transform:translate(-3px,3px);transition:opacity var(--ease),transform var(--ease),background var(--ease);text-decoration:none}
.deeplink:hover{background:var(--tint)}
.section-head h2:hover .deeplink,.rail-head h3:hover .deeplink,.deeplink:focus-visible{opacity:1;transform:none}
.snap-opts{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:16px 0 14px}
.snap-opt{position:relative;display:flex;flex-direction:column;gap:4px;padding:11px 12px;border:1px solid var(--line);border-radius:var(--r-ctl);background:#fff;cursor:pointer;transition:border-color var(--ease),box-shadow var(--ease)}
.snap-opt input{position:absolute;opacity:0;pointer-events:none;margin:0}
.snap-opt:hover{border-color:var(--tint-border)}
.snap-opt.on{border-color:var(--c);box-shadow:inset 0 0 0 1px var(--c)}
.snap-opt:focus-within{outline:2px solid var(--link);outline-offset:2px}
.snap-k{font-size:12px;color:var(--muted-2);display:flex;align-items:center;gap:6px}
.snap-k i{width:8px;height:8px;border-radius:50%;background:var(--c);flex:none}
.snap-v{font-size:19px;font-weight:600;color:var(--ink-strong);letter-spacing:-.01em}
.snap-d{font-size:11.5px;color:var(--ok)}
.snap-legend{display:flex;align-items:center;gap:16px;flex-wrap:wrap;font-size:12px;color:var(--muted-2);margin-bottom:6px}
.snap-legend span{display:inline-flex;align-items:center;gap:6px}
.snap-legend i{display:inline-block;width:14px;border-top:2px solid var(--c,#9aa3b5)}
.snap-legend i.dash{border-top:2px dashed #9aa3b5}
.snap-pin{margin-left:auto;color:var(--ink-2);font-variant-numeric:tabular-nums}
.snap-plot{position:relative}
.snap-svg{width:100%;height:auto;display:block;overflow:visible}
.snap-tip{position:absolute;transform:translate(-50%,-100%);margin-top:-12px;background:#111827;color:#fff;font-size:13px;font-weight:600;padding:6px 10px;border-radius:8px;white-space:nowrap;pointer-events:none;box-shadow:0 6px 16px rgba(17,24,39,.2);text-align:center}
.snap-tip small{display:block;font-size:10.5px;font-weight:400;color:#cbd2e1;margin-top:1px}
.snap-tip[hidden]{display:none}
@media (max-width:900px){.snap-opts{grid-template-columns:repeat(2,minmax(0,1fr))}}

/* ── Title deeplinks: appear on title hover only ───────────────────────── */
.section-head h2,.rail-head h3{display:flex;align-items:center}
.deeplink{width:24px;height:24px;margin-left:6px;vertical-align:middle}

/* ── Audience snapshot tags: larger, pill-shaped ───────────────────────── */
.aud-tags{gap:8px}
.aud-tags .chip{font-size:13px;padding:6px 14px;border-radius:999px;line-height:1.3}

/* ── Tighter gap: Evaluated reports heading to cards ───────────────────── */
.summary > .reports{margin:-6px 0 0}

/* ── Ask about this creator: heading action ────────────────────────────── */
.ask-head{display:inline-flex;align-items:center;gap:6px;background:#fff;border-color:var(--tint-border);color:var(--navy)}
.ask-head:hover{background:var(--tint)}

/* ── Info rows: label and value share one text size, all widgets ───────── */
.info > span:first-child,.rail-card .info > span:first-child{font-size:13.5px;line-height:1.5}
.info > strong,.info > span:last-child:not(:has(*)),.rail-card .info > strong,.rail-card .info > span:last-child:not(:has(*)){font-size:13.5px;line-height:1.5}

/* ── Concise rail cards ────────────────────────────────────────────────── */
.rail-card .info{padding:6px 0}
.rail-card .note-box{margin:4px 0 8px}

/* ── Gallery: uniform cards, pastel media ──────────────────────────────── */
.grid-posts{align-items:stretch}
.grid-posts .post{height:100%}
.post-media{aspect-ratio:4/5;height:auto!important}
.post-media .media{width:100%;height:100%;object-fit:cover;display:block}
.post-media .play{background:rgba(255,255,255,.7);color:#374151}
.post-media .play svg{fill:#374151}

/* ── Pinterest-style masonry: varied media heights ─────────────────────── */
.grid-posts{display:block;column-width:220px;column-gap:14px}
.grid-posts .post{display:flex;width:100%;height:auto;margin:0 0 14px;break-inside:avoid;-webkit-column-break-inside:avoid}

/* ── List view spacing ─────────────────────────────────────────────────── */
.bulk{margin-bottom:16px}
.table th{padding:12px 14px;vertical-align:middle}
.table td{padding:10px 14px;vertical-align:middle}
.table td.cb,.table th.cb{padding-left:16px;padding-right:8px}
.table .thumb-sm{display:block;width:44px;height:56px;border-radius:6px;object-fit:cover}

/* ── Content KPIs: one card with column dividers ───────────────────────── */
.kpis5{gap:0;background:#fff;border:1px solid var(--line);border-radius:var(--r-card);padding:18px 0}
.kpis5 > div{background:none;border:0;border-radius:0;padding:2px 22px;border-left:1px solid var(--line-soft)}
.kpis5 > div:first-child{border-left:0}
@media (max-width:900px){.kpis5 > div{border-left:0;border-top:1px solid var(--line-soft);padding:12px 22px}.kpis5 > div:first-child{border-top:0}}

/* ── Content KPI card: light fill ──────────────────────────────────────── */
.kpis5{background:linear-gradient(135deg,#f5f7fe 0%,#f6fbf9 100%);border-color:#e0e6f5}

/* ── Content Strategy: consistent gaps, list fills its column ──────────── */
.cols2{gap:28px}
.cols2 > .stack{gap:16px}
.cols2 > .stack > .list{align-self:stretch;width:100%}
.cols2 .list-head{padding:0 2px;margin-bottom:2px}
.cols2 > .stack > p.note{margin:0;padding:0 2px}

/* ── Content Strategy: chart 75%, ranked list 25% ──────────────────────── */
#perfArea > .cols2{grid-template-columns:minmax(0,3fr) minmax(0,1fr)}
#perfArea .list-item > .stat:nth-last-child(2){display:none}
#perfArea .list-item{grid-template-columns:22px minmax(0,1fr) auto}
#perfArea .list-item .name{white-space:normal;line-height:1.35}

/* ── Classification drawer: sibling picker ─────────────────────────────── */
.bucket-pick{display:flex;flex-direction:column;gap:6px}
.bucket-pick .eyebrow{font-size:11px}

/* ── Verdict cards: visible stroke, aligned footers, whole-card select ─── */
.verdict{display:flex;flex-direction:column;cursor:pointer;border:1px solid #cfd7e8;height:100%;transition:border-color var(--ease),box-shadow var(--ease)}
.verdict:hover{border-color:#9fb1d6}
.verdict:focus-visible{outline:2px solid var(--link);outline-offset:2px}
.verdict.is-active{border-color:#3f63c9;box-shadow:0 0 0 1px #3f63c9}
.verdict-main{flex:1;padding:16px}
.verdict-foot{margin-top:auto;align-items:center;gap:12px}
.verdict-foot > span:first-child{min-width:0;line-height:1.5}
.verdict-acts{display:flex;align-items:center;gap:6px;white-space:nowrap;flex:none}
.verdict-acts .when{margin-right:2px}

/* ── Scored for rail ───────────────────────────────────────────────────── */
.tag-row{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0}
.tag{font-size:12.5px;padding:5px 10px;border-radius:999px;background:var(--soft);border:1px solid var(--line-soft);color:var(--ink-2)}
.tag.hl{background:var(--tint);color:var(--navy);border-color:var(--tint-border)}
.other-scores{margin-top:12px;padding-top:10px;border-top:1px solid var(--line-soft)}
.other-scores .eyebrow{display:block;margin-bottom:4px}
.rail-sub{margin-top:14px;padding-top:12px;border-top:1px solid var(--line-soft)}
.rail-sub .eyebrow{display:block;margin-bottom:8px}
.analysed{margin:0;padding:0;list-style:none;display:grid;gap:8px}
.analysed li{position:relative;padding-left:14px;font-size:13px;line-height:1.45;color:var(--ink-2)}
.analysed li::before{content:"";position:absolute;left:0;top:7px;width:5px;height:5px;border-radius:50%;background:var(--brand)}
.report-body{position:relative;margin-top:4px}
.report-body::before{content:"";position:absolute;top:-7px;left:calc(var(--caret-x,75%) - 6px);width:12px;height:12px;background:#fff;border-top:1px solid var(--line);border-left:1px solid var(--line);transform:rotate(45deg);border-radius:2px 0 0 0;z-index:2}
.hist-list{margin-top:4px}
.hist-list .info{padding:11px 0}
.hist-list .info:first-child{border-top:0}
.history{margin-top:0}

.report-body{gap:24px;padding-top:20px}
.crit-list{border-top:1px solid var(--line-soft)}
.crit-list .info{padding:14px 0;border-bottom:1px solid var(--line-soft)}
.crit-list .info:last-child{border-bottom:0}
.report-body .thumb-sm{width:52px;height:64px;flex:none}
.report-body{background:color-mix(in srgb,#3f63c9 2.5%,#fff)}
.report-body::before{background:color-mix(in srgb,#3f63c9 2.5%,#fff)}
.hist .info{flex-direction:column;align-items:flex-start;gap:2px;padding:10px 0}
.hist .info strong{text-align:left;font-weight:400;color:var(--ink-2)}
.report-body{border-color:#8fa6dd}
.report-body::before{border-top-color:#8fa6dd;border-left-color:#8fa6dd}
.stage-list{border-top:1px solid var(--line-soft)}
.stage{border-bottom:1px solid var(--line-soft)}
.stage summary{list-style:none;display:grid;grid-template-columns:140px 56px minmax(0,1fr) 16px;gap:18px;align-items:start;padding:16px 0;cursor:pointer}
.stage summary::-webkit-details-marker{display:none}
.stage-name strong{display:block;font-weight:500;font-size:15px;color:var(--ink-strong)}
.stage-name span{display:block;margin-top:2px;font-size:12.5px;color:var(--muted)}
.stage-score{font-size:26px;font-weight:500;color:var(--ink-strong);line-height:1.1}
.stage-q{font-size:13.5px;line-height:1.55;color:var(--ink-2)}
.stage-q .ask{color:var(--muted)}
.stage-chev{color:var(--muted-2);margin-top:4px;transition:transform var(--ease)}
.stage[open] .stage-chev{transform:rotate(90deg)}
.stage-body{padding:0 0 16px 214px}
.stage-body .note{margin:0;line-height:1.55}
.stage-links{display:flex;gap:18px;margin-top:10px;flex-wrap:wrap}
.stage-links .link{font-size:13px}
@media (max-width:640px){.stage summary{grid-template-columns:1fr 48px}.stage-q{grid-column:1/-1}.stage-chev{display:none}.stage-body{padding-left:0}}
.sc-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:8px}
.sc-grid .stack{align-self:start}
.sc-card{background:#fff;border:1px solid var(--line);border-radius:var(--r-card);padding:6px 16px}
.sc-item{display:flex;gap:10px;align-items:flex-start;padding:10px 0;font-size:13.5px;line-height:1.5;color:var(--ink-2)}
.sc-item + .sc-item{border-top:1px solid var(--line-soft)}
.sc-item .ico{flex:none;margin-top:3px}
.sc-item.good .ico{color:#16a34a}
.sc-item.warn .ico{color:#ea580c}
@media (max-width:640px){.sc-grid{grid-template-columns:1fr}}
.stage-score.good{color:#15803d}
.stage-score.fair{color:#b45309}
.stage-score.weak{color:#b91c1c}
.stage-body{padding:0 34px 16px 232px}
@media (max-width:640px){.stage-body{padding:0 0 16px}}
.sc-item{line-height:1.35;padding:9px 0}
.sc-item + .sc-item{border-top:0}
.sc-card{padding:4px 14px}
.stage-list{border-top:0}
.stage{border-bottom:0}
.stage summary{padding:12px 0}
.stage-body{padding-bottom:12px}
.crit-list{border-top:0}
.crit-list .info{border-bottom:0;padding:9px 0}
/* Evaluated Reports tab: tighter type scale (base 12, small 11) */
.reports-tab{font-size:12px}
.reports-tab .info,.reports-tab .note,.reports-tab .desc,.reports-tab .section-sub,.reports-tab .sc-item,.reports-tab .analysed li,.reports-tab .stage-q,.reports-tab .stage-body .note,.reports-tab .rail-row,.reports-tab .fvalue,.reports-tab .stage-links .link,.reports-tab .link,.reports-tab .verdict-copy,.reports-tab .report-open{font-size:12px}
.reports-tab .btn{font-size:12px}
.reports-tab .btn.sm{font-size:11px}
.reports-tab .chip,.reports-tab .eyebrow-sm,.reports-tab .score-label,.reports-tab .rail-head h3,.reports-tab .stage-name span,.reports-tab .verdict-foot,.reports-tab .report-foot,.reports-tab .score small,.reports-tab .report-score small{font-size:11px}
.reports-tab .section-head h2,.reports-tab .section-head h3{font-size:14px}
.reports-tab .report-h{font-size:16px}
.reports-tab .headline{font-size:13.5px}
.reports-tab .stage-name strong{font-size:13px}
.reports-tab .stage-score{font-size:22px}
.reports-tab .score{font-size:26px}
.reports-tab .sc-card{padding:2px 12px}
/* Proximity: name + score read as one unit; question sits apart; rows separated by more space than their contents */
.stage summary{grid-template-columns:116px 48px minmax(0,1fr) 16px;column-gap:10px;padding:16px 0}
.stage-q{margin-left:14px}
.stage-body{margin-top:-6px;padding:0 34px 18px 198px}
.stage-body .note{margin:0}
.stage-links{margin-top:8px}
@media (max-width:640px){.stage-body{padding-left:0}.stage-q{margin-left:0}}
/* Tighten Brand Fit vertical rhythm */
.reports-tab .report-body{gap:16px;padding-top:16px}
.reports-tab .stage summary{padding:10px 0}
.reports-tab .stage-body{padding:0 34px 10px 198px;margin-top:-4px}
.reports-tab .stage-links{margin-top:6px}
.reports-tab .stage-list{margin-top:2px}
.reports-tab .sc-grid{margin-top:0;gap:12px}
.reports-tab .sc-item{padding:5px 0}
.reports-tab .sc-card{padding:2px 12px}
.reports-tab .section-head{margin-bottom:0}
.reports-tab .stack[style*="gap:10px"]{gap:6px !important}
.verdict .eyebrow-sm{display:flex;align-items:center;gap:6px}
.verdict .ev-ico{color:var(--link);flex:none}
.verdict .ev-sub{font-size:11px;color:var(--muted-2);margin-top:2px}
/* Collaboration summary: same tile treatment as Creator evaluation signals */
.sig-card{padding:16px 18px}
.sig-card .card-title{padding-bottom:12px;margin-bottom:14px;border-bottom:1px solid var(--line-soft)}
.sig-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.sig-tile{background:#f8f9fb;border:1px solid var(--line);border-radius:8px;padding:12px 14px;display:flex;flex-direction:column;gap:2px;min-width:0}
.sig-tile small{font-size:12px;color:var(--muted)}
.sig-tile strong{font-size:20px;font-weight:600;color:var(--ink-strong);line-height:1.25;margin-top:2px}
.sig-tile > span{font-size:12px;color:var(--muted-2)}
.sig-tile .stackbar{margin-top:8px}
.sig-tile .legend{margin-top:6px;font-size:12px}
@media (max-width:900px){.sig-grid{grid-template-columns:1fr}}
.sig-tile .legend{flex-direction:column;gap:2px;white-space:nowrap}
.collab-kpis{grid-template-columns:repeat(3,minmax(0,1fr))}
.collab-kpis > div{padding:4px 22px}
.collab-kpis .legend{flex-direction:column;gap:2px;margin-top:8px;font-size:12px;white-space:nowrap}
@media (max-width:900px){.collab-kpis{grid-template-columns:1fr}}
/* Timeline badges sit on a guide line through each row */
.tl-track::before{content:"";position:absolute;left:0;right:0;top:50%;height:1px;background:rgba(63,99,201,.22);transform:translateY(-50%)}
.tl-dot{z-index:1}
/* Creator evaluation signals: heading sits on the page, tiles without the outer card */
.signals-block{display:flex;flex-direction:column;gap:10px}
.signals-block .section-head{margin:0}
.signals-block .section-head h2{font-size:15px}
.signals-grid{margin:0}
.signals-block + .chips-row{margin-top:6px}
/* Creator evaluation signals: one filled strip with dividers */
.signals-grid.kpis5{grid-template-columns:repeat(4,minmax(0,1fr));gap:0;padding:14px 0}
.signals-grid.kpis5 > .ctx{background:none;border:0;border-radius:0;padding:2px 22px;border-left:1px solid var(--line-soft);gap:2px}
.signals-grid.kpis5 > .ctx:first-child{border-left:0}
.signals-grid.kpis5 .ctx span{font-size:12px}
.signals-grid.kpis5 .ctx strong{font-size:18px}
.signals-grid.kpis5 .ctx small{font-size:12px}
@media (max-width:900px){.signals-grid.kpis5{grid-template-columns:repeat(2,minmax(0,1fr))}.signals-grid.kpis5 > .ctx:nth-child(3){border-left:0}}
.signals-block{gap:0}
.signals-title{margin-top:12px}
.signals-block + .chips-row{margin-top:10px}
.signals-title{margin-top:14px;margin-bottom:0}
.signals-block + .chips-row{margin-top:14px}
/* Brand performance table: fewer, lighter rules; tighter rows; uppercase header on a soft fill */
.brand-table{gap:10px;padding:14px 16px}
.brand-table .table{border:0;border-radius:0;overflow:visible}
.brand-table .table th{font-size:11px;font-weight:600;letter-spacing:.05em;text-transform:uppercase;color:var(--muted);background:#f7f8fb;padding:8px 12px;border-bottom:1px solid var(--line-soft)}
.brand-table .table td{padding:6px 12px;font-size:12.5px;border-bottom:1px solid #f1f2f5}
.brand-table .table tr:last-child td{border-bottom:0}
.brand-table .table .thumb-sm{width:30px;height:38px;border-radius:4px}
.brand-table .table .title-btn{font-size:12.5px}
.brand-table .table td .brand-mark{width:24px;height:24px;font-size:10px}
.brand-table .table tbody tr:hover{background:#fafbfd}
/* Audience tab: tighter rhythm, same density as other pages */
.aud-tab{gap:14px}
.aud-tab .page-title{font-size:18px}
.aud-tab .section-sub{font-size:12px;margin-top:2px}
.aud-tab .section{margin:0}
.aud-tab .section-head{margin-bottom:6px}
.aud-tab .section-head h2{font-size:14px}
.aud-tab .card{padding:12px 14px}
.aud-tab .platform-card{padding:12px 14px;gap:0}
.aud-tab .platform-card strong{font-size:13px}
.aud-tab .kpi-value{font-size:20px;margin-top:4px}
.aud-tab .info{padding:6px 0}
.aud-tab .bar-row{padding:4px 0;font-size:12px}
.aud-tab .card-title{padding-bottom:8px;margin-bottom:8px}
.aud-tab .note{font-size:11px}
.aud-tab .grid{gap:12px}
.aud-tab .link{font-size:12px}
.aud-tab .seg{margin-top:8px}
/* Brand performance: columns size to content, no stretched gaps; dense rows */
.brand-table .table{overflow-x:auto}
.brand-table .table table{width:auto;min-width:0}
.brand-table .table th,.brand-table .table td{padding:6px 10px;white-space:nowrap}
.brand-table .table th:first-child,.brand-table .table td:first-child{padding-left:12px}
.brand-table .table th:last-child,.brand-table .table td:last-child{padding-right:12px}
.brand-table{padding:12px 14px;gap:8px}
.brand-table > .between{width:100%}
.brand-table .table table{width:100%}
.brand-table .table th:last-child,.brand-table .table td:last-child{width:100%}
.brand-table .table th:last-child{text-align:left}
.brand-table > .between{display:flex;justify-content:space-between;align-items:center;gap:12px}
.brand-table .search{width:260px;flex:none;margin-left:auto}
.brand-table .search input{width:100%}
/* Proximity: section headings sit close to their own content and far from the preceding section */
.aud-tab .section{margin:26px 0 0}
.aud-tab .section > .section-head{margin:0 0 8px}
.aud-tab > .stack{gap:12px}
.aud-tab .section > .section-head{margin:0 0 4px;min-height:0;padding:0;line-height:1.3}
.aud-tab .section > .section-head h2{margin:0}
.aud-tab .section > .section-head .btn{margin:-4px 0}
.aud-tab .section > .section-head{margin:0 0 0;height:auto}
.aud-tab .section > .section-head + *{margin-top:2px}
.aud-tab .section{margin:22px 0 0}
.aud-tab .section > .section-head{min-height:0;align-items:flex-start}
.aud-tab .section > .section-head .btn{margin-top:-6px}
.aud-tab .section{gap:4px}
/* Audience demographics as pie charts */
.pie-wrap{display:flex;align-items:center;gap:18px;padding:4px 0}
.pie{width:120px;height:120px;flex:none}
.pie-legend{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:7px;flex:1;min-width:0;font-size:12px}
.pie-legend li{display:grid;grid-template-columns:8px 1fr auto;gap:8px;align-items:center;color:var(--ink-2)}
.pie-legend i{width:8px;height:8px;border-radius:2px;display:block}
.pie-legend b{font-weight:600;color:var(--ink-strong)}
.aud-tab .card .info:first-of-type{margin-top:6px}
@media (max-width:900px){.pie-wrap{flex-direction:column;align-items:flex-start}}
/* Performance: ranked bars view */
.hbars{border:1px solid var(--line);border-radius:var(--r-card);background:#fff;overflow:hidden}
.hbar-head,.hbar-row{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,2fr) 56px 52px;gap:12px;align-items:center;padding:0 14px}
.hbar-head{height:32px;background:#f7f8fb;border-bottom:1px solid var(--line-soft);font-size:11px;font-weight:600;letter-spacing:.04em;text-transform:uppercase;color:var(--muted)}
.hbar-head span:nth-child(n+3){text-align:right}
.hbar-row{width:100%;height:38px;border:0;border-bottom:1px solid #f1f2f5;background:none;text-align:left;cursor:pointer;font-size:12.5px;color:var(--ink-2)}
.hbar-row:last-child{border-bottom:0}
.hbar-row:hover{background:#fafbfd}
.hbar-row.on{background:#f3f6fd;box-shadow:inset 2px 0 0 var(--brand)}
.hbar-name{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--ink-strong);font-weight:500}
.hbar-track{height:8px;background:var(--line-soft);border-radius:4px;overflow:hidden;display:block}
.hbar-track span{display:block;height:100%;border-radius:4px}
.hbar-num{text-align:right;font-variant-numeric:tabular-nums}
.hbar-num.muted{color:var(--muted-2)}
/* Signals on Audience: title sits with the cards below it */
.aud-tab .signals-title{margin:14px 0 0;padding:0}
.aud-tab .signals-block{gap:0;margin-bottom:0}
.aud-tab .signals-block + .grid{margin-top:4px}
.hbar-row{display:grid !important;box-sizing:border-box;font:inherit;margin:0}
.hbar-head,.hbar-row{grid-template-columns:minmax(0,1.3fr) minmax(0,2fr) 52px 52px 52px !important}
/* Performance: columns view */
.vcols{display:grid;grid-template-columns:repeat(auto-fit,minmax(58px,1fr));gap:8px;align-items:end;height:300px;padding:14px 14px 0;border:1px solid var(--line);border-radius:var(--r-card);background:#fff}
.vcol{height:100%;display:flex;flex-direction:column;align-items:center;gap:6px;border:0;background:none;padding:0;cursor:pointer;min-width:0}
.vcol-val{font-size:12px;font-weight:600;color:var(--ink-strong);font-variant-numeric:tabular-nums}
.vcol-bar{flex:1;width:100%;max-width:40px;display:flex;align-items:flex-end;background:var(--line-soft);border-radius:6px 6px 0 0;overflow:hidden;min-height:0}
.vcol-bar span{display:block;width:100%;border-radius:6px 6px 0 0;transition:opacity var(--ease)}
.vcol-name{font-size:11px;line-height:1.3;color:var(--ink-2);text-align:center;height:34px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;width:100%}
.vcol:hover .vcol-bar span{opacity:.8}
.vcol.on .vcol-name{color:var(--ink-strong);font-weight:600}
.vcol.on .vcol-bar{box-shadow:0 0 0 2px var(--brand) inset}
.vcols{height:330px}
.vcol-name{height:40px;-webkit-line-clamp:2}
/* Performance: against-average dot view */
.dots{border:1px solid var(--line);border-radius:var(--r-card);background:#fff;padding:12px 14px}
.dots-axis{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,2.4fr) 52px 96px;gap:14px;align-items:end;height:20px;margin-bottom:2px}
.dots-scale{position:relative;display:block;height:100%}
.dots-scale em{position:absolute;transform:translateX(-50%);font-style:normal;font-size:11px;color:var(--muted-2);top:0}
.dot-row{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,2.4fr) 52px 96px;gap:14px;align-items:center;width:100%;height:36px;border:0;border-top:1px solid #f1f2f5;background:none;padding:0;text-align:left;cursor:pointer;font:inherit;color:var(--ink-2)}
.dot-row:first-of-type{border-top:0}
.dot-row:hover{background:#fafbfd}
.dot-row.on{background:#f3f6fd}
.dot-name{font-size:12.5px;color:var(--ink-strong);font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;padding-left:6px}
.dot-track{position:relative;height:2px;background:var(--line-soft);border-radius:2px;display:block}
.dot-avg{position:absolute;top:-10px;bottom:-10px;width:0;border-left:1px dashed #9aa3b2;transform:translateX(-0.5px);display:block}
.dot-pt{position:absolute;top:50%;width:12px;height:12px;border-radius:50%;transform:translate(-50%,-50%);display:block;box-shadow:0 0 0 2px #fff}
.dot-pt.up{background:var(--brand)}
.dot-pt.down{background:#c3cad7}
.dot-val{font-size:12.5px;font-weight:600;color:var(--ink-strong);text-align:right;font-variant-numeric:tabular-nums}
.dot-vol{font-size:12px;color:var(--muted-2);text-align:right;white-space:nowrap}
.dots-foot{margin-top:8px;padding-top:8px;border-top:1px solid var(--line-soft);font-size:12px;color:var(--muted)}
.dots-foot strong{color:var(--ink-strong);font-weight:600}
@media (max-width:900px){.dot-row,.dots-axis{grid-template-columns:minmax(0,1fr) minmax(0,1.6fr) 44px}.dot-vol{display:none}}
/* Content strategy dimensions: compact */
.dim-head{height:32px;margin-bottom:10px}
.dim-grid{gap:8px}
.dim-grid .tile{min-height:0;height:30px;padding:0 12px;display:flex;align-items:center;font-size:12px;line-height:1;border-radius:8px}
.dim-grid .tile strong{font-size:12px;line-height:1}
.dim-detail{margin-top:12px;padding-top:12px;border-top:1px solid var(--line-soft)}
.dna{padding:12px 16px}
.dna .between{margin-bottom:6px}
.dna-text{font-size:13px;color:var(--ink-2);margin:0;line-height:1.5}


/* Report view */
.tabs-line{display:flex;align-items:center;justify-content:space-between;gap:12px}
.tabs-line .tabs{flex:1;min-width:0}
.view-seg{flex:none;margin-bottom:6px}
.report-view .seg,.report-view .search,.report-view .btn,.report-view .link,.report-view .icon-btn,.report-view select,.report-view .dim-head,.report-view .dim-grid{display:none!important}
.report-view tbody tr:nth-child(n+6){display:none}
.report-mode .tabs-line{justify-content:flex-end}
.report-title{padding:4px 0 14px}
.report-title .page-title{margin:0}
.report-sec{padding:18px 0;border-top:1px solid var(--line)}
.report-sec:first-of-type{border-top:0;padding-top:0}
.report-h{font-size:15px;font-weight:600;color:var(--ink-strong);margin:0 0 12px}
.report-mode .fab{display:none}
@media print{.compact,.header-top,.tabs-line,.fab,#layer{display:none!important}.report-sec{break-inside:avoid-page}body{background:#fff}}

/* Recent posts: one row, 3/4/5 thumbs by card width */
.thumbs{grid-template-columns:repeat(5,minmax(0,1fr))}
.card:has(> .thumbs){container-type:inline-size}
@container (max-width:639px){ .thumbs{grid-template-columns:repeat(4,minmax(0,1fr))} .thumbs > .thumb:nth-child(5){display:none} }
@container (max-width:459px){ .thumbs{grid-template-columns:repeat(3,minmax(0,1fr))} .thumbs > .thumb:nth-child(4){display:none} }
/* Overview gauge cards */
.gauge-card{display:flex;flex-direction:column;gap:10px;padding:14px 16px;text-align:left;width:100%}
.gauge-top{display:flex;justify-content:space-between;align-items:center;gap:8px}
.gauge-num{font-size:34px;font-weight:600;line-height:1;color:var(--ink-strong);letter-spacing:-.5px}
.gauge-num small{font-size:13px;color:var(--muted-2);font-weight:500;margin-left:3px;letter-spacing:0}
.gauge{position:relative;margin-top:2px}
.gauge-zones{display:flex;height:8px;border-radius:4px;overflow:hidden}
.gauge-zones i{display:block}
.gauge-mark{position:absolute;top:-4px;width:3px;height:16px;background:var(--ink-strong);border-radius:2px;transform:translateX(-50%)}
.gauge-scale{position:relative;height:14px;margin-top:6px;font-size:11px;color:var(--muted-2)}
.gauge-scale span{position:absolute;top:0;transform:translateX(-50%);white-space:nowrap}
.gauge-scale span:first-child{transform:none}
.gauge-scale span:last-child{transform:translateX(-100%)}

/* Creators secondary nav: collapsible campaigns group */
.nav-toggle{width:100%;border:0;background:none;text-align:left;font:inherit;cursor:pointer}
.nav-toggle span{flex:1}
.nav-toggle svg:last-child{transition:transform .15s ease;flex:none}
.nav-exp.closed .nav-toggle svg:last-child{transform:rotate(-90deg)}
.nav-exp.closed .nav-children{display:none}

/* Discover page */
.disc-hero{text-align:center;padding:22px 18px 18px}
.disc-hero h2{font-size:22px;margin:0 0 6px;color:var(--ink-strong)}
.disc-hero .note{display:block;margin:0 auto 14px;max-width:520px}
.disc-search{display:flex;align-items:center;gap:10px;max-width:640px;margin:0 auto;height:44px;padding:0 12px;border:1px solid var(--line);border-radius:10px;background:#fff}
.disc-search .field.search{flex:1;min-width:0;border:0;box-shadow:none;background:transparent}
.disc-stats{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:0;margin-top:10px}
.disc-stats>div{padding:2px 18px;border-right:1px solid var(--line-soft);min-width:0}
.disc-stats>div:first-child{padding-left:0}
.disc-stats>div:last-child{border-right:0}
.disc-stats b{display:block;font-size:22px;font-weight:600;color:var(--ink-strong);margin:6px 0 2px}
.disc-person{display:flex;align-items:center;gap:10px;min-width:180px}
.disc-person>div{flex:1;min-width:0;display:flex;flex-direction:column}
.disc-av{width:30px;height:30px;border-radius:50%;background:var(--tint);color:var(--navy);display:grid;place-items:center;font-size:13px;font-weight:600;flex:none}
.disc-tier{display:block;font-size:11px;color:var(--muted-2)}
@media (max-width:900px){.disc-stats{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px 0}.disc-stats>div{border-right:0}}

.disc-name{border:0;background:none;padding:0;font:inherit;font-weight:600;color:var(--link);cursor:pointer;text-align:left}
.disc-name:hover{text-decoration:underline}
.disc-av.lg{width:44px;height:44px;font-size:17px}
/* Design-system specs for My creators (values from Adam DS tokens; roomy >1440px, compact <=1440px) */
.ds-page{--ds-ink:#09090b;--ds-navy:#374882;--ds-blue:#2263d5;--ds-blue-hi:#1348b0;--ds-muted:#6b7280;--ds-line:#e5e7eb;--ds-tint:#f9fbff;
  --ds-row-h:3rem;--ds-head-h:2.25rem;--ds-cell-px:1rem;--ds-title-fs:.8125rem;--ds-meta-fs:.6875rem;--ds-cell-fs:.75rem;--ds-btn-h:2rem;--ds-btn-h-sm:1.75rem;--ds-btn-px:.75rem;--ds-btn-fs:.75rem;--ds-badge-fs:.75rem;--ds-badge-fs-sm:.6rem;--ds-avatar:2.25rem;
  --ds-page-fs:1.5rem;--ds-stat-fs:1.25rem;--ds-desc-fs:.75rem;--ds-input-h:2rem;
  color:var(--ds-ink);font-size:var(--ds-cell-fs);line-height:1.4}
@media (max-width:1440px){.ds-page{--ds-row-h:2.5rem;--ds-head-h:2rem;--ds-cell-px:.75rem;--ds-title-fs:.6rem;--ds-meta-fs:.6rem;--ds-cell-fs:.6rem;--ds-btn-h:1.75rem;--ds-btn-h-sm:1.5rem;--ds-btn-px:.5rem;--ds-btn-fs:.6rem;--ds-badge-fs:.6rem;--ds-badge-fs-sm:.6rem;--ds-avatar:2rem;--ds-page-fs:1.25rem;--ds-stat-fs:1rem;--ds-desc-fs:.625rem;--ds-input-h:1.75rem}}
.ds-page button,.ds-page input,.ds-page select{font:inherit;color:inherit}
.ds-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap}
.ds-page-title{font-size:var(--ds-page-fs);line-height:1.33;font-weight:600;margin:0;display:flex;align-items:center;gap:8px}
.ds-page-desc{font-size:var(--ds-desc-fs);color:var(--ds-muted);margin:4px 0 0;line-height:1.43}
.ds-actions,.ds-toolbar,.ds-bulk{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.ds-chip{font-size:var(--ds-meta-fs);padding:2px 8px;border-radius:999px;border:1px solid var(--ds-line);color:var(--ds-muted);font-weight:500}
.ds-note{font-size:var(--ds-desc-fs);color:var(--ds-muted);margin:12px 0 0;line-height:1.5}
.ds-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;height:var(--ds-btn-h);padding:0 var(--ds-btn-px);border-radius:.375rem;border:1px solid transparent;font-size:var(--ds-btn-fs);font-weight:500;line-height:1;white-space:nowrap;cursor:pointer;background:transparent}
.ds-btn--sm{height:var(--ds-btn-h-sm)}
.ds-btn--primary{background:var(--ds-navy);color:#fff}
.ds-btn--primary:hover{background:var(--ds-blue-hi)}
.ds-btn--outline{border-color:var(--ds-blue);background:var(--ds-tint);color:var(--ds-navy)}
.ds-btn--outline:hover{background:#cce6ff;color:var(--ds-blue-hi)}
.ds-btn--ghost{color:var(--ds-blue-hi);padding:0 4px}
.ds-btn--ghost:hover{background:#cce6ff}
.ds-btn svg{width:var(--ds-btn-fs);height:var(--ds-btn-fs);flex:none;width:.875rem;height:.875rem}
.ds-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-top:16px}
.ds-card{border:1px solid var(--ds-line);border-radius:.5rem;padding:12px 16px;display:flex;flex-direction:column;gap:2px;background:#fff}
.ds-label{font-size:var(--ds-desc-fs);font-weight:500;color:var(--ds-muted)}
.ds-value{font-size:var(--ds-stat-fs);font-weight:600;color:var(--ds-ink);line-height:1.2}
.ds-caption{font-size:var(--ds-meta-fs);color:var(--ds-muted)}
.ds-toolbar{margin-top:16px}
.ds-input{position:relative;display:flex;align-items:center;height:var(--ds-input-h);min-width:240px;border:1px solid #d1d5db;border-radius:.375rem;background:#fff;padding:0 8px}
.ds-input input{flex:1;min-width:0;border:0;outline:0;background:transparent;font-size:var(--ds-cell-fs)}
.ds-input-icon{display:inline-flex;color:var(--ds-muted);margin-right:6px}
.ds-filter{position:relative;display:inline-flex;align-items:center;gap:6px;height:var(--ds-btn-h-sm);padding:0 10px;border-radius:999px;border:1px dashed #d1d5db;background:#fff;font-size:var(--ds-btn-fs);font-weight:500;cursor:pointer}
.ds-filter.is-active{border-style:solid;border-color:var(--ds-blue);background:var(--ds-tint);color:var(--ds-navy)}
.ds-filter select{position:absolute;inset:0;opacity:0;cursor:pointer;width:100%}
.ds-filter-x{position:relative;z-index:1;border:0;background:none;padding:0 0 0 2px;cursor:pointer;color:var(--ds-muted);font-size:var(--ds-btn-fs);line-height:1}
.ds-spacer{flex:1}
.ds-bulk{margin-top:12px;padding:8px 12px;border:1px solid #cce6ff;background:var(--ds-tint);border-radius:.5rem}
.ds-table-wrap{margin-top:16px;border:1px solid var(--ds-line);border-radius:.5rem;overflow-x:auto;background:#fff}
.ds-table{width:100%;border-collapse:collapse;min-width:1100px}
.ds-table th{height:var(--ds-head-h);padding:0 var(--ds-cell-px);text-align:left;font-size:var(--ds-meta-fs);font-weight:600;color:var(--ds-navy);white-space:nowrap;vertical-align:middle;background:#fff}
.ds-table td{height:var(--ds-row-h);padding:0 var(--ds-cell-px);border-top:1px solid var(--ds-line);vertical-align:middle;font-size:var(--ds-cell-fs);color:var(--ds-ink)}
.ds-table .ds-num{text-align:right;font-variant-numeric:tabular-nums}
.ds-table th.ds-num{text-align:right}
.ds-cb{width:2.5rem;text-align:center}
.ds-cb input{accent-color:var(--ds-navy)}
.ds-person{display:flex;align-items:center;gap:10px;min-width:0}
.ds-person-text{display:flex;flex-direction:column;min-width:0}
.ds-avatar{width:var(--ds-avatar);height:var(--ds-avatar);border-radius:999px;background:#f4f4f4;display:inline-flex;align-items:center;justify-content:center;flex:none}
.ds-table-title{font-size:var(--ds-title-fs);font-weight:500;color:var(--ds-ink)}
.ds-table-meta{font-size:var(--ds-meta-fs);color:var(--ds-muted)}
.ds-table-cell{font-size:var(--ds-cell-fs)}
.ds-namebtn{border:0;background:none;padding:0;font-size:var(--ds-title-fs);font-weight:500;color:var(--ds-ink);cursor:pointer;text-align:left}
.ds-namebtn:hover{text-decoration:underline}
.ds-badge{display:inline-flex;align-items:center;height:1.25rem;padding:0 8px;border:1px solid var(--ds-line);border-radius:999px;background:#fff;color:var(--ds-ink);font-size:var(--ds-badge-fs);font-weight:500;white-space:nowrap}
.ds-empty{text-align:center;color:var(--ds-muted);height:4rem}
.ds-stats--6{grid-template-columns:repeat(6,minmax(0,1fr))}
@media (max-width:1100px){.ds-stats--6{grid-template-columns:repeat(3,minmax(0,1fr))}}
.ds-seg{display:inline-flex;align-items:center;gap:2px;padding:2px;border:1px solid var(--ds-line);border-radius:8px;background:#fff}
.ds-seg button{height:var(--ds-btn-h);padding:0 var(--ds-btn-px);border:0;border-radius:6px;background:none;font-size:var(--ds-btn-fs);font-weight:500;color:var(--ds-muted);cursor:pointer;display:inline-flex;align-items:center;gap:6px;white-space:nowrap}
.ds-seg button:hover{color:var(--ds-ink)}
.ds-seg button.on{background:var(--ds-tint);color:var(--ds-blue-hi);box-shadow:inset 0 0 0 1px #c9d8f5}
.ds-count{font-size:var(--ds-meta-fs);background:#eef2f9;color:var(--ds-navy);border-radius:999px;padding:0 6px;line-height:1.25rem}
.ds-badge--success{background:#ecfdf3;color:#067647;border-color:#abefc6}
.ds-badge--warn{background:#fffaeb;color:#b54708;border-color:#fedf89}
.ds-badge--outline{background:#fff;color:#344054;border-color:#d0d5dd}
.ds-section-title{font-size:var(--ds-title-fs);font-weight:600;margin:4px 0 -4px}
.ds-cards{margin-top:16px;display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px}
.ds-plan{display:flex;flex-direction:column;gap:10px;padding:16px}
.ds-plan-tags{display:flex;gap:6px;flex-wrap:wrap}
.ds-plan-mini{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;border-top:1px solid var(--ds-line);padding-top:10px;font-size:var(--ds-meta-fs);color:var(--ds-muted)}
.ds-plan-mini span{display:flex;flex-direction:column;gap:2px}
.ds-plan-mini b{font-size:var(--ds-cell-fs);font-weight:600;color:var(--ds-ink)}
.ds-progress{height:6px;background:#eef0f4;border-radius:999px;overflow:hidden}
.ds-progress i{display:block;height:100%;background:var(--ds-blue);border-radius:999px}
.ds-plan-foot{margin-top:auto}
.ds-split-card{display:flex;flex-direction:column;gap:10px;padding:16px}
.ds-split{display:flex;height:10px;border-radius:999px;overflow:hidden;background:#eef0f4}
.ds-split i{background:var(--ds-navy)} .ds-split b{background:#7aa2ea}
.ds-legend{display:flex;gap:16px;font-size:var(--ds-meta-fs);color:var(--ds-muted)}
.ds-dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:6px}
.ds-trend-card{margin-top:16px;padding:18px 20px 12px}
.ds-trend-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}
.ds-trend-title{font-size:var(--ds-title-fs);font-weight:600;color:var(--ds-ink)}
.ds-trend-sub{font-size:var(--ds-meta-fs);color:var(--ds-muted);margin-top:2px}
.ds-trend-total{font-size:var(--ds-title-fs);font-weight:600;color:var(--ds-ink);white-space:nowrap}
.ds-trend-wrap{position:relative;margin-top:12px}
.ds-trend{width:100%;height:auto;display:block;overflow:visible}
.ds-trend-tip{position:absolute;transform:translate(12px,-100%);background:#fff;border:1px solid var(--ds-line);border-radius:.5rem;box-shadow:0 4px 12px rgba(16,24,40,.12);padding:6px 10px;font-size:var(--ds-meta-fs);display:flex;flex-direction:column;gap:2px;pointer-events:none;white-space:nowrap;color:var(--ds-ink)}
.ds-trend-tip span{color:var(--ds-muted)}
.ds-trend-tip.flip{transform:translate(calc(-100% - 12px),-100%)}
.ds-trend-tip[hidden]{display:none}
.ds-table--fit{min-width:0}
.ds-dot--navy{background:var(--ds-navy)} .ds-dot--blue{background:#7aa2ea}

.ds-page{--ds-primary:#1247af;--ds-primary-hi:#0d3a8f}
.ds-page .ds-btn--primary{background:var(--ds-primary);border-color:var(--ds-primary);color:#fff}
.ds-page .ds-btn--primary:hover{background:var(--ds-primary-hi);border-color:var(--ds-primary-hi)}
.ds-page .ds-btn--outline{color:var(--ds-primary);border-color:#c9d6ee}
.ds-tabs{display:flex;align-items:stretch;gap:20px;border-bottom:1px solid var(--ds-line);overflow-x:auto;width:100%}
.ds-tabs button{height:2.25rem;padding:0;border:0;border-bottom:2px solid transparent;margin-bottom:-1px;background:none;font-size:var(--ds-btn-fs);font-weight:500;color:var(--ds-muted);cursor:pointer;display:inline-flex;align-items:center;gap:6px;white-space:nowrap}
.ds-tabs button:hover{color:var(--ds-ink)}
.ds-tabs button.on{color:var(--ds-ink);border-bottom-color:var(--ds-primary)}
.ds-media{width:2.25rem;height:2.25rem;border-radius:.5rem;background:#eef2f9;color:#8290a4;display:grid;place-items:center;flex:none;border:1px solid var(--ds-line)}
.ds-avatar-stack{display:flex;align-items:center}
.ds-avatar-stack .ds-avatar{width:var(--ds-avatar);height:var(--ds-avatar);margin-left:-6px;border:2px solid #fff;box-sizing:content-box}
.ds-avatar-stack .ds-avatar:first-child{margin-left:0}
.ds-avatar-more{margin-left:6px;font-size:var(--ds-meta-fs);color:var(--ds-muted)}

.ds-crumb{display:flex;gap:6px;align-items:center;font-size:var(--ds-meta-fs);color:var(--ds-muted);margin-bottom:8px}
.ds-link{border:0;background:none;padding:0;color:#1247af;cursor:pointer;font:inherit}
.ds-row-between{display:flex;justify-content:space-between;align-items:center;gap:12px}
.ds-pad{padding:16px}
.ds-body{font-size:var(--ds-cell-fs);margin:0 0 6px}
.ds-brief{margin-top:16px;display:flex;flex-direction:column;gap:12px}
.ds-plan-tags{display:flex;gap:6px;flex-wrap:wrap;align-items:center}
.ds-stats--3{grid-template-columns:repeat(3,minmax(0,1fr));margin-top:0}
.ds-stats--2{grid-template-columns:repeat(2,minmax(0,1fr));margin-top:0}
.ds-grid2{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:16px}
@media (max-width:1000px){.ds-grid2{grid-template-columns:1fr}}
.ds-note--warn{background:#fffaeb;border-color:#fedf89;color:#b54708}
.ds-btn--danger{background:#fff;color:#b42318;border-color:#fda29b}
.ds-btn--danger:hover{background:#fef3f2}
.ds-select{height:var(--ds-btn-h);border:1px solid var(--ds-line);border-radius:.5rem;padding:0 8px;background:#fff;font:inherit;color:var(--ds-ink)}
.ds-bars{display:flex;align-items:flex-end;gap:6px;height:180px;margin-top:12px;overflow-x:auto}
.ds-bar-col{flex:1 0 28px;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%;gap:4px}
.ds-bar-fill{width:100%;background:#7aa2ea;border-radius:4px 4px 0 0;min-height:2px}
.ds-bar-col span{font-size:10px;color:var(--ds-muted)}
.ds-cal{margin-top:12px;display:flex;flex-direction:column;gap:10px}
.ds-cal-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));border:1px solid var(--ds-line);border-radius:.5rem;overflow:hidden;background:#fff}
.ds-cal-wd{padding:6px;font-size:var(--ds-meta-fs);color:var(--ds-muted);background:var(--ds-tint);border-bottom:1px solid var(--ds-line);text-align:center}
.ds-cal-day{min-height:96px;padding:6px;border-right:1px solid var(--ds-line);border-bottom:1px solid var(--ds-line);display:flex;flex-direction:column;gap:4px;font-size:var(--ds-meta-fs)}
.ds-cal-day:nth-child(7n){border-right:0}
.ds-cal-blank{background:#fafbfc}
.ds-cal-day.is-today{background:#f3f7ff}
.ds-cal-post{text-align:left;border:1px solid var(--ds-line);border-radius:6px;background:#fff;padding:4px 6px;cursor:pointer;display:flex;flex-direction:column;gap:2px;font-size:10px;color:var(--ds-ink)}
.ds-cal-post span{color:var(--ds-muted)}
.ds-checks{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;max-height:240px;overflow:auto;border:1px solid var(--ds-line);border-radius:.5rem;padding:8px}
.ds-check{display:flex;gap:8px;align-items:center;font-size:var(--ds-cell-fs)}
.ds-check small{color:var(--ds-muted)}
.ds-form{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:12px}
.ds-form-wide{grid-column:1/-1;display:flex;flex-direction:column;gap:6px}
.ds-field{display:flex;flex-direction:column;gap:4px;font-size:var(--ds-meta-fs);color:var(--ds-muted)}
.ds-field input,.ds-field select{height:var(--ds-btn-h);border:1px solid var(--ds-line);border-radius:.5rem;padding:0 10px;font:inherit;color:var(--ds-ink);background:#fff}
.ds-dlg{display:flex;flex-direction:column}
.ds-row-line{display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-bottom:1px solid var(--ds-line);font-size:var(--ds-cell-fs)}
.ds-media--lg{width:100%;height:140px;border-radius:.5rem;font-size:28px}

.ds-stats--4{grid-template-columns:repeat(4,minmax(0,1fr));margin-top:16px}
.ds-toolbar--wrap{flex-wrap:wrap;row-gap:8px}
.ds-split--org{height:22px;border-radius:6px}
.ds-split--org i{background:#2f9e7f;display:flex;align-items:center;justify-content:center}
.ds-split--org b{background:#e0b050;display:flex;align-items:center;justify-content:center}
.ds-split--org em{font-style:normal;color:#fff;font-size:11px;font-weight:600}
.ds-split-head{display:flex;justify-content:space-between;font-size:var(--ds-cell-fs);color:var(--ds-ink)}
.ds-split-head small{color:var(--ds-muted);margin-left:4px}
.ds-split-head b{margin-left:4px}
.ds-dot--ok{background:#2f9e7f}
.ds-contrib{height:8px;background:#eef0f4;border-radius:999px;overflow:hidden;min-width:120px}
.ds-contrib i{display:block;height:100%;background:#7aa2ea}
.ds-fold{margin-top:16px;border:1px solid var(--ds-line);border-radius:.5rem;background:#fff;overflow:hidden}
.ds-fold summary{list-style:none;cursor:pointer;display:flex;align-items:center;gap:10px;padding:12px 16px}
.ds-fold summary::-webkit-details-marker{display:none}
.ds-fold-x{margin-left:auto;font-size:var(--ds-meta-fs);color:var(--ds-muted)}
.ds-fold .ds-table-wrap{margin-top:0;border:0;border-top:1px solid var(--ds-line);border-radius:0}
.ds-fold > .ds-table-wrap + *,.ds-fold > .ds-page{margin:0}
.ds-more{position:relative;display:inline-block}
.ds-more summary{list-style:none;cursor:pointer}
.ds-more summary::-webkit-details-marker{display:none}
.ds-more-menu{position:absolute;right:0;top:calc(100% + 4px);z-index:5;background:#fff;border:1px solid var(--ds-line);border-radius:.5rem;box-shadow:0 8px 24px rgba(16,24,40,.12);display:flex;flex-direction:column;min-width:170px;padding:4px}
.ds-more-menu button{text-align:left;border:0;background:none;padding:8px 10px;border-radius:6px;cursor:pointer;font:inherit;color:var(--ds-ink)}
.ds-more-menu button:hover{background:var(--ds-tint)}
.ds-more-menu .is-danger{color:#b42318}
.ds-seg-block{margin-top:16px;display:flex;flex-direction:column;gap:6px}
.ds-seg-block .ds-table-wrap{margin-top:0}
.ds-page .ds-section-title{margin:0}
.ds-avatar{border:1px solid transparent}
.ds-paid-tag{display:inline-flex;align-items:center;gap:4px}

.ds-entity{display:flex;flex-direction:column;gap:0}
.ds-entity{display:grid;grid-template-columns:auto auto 1fr auto;align-items:center;gap:12px}
.ds-entity-text{min-width:0}
.ds-entity-meta{margin:2px 0 0;font-size:var(--ds-meta-fs);color:var(--ds-muted)}
.ds-icon-btn{width:2rem;height:2rem;border:1px solid var(--ds-line);border-radius:.5rem;background:#fff;display:inline-flex;align-items:center;justify-content:center;cursor:pointer;color:var(--ds-ink);flex:none}
.ds-icon-btn:hover{background:var(--ds-tint)}
.ds-tabrow{display:flex;justify-content:space-between;align-items:flex-end;gap:12px;border-bottom:1px solid var(--ds-line);margin-top:16px}
.ds-tabrow .ds-tabs{border-bottom:0;flex:1 1 auto}
.ds-tabrow .ds-seg{margin-bottom:6px;flex:none}
@media (max-width:900px){.ds-entity{grid-template-columns:auto 1fr}.ds-entity .ds-actions{grid-column:1/-1}}

.ds-drawer-back{position:fixed;inset:0;background:rgba(18,33,58,.36);z-index:99990;display:flex;justify-content:flex-end}
.ds-drawer{width:min(1000px,86vw);height:100dvh;display:flex;flex-direction:column;background:#fff;box-shadow:-12px 0 40px rgba(16,31,56,.17);overflow:hidden}
.ds-drawer-head{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--ds-line);padding:20px 24px;gap:16px;flex-wrap:wrap}
.ds-drawer-head h2{font-size:18px;margin:0;color:var(--ds-ink)}
.ds-drawer-head p{font-size:var(--ds-meta-fs);color:var(--ds-muted);margin:3px 0 0}
.ds-drawer-actions{display:flex;align-items:center;gap:8px}
.ds-drawer-body{min-height:0;overflow:auto;padding:18px 24px 40px;flex:1}
.ds-drawer-body .ds-table-wrap{margin-top:0}
.ds-drawer-foot{display:flex;align-items:center;gap:8px;margin-top:16px;border-top:1px solid var(--ds-line);padding-top:14px}
.ds-drawer-grid{margin-top:0}
.ds-gallery{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px}
.ds-tile{display:flex;flex-direction:column;gap:4px;text-align:left;border:1px solid var(--ds-line);border-radius:.5rem;background:#fff;padding:10px;cursor:pointer;font:inherit;color:var(--ds-ink)}
.ds-tile span{font-size:var(--ds-meta-fs);color:var(--ds-muted)}
.ds-tile:hover{border-color:#c9d6ee;background:var(--ds-tint)}
.ds-tile-hero{height:160px;border-radius:.5rem;overflow:hidden;display:flex;align-items:center;justify-content:center}
.ds-tile-hero .ds-media{width:100%;height:100%;border-radius:.5rem;border:0}
.ds-tile-hero .ds-media svg{width:40px;height:40px}

/* review pass: header + tab proportions (match creator profile: 36px CTAs, 14px tabs, 20-22px entity title) */
.ds-tabrow{flex-wrap:nowrap;align-items:center}
.ds-tabs{flex-wrap:nowrap;overflow-x:auto;gap:18px;min-width:0;scrollbar-width:none}
.ds-tabs::-webkit-scrollbar{display:none}
.ds-tabs button{font-size:.8125rem;height:2.5rem;line-height:1.2}
.ds-entity .ds-page-title{font-size:1.375rem;line-height:1.3}
.ds-entity-meta{font-size:.75rem;line-height:1.4}
.ds-entity .ds-btn{height:2.25rem;font-size:.8125rem;padding:0 .875rem;border-radius:.5rem}
.ds-entity .ds-actions{gap:8px}
.ds-icon-btn{width:2.25rem;height:2.25rem}
.ds-entity{padding-bottom:4px}

/* review pass 2: dense post tables that fit their column (no sideways scroll), smaller thumbnails and avatars */
.ds-table--dense th,.ds-table--dense td{padding-top:.5rem;padding-bottom:.5rem;vertical-align:middle}
.ds-table--dense td{font-size:.75rem}
.ds-table--dense th{font-size:.6875rem}
.ds-table-wrap--posts{overflow-x:visible}
.ds-table-wrap--posts .ds-table{min-width:0}
.ds-post-cell{display:flex;align-items:center;gap:.5rem;white-space:nowrap}
.ds-post-cell .ds-stack a{font-weight:500}
.ds-stack{display:flex;flex-direction:column;gap:2px;align-items:flex-start}
.ds-stack small{color:var(--ds-muted);font-size:.6875rem}
.ds-media--sm{width:1.75rem;height:1.75rem;border-radius:.375rem}
.ds-media--sm svg{width:12px;height:12px}
.ds-avatar--sm{width:1.5rem;height:1.5rem;border-radius:999px}
.ds-avatar--sm svg{width:12px;height:12px}
.ds-who{display:flex;align-items:center;gap:.5rem;white-space:nowrap}
.ds-who-text{display:flex;flex-direction:column;line-height:1.2}
.ds-who-text b{font-weight:500;font-size:.75rem}
.ds-who-text small{color:var(--ds-muted);font-size:.6875rem}
.ds-table-wrap--posts td:nth-child(5) .ds-stack span:first-child{white-space:nowrap}
/* ── Shared DS kit (from design-system screenshots) ── */
.ds-page .ds-beta{display:inline-block;margin-left:8px;padding:1px 6px;border-radius:4px;background:#eef2fb;color:#2a5db0;font-size:10px;font-weight:600;letter-spacing:.04em;vertical-align:middle}
.ds-page .ds-sort{display:inline-flex;align-items:center;gap:4px}
.ds-page .ds-sort svg{color:#9ca3af}
.ds-page .ds-overview{padding:0;overflow:hidden;margin-bottom:12px}
.ds-page .ds-overview>summary{list-style:none;display:flex;align-items:center;gap:10px;padding:12px 16px;cursor:pointer;border-bottom:1px solid var(--ds-line)}
.ds-page .ds-overview>summary::-webkit-details-marker{display:none}
.ds-page .ds-overview>summary .ds-section-title{flex:1}
.ds-page .ds-ov-ico{width:28px;height:28px;border-radius:6px;background:#eef2fb;color:#2a5db0;display:inline-flex;align-items:center;justify-content:center}
.ds-page .ds-chev{color:var(--ds-muted);transition:transform .15s}
.ds-page .ds-overview:not([open]) .ds-chev{transform:rotate(-90deg)}
.ds-page .ds-ov-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr))}
.ds-page .ds-ov-stat{display:flex;flex-direction:column;gap:4px;padding:14px 16px;border-right:1px solid var(--ds-line)}
.ds-page .ds-ov-stat:last-child{border-right:0}
.ds-page .ds-ov-stat .ds-label{text-transform:uppercase;font-size:11px;letter-spacing:.04em;color:var(--ds-muted)}
.ds-page .ds-ov-val{font-size:1.25rem;font-weight:600;color:var(--ds-ink)}
.ds-page .ds-ov-val small{font-size:.8rem;color:var(--ds-muted);font-weight:500}
.ds-page .ds-pager{display:flex;align-items:center;gap:16px;padding:10px 4px;justify-content:flex-end}
.ds-page .ds-pager>.ds-caption:first-child{margin-right:auto}
.ds-page .ds-pager-nav{display:flex;align-items:center;gap:4px}
.ds-page .ds-iconbtn{width:30px;height:30px;border-radius:6px;border:1px solid var(--ds-line);background:#fff;display:inline-flex;align-items:center;justify-content:center;cursor:pointer;color:var(--ds-ink)}
.ds-page .ds-iconbtn:disabled{opacity:.4;cursor:default}
.ds-page .ds-pg{min-width:30px;height:30px;border-radius:6px;border:1px solid transparent;background:#eef2fb;color:#2a5db0;font-weight:600;cursor:pointer}
.ds-page .ds-section-head{display:flex;align-items:baseline;gap:10px;margin:16px 0 10px}
.ds-page .ds-cc-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:14px}
.ds-page .ds-cc{border:1px solid var(--ds-line);border-radius:10px;background:#fff;overflow:hidden;display:flex;flex-direction:column}
.ds-page .ds-cc-head{display:flex;align-items:center;gap:8px;padding:10px 10px 8px}
.ds-page .ds-cc-plat{width:24px;height:24px;border-radius:6px;background:#0f172a;color:#fff;font-size:9px;font-weight:700;display:inline-flex;align-items:center;justify-content:center;flex:none}
.ds-page .ds-cc-name{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13px;font-weight:600}
.ds-page .ds-cc-acts{display:flex;gap:4px;flex:none}
.ds-page .ds-cc-acts .ds-iconbtn{width:26px;height:26px}
.ds-page .ds-cc-media{position:relative;aspect-ratio:4/5;margin:0 10px;border-radius:8px;overflow:hidden;display:flex;align-items:flex-end}
.ds-page .ds-cc-dur{position:absolute;top:8px;right:8px;background:rgba(15,23,42,.72);color:#fff;font-size:11px;padding:2px 7px;border-radius:4px}
.ds-page .ds-cc-tag{position:absolute;top:8px;left:8px;background:#fff;color:var(--ds-ink);font-size:11px;padding:2px 7px;border-radius:4px;font-weight:600}
.ds-page .ds-cc-bar{position:absolute;left:8px;right:8px;bottom:8px;display:flex;align-items:center;gap:8px;background:rgba(255,255,255,.92);border-radius:6px;padding:6px 8px;font-size:11px;color:var(--ds-ink)}
.ds-page .ds-cc-bar i{flex:1;height:3px;background:#d1d5db;border-radius:2px}
.ds-page .ds-cc-foot{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:10px}
.ds-page .ds-cc-foot .ds-caption{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.btn.primary{background:#1247af;border-color:#1247af;color:#fff}
.btn.primary:hover{background:#0d3a8f;border-color:#0d3a8f}
.ds-page .ds-table--dense th,.ds-page .ds-table--dense td{padding-left:8px;padding-right:8px}
.ds-page .ds-table--dense .ds-btn{white-space:nowrap}
/* ── Spacing, header tint and size parity with creator detail ── */
.ds-page{--ds-btn-h:2.25rem;--ds-btn-h-sm:2rem;--ds-btn-px:1rem;--ds-btn-fs:.875rem;--ds-title-fs:.875rem;--ds-meta-fs:.75rem;--ds-cell-fs:.875rem;--ds-cell-px:.875rem;--ds-row-h:3.25rem;--ds-head-h:2.5rem;--ds-desc-fs:.875rem;--ds-input-h:2.25rem;--ds-badge-fs:.75rem;display:flex;flex-direction:column;gap:20px}
.ds-page .ds-head{margin:0}
.ds-page .ds-head .ds-page-desc{margin-top:6px}
.ds-page .ds-head .ds-btn{height:36px;font-size:14px;padding:0 14px}
.ds-page .ds-head .ds-iconbtn{width:36px;height:36px}
.ds-page .ds-note{margin:0}
.ds-page .ds-toolbar{margin:0}
.ds-page .ds-table-wrap{margin-top:0}
.ds-page .ds-table th{background:#f1f4fb;color:#374882}
.ds-page .ds-pager{margin:0}

/* ── Information architecture page ── */
.ia-card{margin:0}
.ia-root{display:flex;align-items:center;gap:12px;margin-bottom:14px}
.ia-root-node{background:#1247af;color:#fff;padding:8px 14px;border-radius:8px;font-weight:600;font-size:14px}
.ia-root-sub{color:var(--ds-muted);font-size:13px}
.ia-tree{display:flex;flex-direction:column;gap:0;border-top:1px solid var(--ds-line)}
.ia-head{display:grid;grid-template-columns:120px 220px 1fr;gap:16px;padding:10px 0;font-size:12px;text-transform:uppercase;letter-spacing:.04em;color:var(--ds-muted);border-bottom:1px solid var(--ds-line)}
.ia-row{display:grid;grid-template-columns:120px 220px 1fr;gap:16px;align-items:start;padding:12px 0;border-bottom:1px solid var(--ds-line)}
.ia-group span{display:inline-block;background:#eef2fb;color:#374882;font-weight:600;font-size:12px;padding:4px 10px;border-radius:999px}
.ia-node{position:relative}
.ia-node::after{content:"";position:absolute;right:-16px;top:50%;width:16px;border-top:1px solid #c9d6ee}
.ia-link{border:1px solid #c9d6ee;background:#fff;color:#1247af;font:inherit;font-size:14px;font-weight:600;padding:8px 12px;border-radius:8px;cursor:pointer;text-align:left}
.ia-link:hover{background:#eef2fb}
.ia-link--page{background:#eef2fb;border-color:#eef2fb;color:#1247af}
.ia-kids{list-style:none;margin:0;padding:0 0 0 22px;border-left:1px solid #c9d6ee;display:flex;flex-direction:column;gap:8px}
.ia-kid{position:relative;display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.ia-kid::before{content:"";position:absolute;left:-22px;top:50%;width:18px;border-top:1px solid #c9d6ee}
.ia-text{font-size:13px;color:var(--ds-ink)}
.ia-kid .ia-link{font-size:13px;padding:5px 10px;font-weight:500}
.ia-kind{font-size:11px;text-transform:uppercase;letter-spacing:.04em;color:var(--ds-muted);background:var(--ds-tint);border:1px solid var(--ds-line);padding:2px 7px;border-radius:4px}
.ia-flows{display:flex;flex-direction:column;gap:14px;margin-top:12px}
.ia-flow{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
.ia-flow-name{font-size:12px;font-weight:600;color:var(--ds-muted);width:64px}
.ia-step{background:#fff;border:1px solid var(--ds-line);padding:6px 10px;border-radius:8px;font-size:13px}
.ia-arrow{color:#2a5db0;font-weight:600}
@media (max-width:900px){.ia-row,.ia-head{grid-template-columns:1fr}.ia-node::after{display:none}.ia-head{display:none}}
/* ── Table refinement: clean, airy, consistent across all tables ── */
.ds-table-wrap{border:1px solid #e3e8f2;border-radius:12px;background:#fff;box-shadow:0 1px 2px rgba(16,24,40,.04);overflow:hidden}
.ds-table-wrap--posts{overflow:auto}
.ds-table{border-collapse:separate;border-spacing:0;font-size:14px;line-height:1.45}
.ds-table th{height:auto;padding:12px 16px;background:#f2f5fc;color:#3b4a6b;font-size:13px;font-weight:600;letter-spacing:0;border-bottom:1px solid #e3e8f2;white-space:nowrap}
.ds-table td{height:auto;padding:14px 16px;border-top:1px solid #eef1f6;color:#111827;font-size:14px;line-height:1.45;vertical-align:middle}
.ds-table tbody tr:first-child td{border-top:0}
.ds-table tbody tr:hover td{background:#fafbfe}
.ds-table .ds-num,.ds-table th.ds-num{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}
.ds-table td:not(.ds-num){white-space:normal}
.ds-table .ds-table-title,.ds-table .ds-namebtn{font-size:14px;font-weight:600;color:#111827}
.ds-table .ds-table-meta,.ds-table .ds-caption{font-size:12px;color:#6b7280;line-height:1.35}
.ds-table .ds-badge{height:24px;padding:0 10px;font-size:12px;font-weight:500;border-color:#dfe4ee}
.ds-table .ds-avatar--sm{width:32px;height:32px}
.ds-table .ds-media--sm{width:36px;height:36px;border-radius:8px}
.ds-table .ds-who{gap:10px;white-space:nowrap}
.ds-table .ds-who-text b{font-size:14px;font-weight:600;color:#111827}
.ds-table .ds-who-text small{font-size:12px;color:#6b7280}
.ds-table .ds-post-cell{gap:12px;white-space:nowrap}
.ds-table .ds-post-cell .ds-stack a{font-size:14px;font-weight:500;color:#1247af}
.ds-table .ds-post-cell .ds-stack small{font-size:12px;color:#6b7280}
.ds-table .ds-stack{gap:3px}
.ds-table .ds-btn--outline.ds-btn--sm{height:34px;padding:0 14px;font-size:13px;font-weight:500;border-radius:8px;white-space:nowrap}
.ds-table .ds-iconbtn{width:34px;height:34px}
.ds-table td .ds-stack span:first-child{font-size:14px}
.ds-table-wrap--posts .ds-table{min-width:0}
.ds-table--dense th{padding:12px 14px}
.ds-table--dense td{padding:14px 14px}
.ds-table--dense td,.ds-table--dense th{font-size:inherit}
.ds-table--dense th{font-size:13px}
.ds-table--dense td{font-size:14px}
.ds-page .ds-table-wrap{margin-top:0}
.ds-table--wide th,.ds-table--wide td{padding-left:12px;padding-right:12px}
.ds-table--dense td{padding-top:16px;padding-bottom:16px}
.ds-table th{white-space:normal;line-height:1.3;vertical-align:middle}
.ds-table th .ds-sort{white-space:nowrap}
.ds-table{min-width:0}

/* ── IA canvas with curved connectors ── */
.ia-card{margin:0}
.ia-scroll{overflow-x:auto;padding:20px 12px}
.ia-canvas{position:relative;margin:0 auto}
.ia-svg{position:absolute;left:0;top:0;pointer-events:none}
.ia-edge{fill:none;stroke:#b8c7e6;stroke-width:1.5}
.ia-edge--kid{stroke:#d5deef;stroke-dasharray:0}
.ia-n{position:absolute;box-sizing:border-box;display:flex;align-items:center;margin:0;font:inherit;border-radius:10px;text-align:left}
.ia-n--root{background:#1247af;color:#fff;font-weight:600;font-size:14px;padding:0 14px;justify-content:center}
.ia-n--group{background:#eef2fb;color:#374882;font-weight:600;font-size:13px;padding:0 12px;justify-content:center;border-radius:999px}
.ia-n--page{background:#fff;border:1.5px solid #1247af;color:#1247af;font-weight:600;font-size:14px;padding:0 12px;cursor:pointer;box-shadow:0 2px 6px rgba(18,71,175,.12)}
.ia-n--page:hover{background:#eef2fb}
.ia-n--kid{background:#fff;border:1px solid #d5deef;color:var(--ds-ink);padding:6px 12px;gap:8px;cursor:pointer;justify-content:space-between;font-size:12.5px;line-height:1.3}
.ia-n--kid:hover{border-color:#1247af}
.ia-n--static{cursor:default;background:#fafbfe}
.ia-n-t{flex:1;min-width:0;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}
.ia-n-k{flex:none;font-size:10px;text-transform:uppercase;letter-spacing:.04em;color:var(--ds-muted);background:var(--ds-tint);border:1px solid var(--ds-line);padding:2px 6px;border-radius:4px}
/* ── Search inputs and filter controls: 32px everywhere ── */
.ds-input,.ds-page .ds-input{height:32px;min-height:32px;box-sizing:border-box}
.ds-input input,.ds-page .ds-input input{height:100%;font-size:13px;line-height:1}
.ds-filter,.ds-page .ds-filter{height:32px;min-height:32px;box-sizing:border-box;font-size:13px}
.ds-select,.ds-page .ds-select,.ds-page select.ds-select{height:32px;min-height:32px;box-sizing:border-box;font-size:13px}
.ds-viewseg{margin-left:auto}

/* ── Discover hero: centred search ── */
.disc-hero{text-align:center;padding:22px 20px 20px;margin:0}
.disc-hero h2{font-size:20px;font-weight:600;margin:0 0 6px;color:var(--ds-ink)}
.disc-hero p{margin:0 auto 16px;max-width:520px}
.disc-hero-search{max-width:620px;margin:0 auto;min-width:0;width:100%;background:#fff}
.disc-hero-search input{text-align:left}

/* ── Detail header standard (reference: creator header) ── */
.ds-dh{display:block;margin:0 0 4px}
.ds-dh-top{display:flex;align-items:center;gap:14px;flex-wrap:wrap}
.ds-dh-back,.ds-dh-icon{width:36px;height:36px;flex:none;border:1px solid #d9dee8;border-radius:8px;background:#fff;color:#374151;display:inline-flex;align-items:center;justify-content:center;cursor:pointer;text-decoration:none;padding:0}
.ds-dh-back:hover,.ds-dh-icon:hover{background:#f5f7fb}
.ds-dh-avatar{width:48px;height:48px;border-radius:999px;display:inline-flex;align-items:center;justify-content:center;font-size:16px;font-weight:600;flex:none}
.ds-dh-media{width:48px;height:48px;border-radius:10px;flex:none}
.ds-dh-text{min-width:0;flex:1 1 320px}
.ds-dh-name{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.ds-dh-name h1{font-size:20px;line-height:1.3;font-weight:600;margin:0;color:#111827}
.ds-dh-badge{height:22px;padding:0 8px;border:1px solid #d9dee8;border-radius:6px;font-size:12px;color:#374151;display:inline-flex;align-items:center;background:#fff;white-space:nowrap}
.ds-dh-meta{font-size:13px;color:#6b7280;margin-top:3px;display:flex;align-items:center;gap:6px;flex-wrap:wrap}
.ds-dh-sep{color:#9ca3af}
.ds-dh-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-left:auto}
.ds-dh-chip{height:32px;display:inline-flex;align-items:center;padding:0 10px;border-radius:6px;background:#eef4ff;color:#1d4ed8;font-size:13px;font-weight:500;white-space:nowrap}
.ds-dh-btn{height:36px;padding:0 14px;border-radius:8px;border:1px solid #d9dee8;background:#fff;font-size:14px;font-weight:500;display:inline-flex;align-items:center;gap:8px;cursor:pointer;color:#111827;white-space:nowrap}
.ds-dh-btn:hover{background:#f5f7fb}
.ds-dh-btn--primary{background:#1247af;border-color:#1247af;color:#fff}
.ds-dh-btn--primary:hover{background:#0d3a8f}
.ds-dh-btn.is-on{background:#eef4ff;border-color:#c9d6ee}
.ds-dh-tabrow{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;border-bottom:1px solid #e5e7eb;margin-top:16px;flex-wrap:wrap}
.ds-dh-tabs{display:flex;gap:24px;overflow-x:auto;scrollbar-width:none}
.ds-dh-tabs .tab{height:42px;border:0;border-bottom:2px solid transparent;background:none;padding:0;font-size:14px;color:#4b5563;cursor:pointer;white-space:nowrap;margin-bottom:-1px}
.ds-dh-tabs .tab.active{color:#111827;font-weight:500;border-bottom-color:#1247af}
.ds-dh-tabrow>.ds-viewseg{margin:0 0 6px auto}
.ds-dh-tabrow .ds-seg{display:inline-flex;gap:2px;padding:2px;background:#f1f4fa;border:1px solid #e3e8f2;border-radius:8px;margin:0 0 6px auto}
.ds-dh-tabrow .ds-seg button{height:28px;padding:0 12px;border:0;border-radius:6px;background:none;font-size:13px;color:#4b5563;cursor:pointer;font-family:inherit}
.ds-dh-tabrow .ds-seg button.on{background:#fff;color:#1247af;font-weight:500;box-shadow:0 1px 2px rgba(16,24,40,.08)}
/* ── Discover hero: flat, prominent search ── */
.ds-page .disc-hero{border:0;box-shadow:none;background:transparent;padding:8px 0 4px}
.ds-page .disc-hero h2{font-size:22px;font-weight:600;margin:0 0 6px}
.ds-page .disc-hero p{font-size:14px;margin:0 auto 18px;max-width:560px}
.ds-page .disc-hero-search.ds-input{height:48px;min-height:48px;max-width:640px;border:1px solid #cfd8e6;border-radius:12px;box-shadow:0 6px 20px rgba(20,35,61,.08);padding:0 16px;gap:10px;background:#fff}
.ds-page .disc-hero-search input{font-size:15px}
.ds-page .disc-hero-search .ds-input-icon svg{width:18px;height:18px}
/* ── Detail header divider: one solid line, tab underlines sit on it ── */
.ds-dh-tabrow{align-items:stretch;border-bottom:1px solid #d5dbe5;margin-top:14px}
.ds-dh-tabrow .ds-seg{align-self:center;margin:0 0 0 auto}
.ds-dh-tabs .tab{margin-bottom:-1px}
.ds-page .disc-hero-search.ds-input{height:46px;min-height:46px;border-radius:12px;border-color:#d9dee8;background:#fff;box-shadow:0 1px 2px rgba(16,24,40,.05);padding:0 6px 0 16px}
.ds-page .disc-hero-search input::placeholder{color:#6b7280}
.disc-ai-btn{flex:none;width:34px;height:34px;border:0;border-radius:999px;cursor:pointer;color:#fff;display:inline-flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#f472b6 0%,#a855f7 55%,#6366f1 100%);box-shadow:0 2px 6px rgba(168,85,247,.35)}
.disc-ai-btn:hover{filter:brightness(1.06)}
.disc-ai-btn svg{width:16px;height:16px}
.ds-page .disc-compact-head .ds-page-title{font-size:18px;font-weight:600}
.ds-page .disc-compact-head .ds-head{align-items:center}
.ds-page .disc-hero{margin:0;padding:12px 0 0}
/* ── Table row elements: checkbox, status colours, row icons ── */
.ds-badge--info{background:#eff6ff;color:#1d4ed8;border-color:#bfdbfe}
.ds-badge--danger{background:#fef2f2;color:#b42318;border-color:#fecaca}
.ds-badge--warn{background:#fffbeb;color:#92400e;border-color:#fde68a}
.ds-badge--success{background:#ecfdf3;color:#067647;border-color:#abefc6}
.ds-table .ds-namebtn{text-decoration:underline;text-decoration-color:#c7d2e6;text-underline-offset:3px}
.ds-table .ds-namebtn:hover{text-decoration-color:#1247af;color:#1247af}
.ds-table td.ds-cb{width:44px;padding-left:14px;padding-right:0}
.ds-table th.ds-cb{width:44px;padding-left:14px;padding-right:0}
.ds-table .ds-cb input{width:16px;height:16px;accent-color:#1247af;cursor:pointer}
.ds-row-end{display:flex;align-items:center;justify-content:flex-end;gap:8px;flex-wrap:nowrap}
.ds-row-icons{display:inline-flex;align-items:center;gap:2px}
.ds-row-icons button{width:28px;height:28px;border:0;background:none;color:#6b7280;border-radius:6px;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;padding:0}
.ds-row-icons button:hover{background:#f1f4fa;color:#111827}
.ds-row-icons button.is-danger:hover{background:#fef2f2;color:#b42318}
/* ── Discover search: Google-style prominent bar ── */
.ds-page .disc-hero{margin:0;padding:18px 0 4px;text-align:center}
.ds-page .disc-hero h2{font-size:24px;font-weight:600;margin:0 0 8px;color:#111827}
.ds-page .disc-hero p{font-size:14px;color:#6b7280;margin:0 auto 22px;max-width:580px;line-height:1.5}
.disc-gsearch{display:flex;align-items:center;gap:6px;height:56px;max-width:760px;margin:0 auto;padding:0 10px 0 20px;border:1px solid #dfe1e5;border-radius:999px;background:#fff;box-shadow:0 1px 6px rgba(32,33,36,.12);transition:box-shadow .15s}
.disc-gsearch:hover,.disc-gsearch:focus-within{box-shadow:0 2px 10px rgba(32,33,36,.2)}
.disc-gsearch-ico{display:inline-flex;flex:none}
.disc-gsearch input{flex:1;min-width:0;border:0;outline:0;background:transparent;font-size:16px;color:#202124;height:100%;padding:0 4px}
.disc-gsearch input::placeholder{color:#80868b}
.disc-gicon{width:40px;height:40px;flex:none;border:0;border-radius:999px;background:transparent;display:inline-flex;align-items:center;justify-content:center;cursor:pointer}
.disc-gicon:hover{background:#f1f3f4}
.disc-gmode{flex:none;height:38px;display:inline-flex;align-items:center;gap:6px;padding:0 14px;border:0;border-radius:999px;background:#f1f3f4;color:#202124;font-size:14px;font-weight:500;cursor:pointer;font-family:inherit;margin-left:4px}
.disc-gmode:hover{background:#e8eaed}
/* ── Filter dropdowns: solid 32px controls with chevron (reference style) ── */
.ds-filter,.ds-page .ds-filter{height:32px;min-height:32px;padding:0 10px 0 12px;border:1px solid #d9dee8;border-radius:8px;background:#fff;color:#374151;font-size:13px;font-weight:400;gap:6px;white-space:nowrap}
.ds-filter::after{content:"";width:5px;height:5px;border-right:1.5px solid currentColor;border-bottom:1.5px solid currentColor;transform:rotate(45deg);margin:-3px 2px 0 2px;flex:none;opacity:.7}
.ds-filter:hover{border-color:#b8c2d4;background:#fafbfd}
.ds-filter.is-active,.ds-page .ds-filter.is-active{border-color:#1247af;background:#eef4ff;color:#1247af;font-weight:500}
.ds-filter.is-active::after{opacity:1}
.ds-filter-x{border:0;background:none;color:inherit;font-size:15px;line-height:1;padding:0 0 0 2px;cursor:pointer;opacity:.7}

/* ── Visual kit (from reference screens) ── */
/* ── Visual kit (from reference screens). Single source for component visuals.
   Tokens are measured from the reference: navy rail #1b2760, brand #374882, link #1348b0,
   table head #f1f4fa, target band #f3f6fd, progress track #dfe5f1, page canvas #f4f5f9. ── */
:root{
  --v-brand:#374882; --v-brand-hover:#2f3d70; --v-link:#1348b0;
  --v-ink:#111827; --v-ink-2:#374151; --v-muted:#4b5563; --v-muted-2:#6b7280; --v-muted-3:#9ca3af;
  --v-line:#e5e7eb; --v-line-soft:#eef0f4; --v-line-2:#d1d5db;
  --v-head:#f1f4fa; --v-hover:#f8fafc; --v-select:#eef4ff; --v-band:#f3f6fd;
  --v-track:#dfe5f1; --v-fill:#1246af;
  --v-ok:#16a34a; --v-ok-ink:#166534; --v-ok-bg:#dcfce7; --v-ok-line:#bbf7d0;
  --v-warn:#d97706; --v-warn-ink:#92400e; --v-warn-bg:#fef3c7; --v-warn-line:#fde68a;
  --v-bad:#dc2626; --v-bad-ink:#991b1b; --v-bad-bg:#fee2e2; --v-bad-line:#fecaca;
  --v-info-ink:#1e40af; --v-info-bg:#dbeafe; --v-info-line:#bfdbfe;
  --v-grey-dot:#9ca3af;
  --v-r-card:12px; --v-r-ctl:8px; --v-r-pill:999px;
}
body{background:#f4f5f9}

/* Cards and boxes: 1px hairline, no shadow, 12px radius */
.ds-card,.ds-ov-stat,.ds-cc,.ds-dh-card{background:#fff;border:1px solid var(--v-line);border-radius:var(--v-r-card);box-shadow:none}
.ds-card:hover{border-color:#d7dce6}

/* Buttons: 32px, 8px radius, 13px medium */
.ds-btn{height:2rem;padding:0 .75rem;border-radius:var(--v-r-ctl);font-size:.8125rem;font-weight:500;letter-spacing:0;gap:.375rem;transition:background var(--ease),border-color var(--ease),color var(--ease)}
.ds-btn--primary{background:var(--v-brand);border-color:var(--v-brand);color:#fff}
.ds-btn--primary:hover{background:var(--v-brand-hover);border-color:var(--v-brand-hover)}
.ds-btn--outline{background:#fff;border:1px solid var(--v-line-2);color:var(--v-ink-2)}
.ds-btn--outline:hover{background:#f9fafb;border-color:#b8bfcc}
.ds-btn--ghost:hover{background:#f3f4f6}
.ds-btn--danger{background:#fff;border:1px solid var(--v-bad-line);color:var(--v-bad-ink)}
.ds-btn--danger:hover{background:var(--v-bad-bg)}
.ds-btn:focus-visible,.ds-iconbtn:focus-visible,.ds-namebtn:focus-visible{outline:2px solid #93b4f0;outline-offset:2px}

/* Badges: pill, 20px, tinted fill, no border (outline variant keeps a hairline) */
.ds-badge{height:1.25rem;padding:0 .5rem;border-radius:var(--v-r-pill);font-size:.6875rem;font-weight:500;line-height:1;display:inline-flex;align-items:center;background:#f3f4f6;color:var(--v-ink-2);border:0;white-space:nowrap}
.ds-badge--success{background:var(--v-ok-bg);color:var(--v-ok-ink)}
.ds-badge--warn{background:var(--v-warn-bg);color:var(--v-warn-ink)}
.ds-badge--danger{background:var(--v-bad-bg);color:var(--v-bad-ink)}
.ds-badge--info{background:var(--v-info-bg);color:var(--v-info-ink)}
.ds-badge--outline{background:#fff;border:1px solid var(--v-line-2);color:var(--v-muted)}

/* Status dot (used for evaluation / score states) */
.ds-dot{display:inline-block;width:.5rem;height:.5rem;border-radius:50%;background:var(--v-grey-dot);flex:none}
.ds-dot--ok{background:var(--v-ok)} .ds-dot--warn{background:var(--v-warn)} .ds-dot--bad{background:var(--v-bad)} .ds-dot--info{background:var(--v-link)}

/* Avatars: solid tones with white initials (reference), no pastel */
.ds-avatar{border-radius:50%;font-weight:600;font-size:.6875rem;letter-spacing:.02em;color:#fff;border:0;box-shadow:none}
.ds-avatar svg{display:none}
.ds-avatar-stack .ds-avatar{border:2px solid #fff;margin-left:-.5rem}
.ds-avatar-stack .ds-avatar:first-child{margin-left:0}
.ds-avatar-more{width:1.75rem;height:1.75rem;border-radius:50%;background:#eef0f4;color:var(--v-muted);font-size:.6875rem;display:inline-flex;align-items:center;justify-content:center;border:2px solid #fff}

/* Progress: 6px track, navy-blue fill */
.ds-progress{height:.375rem;border-radius:var(--v-r-pill);background:var(--v-track);overflow:hidden}
.ds-progress i{background:var(--v-fill);border-radius:inherit;display:block;height:100%}
.ds-progress--ok i{background:var(--v-ok)} .ds-progress--warn i{background:var(--v-warn)} .ds-progress--bad i{background:var(--v-bad)}

/* Tabs: underline 2px, count pill */
.ds-tabs{gap:1.25rem;border-bottom:1px solid var(--v-line)}
.ds-tabs button{height:2.5rem;padding:0;border:0;border-bottom:2px solid transparent;margin-bottom:-1px;color:var(--v-muted-2);font-size:.8125rem;font-weight:500;background:none}
.ds-tabs button:hover{color:var(--v-ink)}
.ds-tabs button.on{color:var(--v-link);border-bottom-color:var(--v-link)}
.ds-count{display:inline-flex;align-items:center;justify-content:center;min-width:1.25rem;height:1.125rem;padding:0 .3125rem;margin-left:.25rem;border-radius:var(--v-r-pill);background:#eef0f4;color:var(--v-muted);font-size:.6875rem;font-weight:500}
.ds-tabs button.on .ds-count{background:#e1e8f6;color:var(--v-link)}

/* Segmented control: grey track, white selected segment */
.ds-seg{background:#f1f2f5;border:0;border-radius:var(--v-r-ctl);padding:2px;gap:2px}
.ds-seg button{height:1.75rem;padding:0 .75rem;border:0;border-radius:6px;color:var(--v-muted);font-size:.75rem;font-weight:500;background:transparent}
.ds-seg button:hover{color:var(--v-ink)}
.ds-seg button.on{background:#fff;color:var(--v-ink);box-shadow:0 1px 2px rgba(17,24,39,.10)}

/* Tables: tinted head, 48px rows, hover and selected tint, hairline rows */
.ds-table-wrap{border:1px solid var(--v-line);border-radius:var(--v-r-card);background:#fff}
.ds-table th{background:var(--v-head);color:var(--v-muted);font-size:.75rem;font-weight:500;height:2.5rem;border-bottom:1px solid var(--v-line)}
.ds-table td{height:3rem;border-bottom:1px solid var(--v-line-soft);color:var(--v-ink-2);font-size:.8125rem}
.ds-table tbody tr:last-child td{border-bottom:0}
.ds-table tbody tr:hover td{background:var(--v-hover)}
.ds-table tbody tr.is-selected td,.ds-table tbody tr[aria-selected="true"] td{background:var(--v-select)}
.ds-table .ds-table-title{color:var(--v-ink);font-weight:500}
.ds-table .ds-table-meta,.ds-table .ds-caption{color:var(--v-muted-2);font-size:.75rem}
.ds-table .ds-num{font-variant-numeric:tabular-nums}
.ds-table input[type=checkbox]{accent-color:var(--v-link);width:1rem;height:1rem}

/* Inputs and filters: 32px, hairline border, focus ring */
.ds-input,.ds-filter,.ds-select{height:2rem;border:1px solid var(--v-line-2);border-radius:var(--v-r-ctl);background:#fff;font-size:.8125rem}
.ds-input:focus-within,.ds-filter:focus-within{border-color:#93b4f0;box-shadow:0 0 0 3px rgba(19,72,176,.12)}
.ds-filter.is-active{background:#eef4ff;border-color:#b9c9ec;color:var(--v-link)}

/* Callouts: tinted fill, matching hairline, 12px copy */
.ds-callout,.ds-note-callout{display:flex;align-items:center;gap:.75rem;padding:.625rem .875rem;border-radius:var(--v-r-ctl);border:1px solid;font-size:.8125rem}
.ds-callout--ok{background:#f0fdf4;border-color:var(--v-ok-line);color:#14532d}
.ds-callout--warn{background:#fffbeb;border-color:var(--v-warn-line);color:var(--v-warn-ink)}
.ds-callout--bad{background:#fef2f2;border-color:var(--v-bad-line);color:var(--v-bad-ink)}
.ds-callout--info{background:#eff6ff;border-color:var(--v-info-line);color:var(--v-info-ink)}
.ds-callout a,.ds-callout button{margin-left:auto;color:inherit;font-weight:500;text-decoration:underline;background:none;border:0;cursor:pointer}

/* Chips: bordered, 4px radius, check marks for matched signals */
.ds-chip{display:inline-flex;align-items:center;gap:.25rem;height:1.5rem;padding:0 .5rem;border:1px solid var(--v-line-2);border-radius:4px;background:#fff;color:var(--v-ink-2);font-size:.75rem}
.ds-chip--ok{background:#f0fdf4;border-color:var(--v-ok-line);color:var(--v-ok-ink)}
.ds-chip--warn{background:#fffbeb;border-color:var(--v-warn-line);color:var(--v-warn-ink)}

/* Score: big number + band label */
.ds-score{display:inline-flex;align-items:baseline;gap:.25rem;font-weight:600;color:var(--v-ink);font-variant-numeric:tabular-nums}
.ds-score small{color:var(--v-muted-2);font-weight:400;font-size:.75rem}

/* Accordion rows: hairline separators, rotating chevron */
.ds-card details,.ds-overview{border:1px solid var(--v-line);border-radius:var(--v-r-card)}
.ds-card summary{list-style:none}
.ds-card summary::-webkit-details-marker{display:none}
.ds-chev{transition:transform var(--ease)}
details[open]>summary .ds-chev{transform:rotate(180deg)}

/* Detail header standard: already tuned; tighten the tab row to the underline style */
.ds-dh-tabs .tab.active{color:var(--v-link);border-bottom-color:var(--v-link)}

/* Drawer: white sheet, hairline head, segmented tabs */
.ds-drawer{background:#fff}
.ds-drawer-head{border-bottom:1px solid var(--v-line)}

/* Pager, row icons: calm, 28px hit targets */
.ds-iconbtn,.ds-row-icons button{width:1.75rem;height:1.75rem;border-radius:6px;color:var(--v-muted-2)}
.ds-iconbtn:hover,.ds-row-icons button:hover{background:#f3f4f6;color:var(--v-ink)}
.ds-row-icons button.is-danger:hover{background:var(--v-bad-bg);color:var(--v-bad-ink)}


.ds-crumb{padding:0 1.5rem;margin-bottom:.25rem}

/* ── Table row height: reduced by 20% (vertical cell padding tightened, same type and avatars) ── */
.ds-table-wrap .ds-table tbody td,.ds-table tbody td,.ds-table--dense td,.ds-table-wrap--posts .ds-table td{padding-top:.5rem;padding-bottom:.5rem;height:auto;min-height:2.4rem}

/* ── Metric strips: one blue-grey panel, full width, stats divided by vertical rules ── */
.ds-stats,.ds-page .ds-ov-grid,.kpis5{background:#f3f6fb;border:1px solid #dbe3ef;border-radius:var(--v-r-card);gap:0;overflow:hidden;margin-top:16px}
.ds-stats>*,.ds-page .ds-ov-grid>.ds-ov-stat,.kpis5>*{background:transparent;border:0;border-right:1px solid #d5deea;border-radius:0;box-shadow:none}
.ds-stats>*:last-child,.ds-page .ds-ov-grid>.ds-ov-stat:last-child,.kpis5>*:last-child{border-right:0}
.ds-stats>.ds-card:hover{border-color:transparent}

/* ── Table spacing: checkbox, avatar and text breathing room ── */
.ds-table th,.ds-table td{padding-left:.875rem;padding-right:.875rem}
.ds-table td.ds-cb,.ds-table th.ds-cb{padding-left:1.25rem;padding-right:.5rem;width:2.5rem}
.ds-table td.ds-cb input[type=checkbox]{margin:0;display:block}
.ds-table .ds-person{display:flex;align-items:center;gap:.75rem;min-width:0}
.ds-table .ds-person-text{display:flex;flex-direction:column;gap:.125rem;min-width:0}
.ds-table .ds-person .ds-avatar{margin-right:0}
.ds-table .ds-table-title,.ds-table .ds-namebtn{line-height:1.35}
.ds-table .ds-table-meta,.ds-table .ds-caption{line-height:1.35}
.ds-table td{line-height:1.4}
.ds-table td.ds-num{padding-right:1rem}

/* ── Overview: one box, one fill, no inner boxes, strokes or dividers ── */
.ds-page .ds-overview,.ds-overview{background:#f3f6fb;border:0;border-radius:var(--v-r-card);box-shadow:none;margin-top:16px;overflow:hidden}
.ds-page .ds-overview *,.ds-overview *{border:0;box-shadow:none;background:transparent}
.ds-page .ds-overview>summary,.ds-overview>summary{border-bottom:0}
.ds-page .ds-overview .ds-ov-grid,.ds-overview .ds-ov-grid{margin:0;gap:0;border:0;border-radius:0;background:transparent}
.ds-page .ds-overview .ds-ov-stat,.ds-overview .ds-ov-stat{border:0;border-right:0;background:transparent}
.ds-page .ds-overview:hover,.ds-overview:hover{border-color:transparent}

/* ── Frozen columns (Discover table): checkbox + creator on the left, actions on the right ── */
.ds-table-wrap{overflow-x:auto}
.ds-table--scroll{min-width:1040px}
.ds-table th.ds-sticky-l,.ds-table td.ds-sticky-l,.ds-table th.ds-sticky-l2,.ds-table td.ds-sticky-l2,.ds-table th.ds-sticky-r,.ds-table td.ds-sticky-r{position:sticky;z-index:2;background:#fff}
.ds-table th.ds-sticky-l,.ds-table th.ds-sticky-l2,.ds-table th.ds-sticky-r{background:var(--v-head);z-index:3}
.ds-table .ds-sticky-l{left:0;width:2.5rem}
.ds-table .ds-sticky-l2{left:2.5rem;box-shadow:6px 0 8px -6px rgba(17,24,39,.22)}
.ds-table .ds-sticky-r{right:0;box-shadow:-6px 0 8px -6px rgba(17,24,39,.22);border-left:1px solid var(--v-line-soft)}
.ds-table tbody tr:hover td.ds-sticky-l,.ds-table tbody tr:hover td.ds-sticky-l2,.ds-table tbody tr:hover td.ds-sticky-r{background:var(--v-hover)}
.ds-table tbody tr.is-selected td.ds-sticky-l,.ds-table tbody tr.is-selected td.ds-sticky-l2,.ds-table tbody tr.is-selected td.ds-sticky-r{background:var(--v-select)}
.ds-name-row{display:flex;align-items:center;gap:.25rem;min-width:0}
.ds-name-row .ds-person{flex:1;min-width:0}
.ds-name-row .ds-row-icons{flex:none}
.ds-name-row .ds-row-icons button{width:1.5rem;height:1.5rem}

/* ── My creators: reference columns, dotted editable cost, score colours, SPOC avatars ── */
.ds-cost{border:0;background:none;padding:0;font:inherit;color:inherit;border-bottom:1px dashed #9ca3af;cursor:pointer}
.ds-cost:hover{color:var(--v-link);border-bottom-color:var(--v-link)}
.ds-score-val{font-weight:600;color:var(--v-muted)}
.ds-score-val.is-ok{color:#15803d} .ds-score-val.is-warn{color:#b45309} .ds-score-val.is-low{color:#b91c1c}
.ds-table .ds-avatar.ds-spoc{width:1.5rem;height:1.5rem;font-size:.625rem;display:inline-flex}

/* ── Column component: custom cell input, hover-count popover, column manager rows ── */
.ds-cell-input{width:100%;min-width:7rem;height:1.75rem;border:1px solid transparent;border-radius:6px;background:transparent;padding:0 .375rem;font:inherit;color:inherit}
.ds-cell-input:hover{border-color:var(--v-line-2)}
.ds-cell-input:focus{outline:none;border-color:#93b4f0;background:#fff;box-shadow:0 0 0 3px rgba(19,72,176,.12)}
.ds-hcount{display:inline-flex;min-width:1.5rem;justify-content:center;padding:0 .375rem;height:1.25rem;align-items:center;border-radius:var(--v-r-pill);background:#eef0f4;color:var(--v-ink-2);font-weight:500;cursor:default;font-variant-numeric:tabular-nums}
.ds-hcount:hover,.ds-hcount:focus{background:#e1e8f6;color:var(--v-link);outline:none}
.ds-hpop{position:fixed;z-index:200;display:none;min-width:200px;max-width:280px;background:#fff;border:1px solid var(--v-line);border-radius:var(--v-r-ctl);box-shadow:var(--shadow-pop);padding:.625rem .75rem;pointer-events:none}
.ds-hpop b{display:block;font-size:.6875rem;text-transform:uppercase;letter-spacing:.04em;color:var(--v-muted-2);margin-bottom:.375rem}
.ds-hpop span{display:block;font-size:.8125rem;color:var(--v-ink-2);padding:.125rem 0}
.ds-colmgr{display:flex;flex-direction:column;gap:.5rem;min-width:min(440px,80vw)}
.ds-colrow{display:flex;align-items:center;justify-content:space-between;gap:.5rem;padding:.375rem .5rem;border-radius:6px}
.ds-colrow:hover{background:#f8fafc}
.ds-colmove{display:flex;gap:.25rem}
.ds-colnew{margin-top:.75rem;padding-top:.75rem;border-top:1px solid var(--v-line-soft);display:flex;flex-direction:column;gap:.5rem}

/* ── Column manager layout fixes ── */
.ds-colmgr{padding-right:.25rem}
.ds-colrows{max-height:44vh;overflow:auto}
.ds-colmgr .ds-caption{margin:0 0 .25rem}
.ds-colrow{padding:.125rem .375rem;min-height:2rem}
.ds-colrow .ds-check{margin:0;min-height:0;padding:.25rem 0;gap:.5rem;font-size:.8125rem}
.ds-colrow .ds-check span{font-size:.8125rem}
.ds-colrow .ds-iconbtn{width:1.625rem;height:1.625rem;border:1px solid var(--v-line-2);background:#fff;border-radius:6px}
.ds-colnew .ds-form{display:flex;flex-direction:column;gap:.5rem}
.ds-colnew .ds-field{display:flex;flex-direction:column;gap:.25rem;font-size:.75rem;color:var(--v-muted)}
.ds-colnew .ds-field input{width:100%;height:2rem;border:1px solid var(--v-line-2);border-radius:var(--v-r-ctl);padding:0 .625rem;font:inherit;font-size:.8125rem;color:var(--v-ink)}
.ds-colnew .ds-field input:focus{outline:none;border-color:#93b4f0;box-shadow:0 0 0 3px rgba(19,72,176,.12)}

/* ── Creator side panel ── */
.ds-drawer.ds-drawer--side{width:min(460px,92vw)}
.cs{display:flex;flex-direction:column;gap:20px}
.cs-id{display:flex;align-items:center;gap:12px}
.cs-avatar{width:3rem;height:3rem;font-size:.9375rem;flex:none}
.cs-id-text{display:flex;flex-direction:column;min-width:0;flex:1}
.cs-id-text b{font-size:1rem;color:var(--v-ink)} .cs-id-text span{font-size:.8125rem;color:var(--v-muted-2)}
.cs-stats{margin-top:0;grid-template-columns:repeat(5,minmax(0,1fr))}
.cs-stats .ds-ov-stat{padding:12px 10px}
.cs-stats .ds-ov-val{font-size:1rem}
.cs-sec h3{margin:0 0 10px;font-size:.6875rem;font-weight:600;text-transform:uppercase;letter-spacing:.06em;color:var(--v-muted-2)}
.cs-sec-head{display:flex;justify-content:space-between;align-items:baseline;gap:8px}
.cs-sec-head h3{margin-bottom:10px}
.cs-sec .ds-caption{margin:0 0 8px}
.cs-scores{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.cs-score{border:1px solid var(--v-line);border-radius:var(--v-r-card);padding:14px 16px;display:flex;flex-direction:column;gap:6px;background:#fff}
.cs-score-l{font-size:.8125rem;color:var(--v-muted)}
.cs-score-v{font-size:1.5rem;font-weight:600;font-variant-numeric:tabular-nums}
.cs-score-v.is-ok{color:#15803d} .cs-score-v.is-warn{color:#b45309} .cs-score-v.is-low{color:#b91c1c}
.cs-tl{list-style:none;margin:0;padding:0}
.cs-ev{display:grid;grid-template-columns:52px 14px 1fr;gap:10px;position:relative;padding-bottom:18px}
.cs-ev:last-child{padding-bottom:0}
.cs-ev::before{content:"";position:absolute;left:calc(52px + 10px + 6px);top:14px;bottom:0;width:1px;background:var(--v-line)}
.cs-ev:last-child::before{display:none}
.cs-date{font-size:.75rem;color:var(--v-muted-2);text-align:right;padding-top:1px;font-variant-numeric:tabular-nums}
.cs-dot{width:9px;height:9px;border-radius:50%;background:var(--v-link);margin-top:4px;justify-self:center;box-shadow:0 0 0 3px #fff}
.cs-ev:has(.cs-verb:first-child) .cs-dot{}
.cs-ev-title{font-size:.8125rem;color:var(--v-ink-2);line-height:1.4}
.cs-ev-title b{color:var(--v-ink);font-weight:500}
.cs-verb{color:var(--v-link);font-weight:500}
.cs-chip{display:inline-block;margin-top:4px;font-size:.75rem;color:var(--v-ok-ink);background:var(--v-ok-bg);border-radius:var(--v-r-pill);padding:1px 8px}
.cs-post{margin-top:8px;display:flex;align-items:center;gap:10px;border:1px solid var(--v-line);border-radius:var(--v-r-ctl);padding:8px}
.cs-post .ds-media{width:2.5rem;height:2.5rem;border-radius:6px;flex:none}
.cs-post-text{display:flex;flex-direction:column;min-width:0}
.cs-post-text b{font-size:.8125rem;color:var(--v-ink);font-weight:500}
.cs-post-text span{font-size:.75rem;color:var(--v-muted-2)}

/* ── Side panel: lifetime tiles, SPOC row, notes ── */
.ds-drawer .cs-stats .ds-label,.ds-page .cs-stats .ds-label{text-transform:none;letter-spacing:0;font-size:.75rem;white-space:nowrap}
.ds-drawer .cs-stats .ds-ov-stat{padding:12px 8px}
.cs-stats .ds-ov-val{font-size:1rem}
.cs-life{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}
.cs-life-t{background:#f3f6fb;border-radius:var(--v-r-ctl);padding:12px 8px;display:flex;flex-direction:column;align-items:center;gap:4px;text-align:center}
.cs-life-t b{font-size:1.0625rem;font-weight:600;color:var(--v-ink);font-variant-numeric:tabular-nums}
.cs-life-t span{font-size:.6875rem;color:var(--v-muted-2)}
.cs-row{display:flex;align-items:center;gap:10px;border-top:1px solid var(--v-line-soft);border-bottom:1px solid var(--v-line-soft);padding:10px 0;margin:0}
.cs-row-l{font-size:.6875rem;font-weight:600;text-transform:uppercase;letter-spacing:.06em;color:var(--v-muted-2);width:4.5rem}
.cs-spoc{display:flex;align-items:center;gap:8px;flex:1;font-size:.8125rem;color:var(--v-ink-2)}
