/* ── Phase 1 analytics ── */
.tl{margin:0 0 18px;padding:16px 18px;border:1px solid #e5e7eb;border-radius:12px;background:#fff}
.tl-head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;flex-wrap:wrap;margin-bottom:14px}
