/* round 77: campaign list has no checkbox column (no bulk actions) */
.cp-table .ds-sticky-l2{left:0}

/* round 78: compact campaign overview, definitions live in tooltips only */
.dk-ov{padding:12px 16px}
.dk-ov .dk-p2-head{margin-bottom:8px}
.dk-ov-row{gap:8px}
.dk-ov-item{padding:10px 14px}
.dk-ov-item b{font-size:22px;line-height:1.1}

/* round 79: campaign analytics as a native table (no iframe, no CDN); expanded rows share the same columns */
.ana-card{border:1px solid #e5e7eb;border-radius:12px;background:#fff;overflow:hidden}
.ana-scroll{overflow-x:auto}
.ana-table{width:100%;min-width:760px;border-collapse:collapse;table-layout:fixed;font-size:13px;color:#374151;font-variant-numeric:tabular-nums}
.ana-table col.ana-c1{width:64px}.ana-table col.ana-c2{width:92px}.ana-table col.ana-c3{width:92px}.ana-table col.ana-c4{width:76px}
.ana-table thead th{height:40px;padding:0 14px;background:#f1f4fa;color:#4b5563;font-weight:500;font-size:12px;text-align:right;white-space:nowrap;border-bottom:1px solid #e5e7eb}
.ana-table thead th.ana-l{text-align:left}
.ana-table td{height:52px;padding:0 14px;text-align:right;border-bottom:1px solid #eef0f4;white-space:nowrap;vertical-align:middle}
.ana-table td:first-child{text-align:left;white-space:normal}
.ana-table tr:last-child td{border-bottom:0}
.ana-strong{font-weight:600;color:#111827}
.ana-mute{color:#6b7280}
.ana-row{cursor:pointer}
.ana-row:hover td{background:#f8fafc}
.ana-row.is-open td{background:#F8FAFF}
.ana-cell{display:flex;align-items:center;gap:10px;min-width:0}
.ana-min{min-width:0}
.ana-name{font-size:13px;font-weight:500;color:#1f2937;line-height:1.3;overflow:hidden;text-overflow:ellipsis}
.ana-sub{font-size:11.5px;color:#9ca3af;line-height:1.35;overflow:hidden;text-overflow:ellipsis}
.ana-av{width:30px;height:30px;border-radius:50%;color:#fff;font-size:11px;font-weight:600;display:flex;align-items:center;justify-content:center;flex:none}
.ana-chev{display:inline-flex;width:14px;flex:none;color:#9ca3af;transition:transform 120ms}
.ana-chev svg{width:12px;height:12px}
.ana-row.is-open .ana-chev{transform:rotate(90deg)}
.ana-tag{display:inline-block;padding:1px 6px;border-radius:4px;font-size:11px;background:#f3f4f6;color:#4b5563;margin-right:2px}
.ana-child{display:none}
.ana-child.is-open{display:table-row}
.ana-child td{height:46px;background:#fafbfc;font-size:12.5px}
.ana-child td:first-child{padding-left:42px}
.ana-play{width:24px;height:24px;border-radius:6px;background:#eef1f7;color:#9ca3af;display:flex;align-items:center;justify-content:center;flex:none}
.ana-play svg{width:9px;height:9px}
.ana-total td{height:44px;background:#fafbfc;font-weight:600;color:#111827}
.ana-total td:first-child{font-weight:600}
.ana-bar{display:flex;justify-content:flex-end;align-items:center;gap:8px;margin-bottom:12px}
.ana-date{display:inline-flex;align-items:center;height:32px;padding:0 12px;border:1px solid #bfd0f0;border-radius:8px;background:#eef4ff;color:#2f4a8a;font-size:13px;font-weight:500;white-space:nowrap}

/* round 80: dashboard campaign selector beside date range; accordion overview; single campaign insights and creator table */
.dk-head-actions{flex-wrap:wrap}
.dk-acc>summary{list-style:none;cursor:pointer}
.dk-acc>summary::-webkit-details-marker{display:none}
.dk-acc-h{display:flex;align-items:center;gap:10px}
.dk-acc-chev{margin-left:auto;display:inline-flex;color:#6b7280;transition:transform 120ms}
.dk-acc-chev svg{width:14px;height:14px}
.dk-acc[open] .dk-acc-chev{transform:rotate(180deg)}
.dk-acc[open]>summary{margin-bottom:8px}
.dk-ov-static{cursor:default}
.dk-ov-static:hover{background:transparent}
.cp-ins-card,.cp-creators{margin-top:12px}
.cp-ins{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}
.cp-ins-item{padding:12px 14px;border:1px solid #e5e7eb;border-radius:10px;background:#fff}
.cp-ins-t{font-size:12px;color:#6b7280}
.cp-ins-v{font-size:18px;font-weight:600;color:#111827;margin-top:2px}
.cp-ins-d{font-size:12px;color:#6b7280;margin-top:2px}

/* round 81: views trend series switch, boost ticks; overview filters and post table */
.vg-seg{margin-left:auto}
.vg-seg button{font-size:12px}
.vg-boost line{stroke:#d97706;stroke-width:2;stroke-linecap:round}
.cp-ovf{margin:0 0 12px}
.cp-posts{margin-top:12px}
.cp-posts .ct-post-cell{min-width:200px}

/* round 82: KPI row has four cards now (Published posts moved to overview) */
.dk-kpis{grid-template-columns:repeat(4,minmax(0,1fr))}
@media (max-width:1180px){.dk-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:820px){.dk-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}

/* round 83: creator picker in campaign dialogs is a table of the shortlist with all columns */
.dlg-ct{width:100%}
.dlg-ct-scroll{max-height:340px}
.dlg-ct tr.is-sel td{background:#F5F8FF}
.modal:has(.dlg-ct){width:min(1120px,calc(100vw - 32px));max-width:none}
.dlg-ct table{min-width:900px}

/* round 84: bar rows fit their card; concept / product rows open a side panel; side panel tabs and stats */
.dk-row2>.ds-card{min-width:0}
.dk-hb{grid-template-columns:minmax(0,130px) minmax(40px,1fr) auto auto;gap:10px}
.dk-hb small,.dk-rr-meta span{white-space:nowrap}
.dk-hb.is-click,.dk-rr.is-click{cursor:pointer;border-radius:8px}
.dk-hb.is-click:hover,.dk-rr.is-click:hover{background:#f5f7fc}
.dk-hb.is-click:focus-visible,.dk-rr.is-click:focus-visible{outline:2px solid #3b49c9;outline-offset:2px}
.dk-side-tabs{margin-bottom:16px}
.dk-side-stats{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-bottom:12px}
.dk-side-stat{display:flex;flex-direction:column;gap:4px}
.dk-side-split{margin-bottom:12px;display:flex;flex-direction:column;gap:8px}
.dk-side-row{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:12px;font-size:13px;padding:6px 0;border-bottom:1px solid #eef0f4}
.dk-side-row small{color:#6b7280}

/* ── Campaign overview, creators and header (round 52) ── */
.vg{padding:16px 18px;margin-bottom:14px}
.vg-head{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;margin-bottom:6px}
.vg-svg{display:block;width:100%;height:auto;overflow:visible}
