.ct-link{font-size:12px;color:#6b7280}
.ct-thumb,.ct-thumb.ct-reel,.ct-thumb.ct-post,.ct-thumb.ct-carousel{width:40px;height:40px;border-radius:8px;box-shadow:none;flex-direction:column;justify-content:flex-end;padding-bottom:4px;font-size:9.5px;font-weight:600;line-height:1;letter-spacing:.02em}
