.ana-child td:first-child{padding-left:42px}
.ana-play{width:24px;height:24px;border-radius:6px;background:#eef1f7;color:#9ca3af;display:flex;align-items:center;justify-content:center;flex:none}
.ana-play svg{width:9px;height:9px}
.ana-total td{height:44px;background:#fafbfc;font-weight:600;color:#111827}
.ana-total td:first-child{font-weight:600}
.ana-bar{display:flex;justify-content:flex-end;align-items:center;gap:8px;margin-bottom:12px}
.ana-date{display:inline-flex;align-items:center;height:32px;padding:0 12px;border:1px solid #bfd0f0;border-radius:8px;background:#eef4ff;color:#2f4a8a;font-size:13px;font-weight:500;white-space:nowrap}

/* round 80: dashboard campaign selector beside date range; accordion overview; single campaign insights and creator table */
.dk-head-actions{flex-wrap:wrap}
.dk-acc>summary{list-style:none;cursor:pointer}
.dk-acc>summary::-webkit-details-marker{display:none}
.dk-acc-h{display:flex;align-items:center;gap:10px}
.dk-acc-chev{margin-left:auto;display:inline-flex;color:#6b7280;transition:transform 120ms}
.dk-acc-chev svg{width:14px;height:14px}
.dk-acc[open] .dk-acc-chev{transform:rotate(180deg)}
.dk-acc[open]>summary{margin-bottom:8px}
.dk-ov-static{cursor:default}
.dk-ov-static:hover{background:transparent}
.cp-ins-card,.cp-creators{margin-top:12px}
.cp-ins{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}
.cp-ins-item{padding:12px 14px;border:1px solid #e5e7eb;border-radius:10px;background:#fff}
.cp-ins-t{font-size:12px;color:#6b7280}
.cp-ins-v{font-size:18px;font-weight:600;color:#111827;margin-top:2px}
.cp-ins-d{font-size:12px;color:#6b7280;margin-top:2px}

/* round 81: views trend series switch, boost ticks; overview filters and post table */
