.ct-seg button span{font-size:11.5px;color:#6b7280;background:#eef0f4;border-radius:99px;padding:0 7px}
.ct-seg button.on{background:#fff;color:#111827;font-weight:600;box-shadow:0 1px 2px rgba(0,0,0,.08)}
.ct-seg button.on span{background:#1f3a68;color:#fff}
.ap-tabs{display:inline-flex;gap:4px;padding:3px;border:1px solid #e5e7eb;border-radius:10px;margin-bottom:12px}
.ap-tabs button{border:0;background:transparent;border-radius:8px;padding:6px 12px;font:inherit;font-size:13px;color:#4b5563;cursor:pointer}
.ap-tabs button.on{background:#1f3a68;color:#fff}
.ap-csv{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:6px}
.ap-tpl{font-size:12px;background:#f7f8fb;border:1px solid #e5e7eb;border-radius:8px;padding:8px 10px;margin:6px 0 0;overflow:auto}
.ap-actions{margin:6px 0 10px}
.ap-wrap{max-height:320px;overflow:auto;margin-top:10px}
.ap-table{min-width:760px}
.ap-table td{padding:6px 8px}
.ap-sel,.ap-in{height:30px;border:1px solid #d6dbe4;border-radius:7px;padding:0 6px;font:inherit;font-size:12.5px;background:#fff}
.ap-num{width:90px}
.ap-x{width:26px;height:26px;border:1px solid #e5e7eb;border-radius:7px;background:#fff;cursor:pointer;font-size:14px;line-height:1}
.ap-empty{margin-top:10px}
/* round 63: compact spend cell, percentage beside the bar */
.cp-table td{padding-top:8px;padding-bottom:8px}
.cp-spend{min-width:190px}
.cp-spend .cp-prog-txt{font-size:12.5px;line-height:1.3}
.cp-bar-row{display:flex;align-items:center;gap:10px;margin-top:4px}
.cp-bar-row .cp-bar{flex:1;min-width:0;margin:0}
.cp-pct{font-size:12px;font-weight:600;color:#374151;min-width:38px;text-align:right;font-variant-numeric:tabular-nums}
.cp-spend.is-over .cp-pct{color:#b42318}
.cp-spend.is-risk .cp-pct{color:#b45309}

/* round 64: dashboard timeline redesign + plain tertiary links */
.tv{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:18px 20px;margin:0 0 16px;box-shadow:none}
.tv-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;flex-wrap:wrap;margin:0}
.tv-title{font-size:15px;font-weight:600;color:#111827;line-height:1.3}
.tv-sub{font-size:12.5px;color:#6b7280;margin:3px 0 0}
.tv-legend{display:flex;gap:14px;font-size:12px;color:#4b5563;margin:2px 0 0;align-items:center}
.tv-legend span{display:inline-flex;align-items:center;gap:6px}
.tv-legend i{width:10px;height:10px;border-radius:3px;display:inline-block}
.tv-org,.tv-stk .tv-org{background:#374882}
.tv-boo,.tv-stk .tv-boo{background:#7aa2f0}
.tv--split{display:grid;grid-template-columns:minmax(0,3fr) minmax(200px,1fr);gap:0;align-items:stretch}
.tv-main{min-width:0;padding-right:22px;border-right:1px solid #eef0f4}
.tv-frame{display:grid;grid-template-columns:34px minmax(0,1fr);gap:10px;height:240px;margin-top:16px}
.tv-yax{position:relative;height:100%}
.tv-yax span{position:absolute;right:0;transform:translateY(50%);font-size:11px;color:#9ca3af;line-height:1;font-variant-numeric:tabular-nums}
.tv-plot{position:relative;height:100%;border-bottom:1px solid #d6dbe4}
.tv-gl{position:absolute;left:0;right:0;height:0;border-top:1px solid #f0f2f6}
.tv-cols{position:absolute;inset:0;display:flex}
.tv-col{flex:1;height:100%;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;position:relative;border-radius:4px;cursor:default}
.tv-col:hover,.tv-col.is-on{background:#f3f6fc}
.tv-stk{width:min(14px,50%);display:flex;flex-direction:column;border-radius:3px 3px 0 0;overflow:hidden}
.tv-stk i{display:block;min-height:0}
.tv-xax{display:flex;margin:8px 0 0 44px;font-size:11px;color:#6b7280}
.tv-xax span{flex:1;text-align:center;white-space:nowrap;overflow:visible}
.tv-tip{position:absolute;top:0;z-index:3}
.tv-side{display:flex;flex-direction:column;padding-left:22px;gap:0}
.tv-kpi{display:flex;flex-direction:column;gap:2px;padding:14px 0;border:0;border-bottom:1px solid #eef0f4;border-radius:0;background:none}
.tv-kpi:first-child{padding-top:0}
.tv-kpi:last-child{border-bottom:0;padding-bottom:0}
.tv-kpi span{font-size:12px;color:#6b7280}
.tv-kpi b{font-size:20px;font-weight:600;color:#111827;line-height:1.2;font-variant-numeric:tabular-nums}
.tv-kpi small{font-size:12px;color:#6b7280}
.tv-empty{font-size:12.5px;color:#6b7280;margin:10px 0 0}
@media (max-width:900px){
  .tv--split{grid-template-columns:1fr}
  .tv-main{border-right:0;padding-right:0}
  .tv-side{padding-left:0;padding-top:14px;margin-top:14px;border-top:1px solid #eef0f4;display:grid;grid-template-columns:1fr 1fr;column-gap:16px}
  .tv-kpi:nth-child(odd){padding-right:0}
}
.my-link,.my-table tbody .my-link{text-decoration:none}
.my-link:hover,.my-table tbody .my-link:hover{text-decoration:underline}

/* round 67: freeze first and last columns in campaign Creators and Content tables */
.ds-table th.cs-first,.ds-table td.cs-first{position:sticky;left:0;z-index:2;background:#fff}
.ds-table th.cs-first{background:var(--v-head);z-index:3}
.ds-table th.cs-last,.ds-table td.cs-last{position:sticky;right:0;z-index:2;background:#fff}
.ds-table th.cs-last{background:var(--v-head);z-index:3}
.ds-table td.cs-first{box-shadow:6px 0 8px -6px rgba(17,24,39,.22)}
.ds-table td.cs-last{box-shadow:-6px 0 8px -6px rgba(17,24,39,.22);border-left:1px solid var(--v-line-soft)}
.ds-table tbody tr:hover td.cs-first,.ds-table tbody tr:hover td.cs-last{background:var(--v-hover)}

/* round 68: cumulative dashboard per PRD v2 — status row, campaign comparison, pagination */
.dk-status{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:0 0 14px}
.dk-stat{all:unset;box-sizing:border-box;cursor:pointer;background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:14px 16px;display:flex;flex-direction:column;gap:2px;transition:border-color .15s,background .15s}
.dk-stat:hover{border-color:#b8c7e6}
.dk-stat:focus-visible{outline:2px solid #2263d5;outline-offset:2px}
.dk-stat.is-on{border-color:#374882;background:#f3f6fc;box-shadow:inset 0 0 0 1px #374882}
.dk-stat-l{display:inline-flex;align-items:center;gap:6px;font-size:12.5px;color:#4b5563;font-weight:500}
.dk-stat b{font-size:22px;font-weight:600;color:#111827;line-height:1.2;font-variant-numeric:tabular-nums}
.dk-stat small{font-size:12px;color:#6b7280}
.dk-info{width:15px;height:15px;border-radius:50%;border:1px solid #c7ccd6;font-size:10px;font-style:normal;display:inline-flex;align-items:center;justify-content:center;color:#6b7280;cursor:help}
.dk-camps{margin:14px 0}
.dk-camps .ds-table td:first-child{min-width:240px}
@media (max-width:820px){.dk-status{grid-template-columns:repeat(2,minmax(0,1fr))}}
.dk-kpis{grid-template-columns:repeat(5,minmax(0,1fr))}
@media (max-width:1180px){.dk-kpis{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media (max-width:820px){.dk-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}

/* round 69: PRD v2 completion — campaign picker, chips, alerts, aggregated views trend */
.dk-cf{position:relative;display:inline-block}
.dk-cf>summary{list-style:none;cursor:pointer}
.dk-cf>summary::-webkit-details-marker{display:none}
.dk-cf-panel{position:absolute;top:calc(100% + 6px);left:0;z-index:40;width:280px;background:#fff;border:1px solid #e5e7eb;border-radius:12px;box-shadow:0 10px 30px rgba(17,24,39,.14);padding:10px;display:flex;flex-direction:column;gap:8px}
.dk-cf-list{max-height:260px;overflow:auto;display:flex;flex-direction:column;gap:2px}
.dk-cf-item{display:flex;align-items:center;gap:8px;padding:6px;border-radius:6px;font-size:13px;color:#111827;cursor:pointer}
.dk-cf-item:hover{background:#f3f6fc}
.dk-cf-foot{display:flex;justify-content:flex-end;border-top:1px solid #eef0f4;padding-top:8px}
.dk-chips{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.dk-trend-ctl{display:flex;gap:6px;flex-wrap:wrap;align-items:center}
.dk-trend-legend{margin:10px 0 0}
.dk-trend .tv-plot{height:100%}
.dk-trend-svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible;pointer-events:none}
.dk-boost{position:absolute;top:-2px;transform:translateX(-50%);font-size:10px;color:#b7791f;line-height:1;cursor:help}
.dk-boost-key{color:#b7791f;margin-right:2px}
.dk-trend-note{margin:10px 0 0}
.dk-row3{grid-template-columns:repeat(2,minmax(0,1fr))}
@media (max-width:900px){.dk-row3{grid-template-columns:1fr}}
.dk-alerts{margin:14px 0}
.dk-alert-list{display:flex;flex-direction:column;gap:6px}
.dk-alert{display:flex;gap:10px;align-items:baseline;font-size:13px;padding:8px 10px;border-radius:8px;background:#f9fafb;border:1px solid #eef0f4}
.dk-alert-tag{flex:none;font-size:11px;font-weight:600;padding:2px 8px;border-radius:99px;background:#eef1f6;color:#374151}
.dk-alert--warn .dk-alert-tag{background:#fff4df;color:#9a6700}
.dk-alert--bad .dk-alert-tag{background:#fde8e8;color:#b42318}
.dk-alert--info .dk-alert-tag{background:#e8f0fe;color:#2d5bb8}
.dk-alert-t{color:#374151}

/* round 71: layout pass per UX brief — trend + organic pair, breakdown grid, flags, alert reasons */
.dk-pair{display:grid;grid-template-columns:minmax(0,2fr) minmax(260px,1fr);gap:14px;margin:14px 0;align-items:stretch}
.dk-pair>.tv{margin:0;height:100%;box-sizing:border-box}
.dk-org{margin:0;display:flex;flex-direction:column;gap:12px;padding:18px 20px}
.dk-org-body{display:grid;grid-template-columns:140px minmax(0,1fr);gap:18px;align-items:center}
.dk-org-body .dk-donut-wrap{width:140px}
.dk-org-table{width:100%;border-collapse:collapse;font-size:13px}
.dk-org-table th{font-size:12px;color:#6b7280;font-weight:500;text-align:left;padding:0 0 6px}
.dk-org-table td{padding:8px 0;border-top:1px solid #eef0f4;color:#111827}
.dk-org-table .ds-num{text-align:right;font-variant-numeric:tabular-nums}
.dk-org-table .dk-org-total td{font-weight:600;border-top:1px solid #d6dbe4}
.dk-org-table .dk-sw{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:8px;vertical-align:middle}
.dk-org-foot{display:flex;justify-content:space-between;gap:10px;font-size:12.5px;color:#4b5563;border-top:1px solid #eef0f4;padding-top:10px;flex-wrap:wrap}
.dk-org-foot b{color:#111827;font-weight:600}
#dash-breakdowns{grid-template-columns:repeat(3,minmax(0,1fr))}
@media (max-width:1100px){.dk-pair{grid-template-columns:1fr}#dash-breakdowns{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:900px){#dash-breakdowns{grid-template-columns:1fr}}
.dk-flag{display:inline-block;font-size:11px;font-weight:600;padding:2px 8px;border-radius:99px;white-space:nowrap}
.dk-flag--good{background:#e3f6ec;color:#17704a}
.dk-flag--bad{background:#fde8e8;color:#b42318}
.dk-alert-why{display:block;font-size:12px;color:#6b7280;margin-top:2px}
.dk-alert-act{flex:none;margin-left:auto;white-space:nowrap}
.dk-status-note{margin:8px 0 0}
.dk-trend .tv-title,.dk-org .ds-section-title{font-size:14px}
.dk-org-body{grid-template-columns:1fr;gap:12px}
.dk-org-body .dk-donut-wrap{width:120px;margin:0 auto}
.dk-camps .ds-table-wrap{overflow-x:auto}
.dk-camps .ds-table th,.dk-camps .ds-table td{padding-left:10px;padding-right:10px}
.dk-camps .ds-table td:first-child{min-width:200px}
.dk-flag-row{margin-top:4px}

/* round 72: trend card fills its row; lighter tooltip so it does not hide the line */
.dk-trend{display:flex;flex-direction:column}
.dk-trend .tv-chart{flex:1;display:flex;flex-direction:column;min-height:0}
.dk-trend .tv-frame{flex:1;height:auto;min-height:240px}
.dk-trend .tv-tip{background:#fff;color:#111827;border:1px solid #e5e7eb;box-shadow:0 6px 18px rgba(17,24,39,.12);width:176px;padding:9px 11px;font-size:12px;gap:2px}
.dk-trend .tv-tip b{color:#111827}
.dk-trend .tv-tip-split i{width:9px;height:9px}
.dk-trend .tv-col:hover,.dk-trend .tv-col.is-on{background:rgba(55,72,130,.06)}
.dk-org .dk-donut-c b{font-size:17px;white-space:nowrap}
.dk-org .dk-donut-c span{font-size:11px}

/* round 73: campaign overview strip and shared performance strip (no per-metric cards) */
.dk-ov{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:6px 0 0;margin:0 0 10px}
.dk-ov-row{display:grid;grid-template-columns:repeat(4,minmax(0,1fr))}
.dk-ov-item{all:unset;box-sizing:border-box;cursor:pointer;display:flex;flex-direction:column;gap:2px;padding:12px 24px 14px;border-left:1px solid #eef0f4;position:relative}
.dk-ov-item:first-child{border-left:0}
.dk-ov-item:focus-visible{outline:2px solid #2263d5;outline-offset:-2px;border-radius:8px}
.dk-ov-l{font-size:12.5px;color:#6b7280;font-weight:500}
.dk-ov-item b{font-size:30px;font-weight:600;color:#111827;line-height:1.15;font-variant-numeric:tabular-nums}
.dk-ov-s{font-size:11.5px;color:#9ca3af}
.dk-ov-item:hover .dk-ov-l{color:#111827}
.dk-ov-item.is-on::after{content:"";position:absolute;left:24px;right:24px;bottom:0;height:2px;background:#374882;border-radius:2px}
.dk-ov-item.is-on b{color:#374882}
.dk-ov .dk-status-note{margin:0;padding:8px 24px 10px;border-top:1px solid #eef0f4}
.dk-perf{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:12px 0;margin:0 0 14px}
.dk-perf-item{padding:4px 24px;display:flex;flex-direction:column;gap:3px;border-left:1px solid #eef0f4;min-width:0}
.dk-perf-item:first-child{border-left:0}
.dk-perf-l{font-size:12.5px;color:#6b7280;font-weight:500;white-space:nowrap}
.dk-perf-v{font-size:22px;font-weight:600;color:#111827;line-height:1.2;font-variant-numeric:tabular-nums;white-space:nowrap}
.dk-perf-s{font-size:11.5px;color:#9ca3af;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
@media (max-width:1180px){.dk-perf{grid-template-columns:repeat(3,minmax(0,1fr));row-gap:12px}.dk-perf-item:nth-child(4){border-left:0}}
@media (max-width:760px){.dk-ov-row{grid-template-columns:repeat(2,minmax(0,1fr))}.dk-ov-item:nth-child(3){border-left:0}.dk-perf{grid-template-columns:repeat(2,minmax(0,1fr))}.dk-perf-item:nth-child(3){border-left:0}}
.dk-perf-s{white-space:normal;line-height:1.35;overflow:visible;text-overflow:clip}
.dk-perf-l,.dk-perf-v{white-space:normal}

/* round 74: overview + performance as tinted panels (reference style) */
.dk-ov{background:#f3f6fb;border:0;border-radius:14px;padding:16px 20px 18px;margin:0 0 6px;box-shadow:none}
.dk-p2{background:#f3f6fb;border:0;border-radius:14px;padding:16px 20px 18px;margin:0 0 14px;box-shadow:none;display:block}
.dk-p2-head{display:flex;align-items:center;gap:10px;margin:0 0 14px}
.dk-p2-tile{width:30px;height:30px;border-radius:8px;background:#dfe7f6;color:#2f4a8a;display:inline-flex;align-items:center;justify-content:center;flex:none}
.dk-p2-title{font-size:15px;font-weight:600;color:#111827}
.dk-p2-sub{margin-left:auto;font-size:12.5px;color:#6b7280}
.dk-ov-row{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}
.dk-ov-item{all:unset;box-sizing:border-box;cursor:pointer;border-radius:12px;padding:12px 16px 14px;display:flex;flex-direction:column;gap:6px;position:relative}
.dk-ov-item::after{display:none}
.dk-ov-item:hover{background:rgba(255,255,255,.6)}
.dk-ov-item.is-on{background:#fff;box-shadow:0 1px 2px rgba(17,24,39,.08)}
.dk-ov-item:focus-visible{outline:2px solid #2263d5;outline-offset:2px}
.dk-ov-l,.dk-perf-l{display:flex;align-items:center;gap:7px;font-size:11.5px;letter-spacing:.06em;text-transform:uppercase;color:#4b5563;font-weight:600}
.dk-ov-l svg,.dk-perf-l svg{color:#2f4a8a;flex:none}
.dk-ov-item b{font-size:32px;font-weight:600;color:#1d2a4f;line-height:1.1;font-variant-numeric:tabular-nums}
.dk-ov-item.is-on b{color:#2f4a8a}
.dk-ov-s,.dk-perf-s{font-size:12.5px;color:#6b7280;line-height:1.35}
.dk-p2-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px}
.dk-p2-grid .dk-perf-item{padding:12px 16px 14px;border-left:0;border-radius:12px;gap:6px;background:transparent}
.dk-p2-grid .dk-perf-item:hover{background:rgba(255,255,255,.6)}
.dk-perf-v{font-size:26px;font-weight:600;color:#1d2a4f;line-height:1.15;font-variant-numeric:tabular-nums}
.dk-status-note{margin:8px 4px 0;font-size:12px}
@media (max-width:1180px){.dk-p2-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media (max-width:760px){.dk-ov-row,.dk-p2-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}

/* round 75: revert performance to KPI cards; scrollable lists (10 rows visible); filter on heading line */
.dk-scroll{overflow:auto;position:relative}
.dk-scroll-camps{max-height:560px}
.dk-scroll-posts{max-height:620px}
.dk-scroll thead th{position:sticky;top:0;z-index:2;background:#fff;box-shadow:inset 0 -1px 0 #e5e7eb}
.dk-wh--row{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}
.dk-wh--row .dk-wa{margin-left:auto}
.dk-wh--row .dk-wt{flex-wrap:wrap}
.dk-posts .dk-scroll-posts .ds-table-wrap--posts{overflow:visible}
.dk-scroll-camps{max-height:520px}
.dk-scroll-camps{max-height:500px}
.dk-scroll-posts{max-height:590px}
.dk-adv-btn{display:inline-flex;align-items:center;gap:6px}
.dk-cf-btn{display:inline-flex;align-items:center;gap:6px}
.dk-cf-chev{display:inline-flex;margin-left:2px;color:currentColor;opacity:.75}
.dk-cf-chev svg{width:14px;height:14px}

/* round 76: period dropdown with range label; custom dates inside the panel (no layout shift) */
.dk-per-wrap{position:relative;display:inline-flex;align-items:center;gap:6px}
.dk-per{position:relative}
.dk-per>summary{list-style:none}
.dk-per>summary::-webkit-details-marker{display:none}
.dk-per-trig{display:flex;align-items:center;gap:8px;width:236px;height:36px;box-sizing:border-box;padding:0 12px;border:1px solid #c9d6ee;border-radius:8px;background:#fff;cursor:pointer;font-size:13px;font-weight:600;color:#111827;white-space:nowrap}
.dk-per-trig:hover{border-color:#8fa9dd}
.dk-per-val{flex:1;overflow:hidden;text-overflow:ellipsis;text-align:left}
.dk-per-cal{display:inline-flex;color:#2f4a8a}
.dk-per-cal svg{width:15px;height:15px}
.dk-per-trig .dk-cf-chev svg{width:14px;height:14px}
.dk-per-panel{position:absolute;right:0;top:calc(100% + 6px);z-index:60;width:250px;background:#fff;border:1px solid #e5e7eb;border-radius:12px;box-shadow:0 10px 30px rgba(17,24,39,.14);padding:6px;display:flex;flex-direction:column;box-sizing:border-box}
.dk-per-opt{all:unset;box-sizing:border-box;display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:8px;font-size:13px;color:#111827;cursor:pointer}
.dk-per-opt:hover{background:#f3f6fb}
.dk-per-opt.is-on{font-weight:600}
.dk-per-opt svg{width:15px;height:15px;color:#2f4a8a;flex:none}
.dk-per-tick{width:15px;height:15px;flex:none}
.dk-per-dates{display:flex;flex-direction:column;gap:8px;padding:10px;border-top:1px solid #eef0f4;margin-top:6px}
