/* round 76: period dropdown with range label; custom dates inside the panel (no layout shift) */
.dk-per-wrap{position:relative;display:inline-flex;align-items:center;gap:6px}
.dk-per{position:relative}
.dk-per>summary{list-style:none}
.dk-per>summary::-webkit-details-marker{display:none}
.dk-per-trig{display:flex;align-items:center;gap:8px;width:236px;height:36px;box-sizing:border-box;padding:0 12px;border:1px solid #c9d6ee;border-radius:8px;background:#fff;cursor:pointer;font-size:13px;font-weight:600;color:#111827;white-space:nowrap}
.dk-per-trig:hover{border-color:#8fa9dd}
.dk-per-val{flex:1;overflow:hidden;text-overflow:ellipsis;text-align:left}
.dk-per-cal{display:inline-flex;color:#2f4a8a}
.dk-per-cal svg{width:15px;height:15px}
.dk-per-trig .dk-cf-chev svg{width:14px;height:14px}
.dk-per-panel{position:absolute;right:0;top:calc(100% + 6px);z-index:60;width:250px;background:#fff;border:1px solid #e5e7eb;border-radius:12px;box-shadow:0 10px 30px rgba(17,24,39,.14);padding:6px;display:flex;flex-direction:column;box-sizing:border-box}
.dk-per-opt{all:unset;box-sizing:border-box;display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:8px;font-size:13px;color:#111827;cursor:pointer}
.dk-per-opt:hover{background:#f3f6fb}
.dk-per-opt.is-on{font-weight:600}
.dk-per-opt svg{width:15px;height:15px;color:#2f4a8a;flex:none}
.dk-per-tick{width:15px;height:15px;flex:none}
.dk-per-dates{display:flex;flex-direction:column;gap:8px;padding:10px;border-top:1px solid #eef0f4;margin-top:6px}
.dk-per-dates label{display:flex;justify-content:space-between;align-items:center;font-size:12.5px;color:#6b7280}
.dk-per-dates input{border:1px solid #d6dbe4;border-radius:8px;padding:0 8px;height:34px;width:150px;font:inherit;font-size:13px;color:#111827;background:#fff;box-sizing:border-box}
.dk-per-wrap .tv-sync{width:36px;height:36px;min-width:36px}

/* round 77: campaign list has no checkbox column (no bulk actions) */
.cp-table .ds-sticky-l2{left:0}

/* round 78: compact campaign overview, definitions live in tooltips only */
.dk-ov{padding:12px 16px}
.dk-ov .dk-p2-head{margin-bottom:8px}
.dk-ov-row{gap:8px}
.dk-ov-item{padding:10px 14px}
.dk-ov-item b{font-size:22px;line-height:1.1}

/* round 79: campaign analytics as a native table (no iframe, no CDN); expanded rows share the same columns */
.ana-card{border:1px solid #e5e7eb;border-radius:12px;background:#fff;overflow:hidden}
.ana-scroll{overflow-x:auto}
.ana-table{width:100%;min-width:760px;border-collapse:collapse;table-layout:fixed;font-size:13px;color:#374151;font-variant-numeric:tabular-nums}
.ana-table col.ana-c1{width:64px}.ana-table col.ana-c2{width:92px}.ana-table col.ana-c3{width:92px}.ana-table col.ana-c4{width:76px}
.ana-table thead th{height:40px;padding:0 14px;background:#f1f4fa;color:#4b5563;font-weight:500;font-size:12px;text-align:right;white-space:nowrap;border-bottom:1px solid #e5e7eb}
.ana-table thead th.ana-l{text-align:left}
.ana-table td{height:52px;padding:0 14px;text-align:right;border-bottom:1px solid #eef0f4;white-space:nowrap;vertical-align:middle}
.ana-table td:first-child{text-align:left;white-space:normal}
.ana-table tr:last-child td{border-bottom:0}
.ana-strong{font-weight:600;color:#111827}
.ana-mute{color:#6b7280}
.ana-row{cursor:pointer}
.ana-row:hover td{background:#f8fafc}
.ana-row.is-open td{background:#F8FAFF}
.ana-cell{display:flex;align-items:center;gap:10px;min-width:0}
.ana-min{min-width:0}
.ana-name{font-size:13px;font-weight:500;color:#1f2937;line-height:1.3;overflow:hidden;text-overflow:ellipsis}
.ana-sub{font-size:11.5px;color:#9ca3af;line-height:1.35;overflow:hidden;text-overflow:ellipsis}
.ana-av{width:30px;height:30px;border-radius:50%;color:#fff;font-size:11px;font-weight:600;display:flex;align-items:center;justify-content:center;flex:none}
.ana-chev{display:inline-flex;width:14px;flex:none;color:#9ca3af;transition:transform 120ms}
.ana-chev svg{width:12px;height:12px}
.ana-row.is-open .ana-chev{transform:rotate(90deg)}
.ana-tag{display:inline-block;padding:1px 6px;border-radius:4px;font-size:11px;background:#f3f4f6;color:#4b5563;margin-right:2px}
.ana-child{display:none}
.ana-child.is-open{display:table-row}
.ana-child td{height:46px;background:#fafbfc;font-size:12.5px}
.ana-child td:first-child{padding-left:42px}
.ana-play{width:24px;height:24px;border-radius:6px;background:#eef1f7;color:#9ca3af;display:flex;align-items:center;justify-content:center;flex:none}
.ana-play svg{width:9px;height:9px}
.ana-total td{height:44px;background:#fafbfc;font-weight:600;color:#111827}
.ana-total td:first-child{font-weight:600}
.ana-bar{display:flex;justify-content:flex-end;align-items:center;gap:8px;margin-bottom:12px}
.ana-date{display:inline-flex;align-items:center;height:32px;padding:0 12px;border:1px solid #bfd0f0;border-radius:8px;background:#eef4ff;color:#2f4a8a;font-size:13px;font-weight:500;white-space:nowrap}

/* round 80: dashboard campaign selector beside date range; accordion overview; single campaign insights and creator table */
.dk-head-actions{flex-wrap:wrap}
.dk-acc>summary{list-style:none;cursor:pointer}
.dk-acc>summary::-webkit-details-marker{display:none}
.dk-acc-h{display:flex;align-items:center;gap:10px}
.dk-acc-chev{margin-left:auto;display:inline-flex;color:#6b7280;transition:transform 120ms}
.dk-acc-chev svg{width:14px;height:14px}
.dk-acc[open] .dk-acc-chev{transform:rotate(180deg)}
.dk-acc[open]>summary{margin-bottom:8px}
.dk-ov-static{cursor:default}
.dk-ov-static:hover{background:transparent}
.cp-ins-card,.cp-creators{margin-top:12px}
.cp-ins{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}
.cp-ins-item{padding:12px 14px;border:1px solid #e5e7eb;border-radius:10px;background:#fff}
.cp-ins-t{font-size:12px;color:#6b7280}
.cp-ins-v{font-size:18px;font-weight:600;color:#111827;margin-top:2px}
.cp-ins-d{font-size:12px;color:#6b7280;margin-top:2px}

/* round 81: views trend series switch, boost ticks; overview filters and post table */
.vg-seg{margin-left:auto}
.vg-seg button{font-size:12px}
.vg-boost line{stroke:#d97706;stroke-width:2;stroke-linecap:round}
.cp-ovf{margin:0 0 12px}
.cp-posts{margin-top:12px}
.cp-posts .ct-post-cell{min-width:200px}

/* round 82: KPI row has four cards now (Published posts moved to overview) */
.dk-kpis{grid-template-columns:repeat(4,minmax(0,1fr))}
@media (max-width:1180px){.dk-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:820px){.dk-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}

/* round 83: creator picker in campaign dialogs is a table of the shortlist with all columns */
.dlg-ct{width:100%}
.dlg-ct-scroll{max-height:340px}
.dlg-ct tr.is-sel td{background:#F5F8FF}
.modal:has(.dlg-ct){width:min(1120px,calc(100vw - 32px));max-width:none}
.dlg-ct table{min-width:900px}

/* round 84: bar rows fit their card; concept / product rows open a side panel; side panel tabs and stats */
.dk-row2>.ds-card{min-width:0}
.dk-hb{grid-template-columns:minmax(0,130px) minmax(40px,1fr) auto auto;gap:10px}
.dk-hb small,.dk-rr-meta span{white-space:nowrap}
.dk-hb.is-click,.dk-rr.is-click{cursor:pointer;border-radius:8px}
.dk-hb.is-click:hover,.dk-rr.is-click:hover{background:#f5f7fc}
.dk-hb.is-click:focus-visible,.dk-rr.is-click:focus-visible{outline:2px solid #3b49c9;outline-offset:2px}
.dk-side-tabs{margin-bottom:16px}
.dk-side-stats{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-bottom:12px}
.dk-side-stat{display:flex;flex-direction:column;gap:4px}
.dk-side-split{margin-bottom:12px;display:flex;flex-direction:column;gap:8px}
.dk-side-row{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:12px;font-size:13px;padding:6px 0;border-bottom:1px solid #eef0f4}
.dk-side-row small{color:#6b7280}

/* round 85: campaign overview strip uses the dashboard overview panel */
.cp-ov{margin-bottom:12px}
.cp-ov .dk-ov-row{grid-template-columns:repeat(3,minmax(0,1fr))}
@media (max-width:820px){.cp-ov .dk-ov-row{grid-template-columns:repeat(2,minmax(0,1fr))}}
.cp-ov .dk-ov-row{grid-template-columns:repeat(6,minmax(0,1fr))}
@media (max-width:1180px){.cp-ov .dk-ov-row{grid-template-columns:repeat(3,minmax(0,1fr))}}

/* round 86: campaign overview: timeline and views trend side by side; gender, location, sentiment row */
.cp-tl{align-items:stretch}
.cp-tl>.ds-card{min-width:0;height:100%}
.cp-three{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:12px}
@media (max-width:1000px){.cp-three{grid-template-columns:1fr}}
.dk-empty-note{font-size:13px;color:#6b7280;margin:12px 0 0;line-height:1.5}

/* round 87: campaign overview header is one row: data note, date range, refresh, filters */
.cp-hdrbar{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin:0 0 16px}
.cp-hdrbar>.tv-sub{margin:0 6px 0 0;white-space:nowrap}
.cp-hdrbar>.tv-ctrl{margin:0}
.cp-hdrbar>.ds-filter{margin:0}

/* round 88: sentiment card sits beside Needs attention on the dashboard */
.dk-alerts-row{display:grid;grid-template-columns:minmax(0,2fr) minmax(260px,1fr);gap:14px;align-items:stretch;margin-bottom:14px}
.dk-alerts-row>.ds-card{min-width:0;margin:0}
.dk-alerts-row .dk-sent{display:flex;flex-direction:column}
@media (max-width:1000px){.dk-alerts-row{grid-template-columns:1fr}}

/* round 89: campaign header: filters on the left, date range and refresh on the right */
.cp-hdrbar{justify-content:space-between;gap:10px 16px}
.cp-hdr-l{display:flex;flex-wrap:wrap;align-items:center;gap:10px}
.cp-hdr-r{display:flex;align-items:center;gap:10px;margin-left:auto;flex-wrap:wrap}
.cp-hdr-r>.tv-ctrl{margin:0}

/* round 90: equal-height, top-aligned cards in the campaign overview rows */
.cp-two{align-items:stretch}
.cp-two>.ds-card,.cp-two>.sv{min-width:0;height:100%;margin:0;box-sizing:border-box}
.cp-two .sv{display:flex;flex-direction:column}
.cp-two .sv .sv-rows{flex:1}
.cp-tl>*{height:100%;box-sizing:border-box}

/* round 91: analytics group-by tabs with counts; group tabs and Boosted / date on one row; summary line */
.ana-top{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;margin:0 0 14px}
.ana-top .ana-bar{margin:0;justify-content:flex-end;flex-wrap:nowrap}
.ana-seg button{display:inline-flex;align-items:center;gap:6px}
.ana-seg button span{font-size:11px;font-weight:600;padding:1px 7px;border-radius:999px;background:#e5e7eb;color:#4b5563}
.ana-seg button.on span{background:#1e3a8a;color:#fff}
.ana-sum{display:flex;flex-wrap:wrap;gap:6px 22px;font-size:13px;color:#6b7280;margin:0 0 12px}
.ana-sum b{color:#111827;font-weight:600}

/* round 92: create-campaign dialog: sections, source toggle, shortlist picker, lighter table */
.cc-form{display:flex;flex-direction:column;gap:0}
.cc-sec{border-top:1px solid #eef0f4;padding-top:18px;margin-top:18px}
.cc-sec:first-child{border-top:0;padding-top:0;margin-top:0}
.cc-sec h4{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:13px;font-weight:600;color:#111827;margin:0 0 14px}
.cc-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px 16px}
.cc-grid .ds-field{margin:0}
.cc-count{font-size:12px;font-weight:400;color:#6b7280}
.cc-head{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:12px}
.cc-toggle{display:inline-flex;background:#f3f4f6;border-radius:8px;padding:3px;gap:2px}
.cc-toggle button{border:0;background:transparent;padding:6px 12px;border-radius:6px;font:inherit;font-size:13px;color:#4b5563;cursor:pointer}
.cc-toggle button.on{background:#fff;color:#111827;font-weight:600;box-shadow:0 1px 2px rgba(17,24,39,.08)}
.cc-plan{height:34px;border:1px solid #d1d5db;border-radius:8px;padding:0 10px;font:inherit;font-size:13px;color:#111827;background:#fff;min-width:260px}
.cc-note{font-size:13px;color:#6b7280}
.cc-search{height:36px;width:100%;box-sizing:border-box;border:1px solid #d1d5db;border-radius:8px;padding:0 12px;font:inherit;font-size:13px;margin-bottom:12px}
.cc-search:focus{outline:none;border-color:#3b49c9;box-shadow:0 0 0 3px rgba(59,73,201,.12)}
.dlg-ct{border:1px solid #eef0f4;border-radius:10px;overflow:hidden}
.dlg-ct table{min-width:0;width:100%}
.dlg-ct thead th{background:#f9fafb;font-size:12px;color:#6b7280;font-weight:500}
.dlg-ct tbody td{padding-top:10px;padding-bottom:10px}
.dlg-ct tr.is-sel td{background:#f5f7ff}
.modal:has(.cc-form){width:min(1040px,calc(100vw - 32px));max-width:none}

/* round 93: campaign overview: no stretched empty space; donut beside its legend; tidy pipeline header */
.cp-two>.dk-compact{display:flex;flex-direction:column}
.cp-split-row{flex:1;display:flex;align-items:center;justify-content:center;gap:24px;flex-wrap:wrap}
.cp-split-row .dk-donut-wrap{flex:none}
.cp-split-row .dk-list{flex:1;min-width:200px}
.cov-head{align-items:center}
.cov-head .ds-section-title small{font-size:13px;font-weight:500;color:#6b7280;margin-left:8px}
.cp-split-row .dk-donut-wrap{margin:0}
.cp-split-row .dk-list{margin-top:0;align-self:center}

/* round 94: create-campaign dialog fills its width; no dead column */
.ds-form>.cc-form{grid-column:1/-1;width:100%;min-width:0}
.cc-grid>.ds-field:first-child{grid-column:1/-1}

/* round 95: create-campaign modal is shorter; creator table scrolls inside it */
.modal:has(.cc-form){max-height:calc(100vh - 48px);display:flex;flex-direction:column}
.modal:has(.cc-form)>*:not(header):not(footer){min-height:0}
.modal:has(.cc-form) .dlg-ct{max-height:min(300px,40vh);overflow:auto}
.modal:has(.cc-form) .ds-page{flex:1 1 auto;min-height:0;overflow-y:auto}
.modal:has(.cc-form) .dlg-ct{max-height:240px}

/* round 96: narrower create-campaign modal */
.modal:has(.cc-form){width:min(860px,calc(100vw - 32px))}

/* round 97: analytics summary as stat cards; single Cancel in dialogs */
.ana-sum{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:0 0 12px}
.ana-stat{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:12px 16px;display:flex;flex-direction:column;gap:2px;min-width:0}
.ana-stat small{font-size:12px;color:#6b7280}
.ana-stat b{font-size:20px;font-weight:600;color:#111827;font-variant-numeric:tabular-nums;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ana-stat span{font-size:12px;color:#6b7280}
@media (max-width:640px){.ana-sum{grid-template-columns:repeat(2,minmax(0,1fr))}}

/* round 98: campaign plan form embedded under the Brief tab, two columns like the dialog */
.cb-plan{margin-top:14px}
.pl-embed{display:grid;grid-template-columns:minmax(0,1fr) 320px;border:1px solid #e5e7eb;border-radius:12px;overflow:hidden;margin-top:12px}
.pl-embed .pl-left{padding:20px 24px;min-width:0;overflow:visible}
.pl-embed .pl-right{padding:20px;background:#f8fafc;border-left:1px solid #eef0f4;min-width:0;overflow:visible;max-height:none}
@media (max-width:900px){.pl-embed{grid-template-columns:1fr}.pl-embed .pl-right{border-left:0;border-top:1px solid #eef0f4}}

/* round 99: campaign overview split card fills its height: larger donut stacked over its legend */
.cp-split-row{flex-direction:column;justify-content:center;gap:18px;align-items:stretch}
.cp-split-row .dk-donut-wrap{width:240px;height:240px;margin:0 auto}
.cp-split-row .dk-list{flex:none;width:100%;max-width:360px;margin:0 auto}

/* round 100: creator side panel chips + Open profile live in the drawer header; link creators uses My creators table */
.cq-chips--head{display:inline-flex;flex-wrap:wrap;gap:6px;align-items:center}
.ds-drawer-actions .ds-btn{white-space:nowrap}
.link-wrap{max-height:52vh;overflow:auto}
.modal:has(#linkTbl){width:min(780px,calc(100vw - 32px));max-width:none}

/* round 101: analytics KPI icons, Boosted only checkbox, plan sections shown open */
.ana-stat{position:relative}
.ana-ico{display:flex;align-items:center;justify-content:center;width:30px;height:30px;border-radius:8px;background:#eef2ff;color:#1e40af;margin-bottom:6px;font-style:normal}
.ana-chk{display:inline-flex;align-items:center;gap:8px;font-size:13px;color:#111827;cursor:pointer;user-select:none;border:1px solid #d1d5db;border-radius:8px;padding:6px 12px;background:#fff}
.ana-chk input{width:16px;height:16px;accent-color:#1e40af;margin:0;cursor:pointer}
.ana-bar{align-items:center}
.pl-embed .pl-sec .pl-chev{display:none}

/* round 102: campaign content can show cards or table */
.ct-cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:14px;margin-top:12px}
.ct-card{padding:14px 16px;cursor:pointer;display:flex;flex-direction:column;gap:10px;min-width:0}
.ct-card:hover{border-color:#c7d2fe}
.ct-card-top{display:flex;align-items:flex-start;gap:10px}
.ct-card-id{display:flex;flex-direction:column;gap:2px;min-width:0;flex:1}
.ct-card-id .ct-product{font-size:13px;color:#111827;font-weight:500}
.ct-card-row{display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:13px;color:#6b7280}
.ct-card-stats{display:grid;grid-template-columns:1fr 1fr;gap:8px 12px;border-top:1px solid #eef0f4;padding-top:10px}
.ct-card-stats small{display:block;font-size:11px;color:#6b7280}
.ct-card-stats b{font-size:14px;color:#111827;font-weight:600;font-variant-numeric:tabular-nums}
.ct-card-foot{display:flex;align-items:center;gap:8px;flex-wrap:wrap}

/* round 103: campaign plan embed: no outer border, sections separated by dividers */
.cb-plan{border:0;box-shadow:none;background:transparent;padding:0;margin-top:0}
.pl-embed{border:0;border-radius:0;overflow:visible;display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:0;margin-top:0}
.pl-embed .pl-left{padding:0 28px 0 0}
.pl-embed .pl-right{padding:0 0 0 28px;background:transparent;border-left:1px solid #eef0f4;border-top:0}
.pl-embed .pl-sec{border-top:1px solid #eef0f4;padding:20px 0}
.pl-embed .pl-sec:first-child{border-top:0;padding-top:0}
.pl-embed .pl-sh{pointer-events:none}
.pl-embed .pl-sec{border:0;box-shadow:none;margin:0}
.pl-embed .pl-sec+.pl-sec{border-top:1px solid #eef0f4;margin-top:20px;padding-top:20px}
.pl-embed .pl-sec .pl-sh{border:0}
.pl-embed .pl-right{overflow:hidden}
.pl-embed .pl-right{padding:0 16px 0 28px}

/* ── Campaign overview, creators and header (round 52) ── */
.vg{padding:16px 18px;margin-bottom:14px}
.vg-head{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;margin-bottom:6px}
.vg-svg{display:block;width:100%;height:auto;overflow:visible}
.vg-grid{stroke:#eceef3;stroke-width:1}
.vg-tick{font-size:12px;fill:#6b7280}
.vg-end{font-size:12px;font-weight:600;fill:#111827}
.vg-line{stroke:#3d4fb8;stroke-width:2.2;stroke-linejoin:round}
.vg-area{fill:#3d4fb8;opacity:.12}
.vg-dot{fill:#3d4fb8}
.cp-two{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:14px;align-items:start}
@media (max-width:900px){.cp-two{grid-template-columns:1fr}}
.sv{padding:16px 18px}
.sv-total{display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;margin:6px 0 8px}
.sv-total b{font-size:22px;color:#111827}
.sv-total span{font-size:13px;color:#6b7280}
.sv-bar{margin-bottom:10px}
.sv-rows{display:flex;flex-direction:column;max-height:300px;overflow:auto}
.sv-row{display:grid;grid-template-columns:minmax(0,1fr) auto 90px;gap:12px;align-items:center;padding:8px 0;border-top:1px solid #eef0f4;font-size:13px}
.sv-who{display:flex;flex-direction:column;min-width:0;color:#111827}
.sv-who small{color:#6b7280;font-size:12px}
.sv-amt{font-variant-numeric:tabular-nums;font-weight:600;color:#111827}
.sv-share{height:6px;border-radius:99px;background:#eef1f6;overflow:hidden}
.sv-share i{display:block;height:100%;background:#d69e2e;border-radius:99px}
.cr-cost{display:inline-flex;align-items:center;gap:2px}
