.dk-alerts-row>.ds-card{min-width:0;margin:0}
.dk-alerts-row .dk-sent{display:flex;flex-direction:column}
@media (max-width:1000px){.dk-alerts-row{grid-template-columns:1fr}}

/* round 89: campaign header: filters on the left, date range and refresh on the right */
.cp-hdrbar{justify-content:space-between;gap:10px 16px}
.cp-hdr-l{display:flex;flex-wrap:wrap;align-items:center;gap:10px}
.cp-hdr-r{display:flex;align-items:center;gap:10px;margin-left:auto;flex-wrap:wrap}
.cp-hdr-r>.tv-ctrl{margin:0}

/* round 90: equal-height, top-aligned cards in the campaign overview rows */
.cp-two{align-items:stretch}
.cp-two>.ds-card,.cp-two>.sv{min-width:0;height:100%;margin:0;box-sizing:border-box}
.cp-two .sv{display:flex;flex-direction:column}
.cp-two .sv .sv-rows{flex:1}
.cp-tl>*{height:100%;box-sizing:border-box}

/* round 91: analytics group-by tabs with counts; group tabs and Boosted / date on one row; summary line */
.ana-top{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;margin:0 0 14px}
.ana-top .ana-bar{margin:0;justify-content:flex-end;flex-wrap:nowrap}
.ana-seg button{display:inline-flex;align-items:center;gap:6px}
.ana-seg button span{font-size:11px;font-weight:600;padding:1px 7px;border-radius:999px;background:#e5e7eb;color:#4b5563}
.ana-seg button.on span{background:#1e3a8a;color:#fff}
.ana-sum{display:flex;flex-wrap:wrap;gap:6px 22px;font-size:13px;color:#6b7280;margin:0 0 12px}
.ana-sum b{color:#111827;font-weight:600}

/* round 92: create-campaign dialog: sections, source toggle, shortlist picker, lighter table */
.cc-form{display:flex;flex-direction:column;gap:0}
.cc-sec{border-top:1px solid #eef0f4;padding-top:18px;margin-top:18px}
.cc-sec:first-child{border-top:0;padding-top:0;margin-top:0}
.cc-sec h4{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:13px;font-weight:600;color:#111827;margin:0 0 14px}
.cc-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px 16px}
.cc-grid .ds-field{margin:0}
.cc-count{font-size:12px;font-weight:400;color:#6b7280}
.cc-head{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:12px}
.cc-toggle{display:inline-flex;background:#f3f4f6;border-radius:8px;padding:3px;gap:2px}
.cc-toggle button{border:0;background:transparent;padding:6px 12px;border-radius:6px;font:inherit;font-size:13px;color:#4b5563;cursor:pointer}
.cc-toggle button.on{background:#fff;color:#111827;font-weight:600;box-shadow:0 1px 2px rgba(17,24,39,.08)}
.cc-plan{height:34px;border:1px solid #d1d5db;border-radius:8px;padding:0 10px;font:inherit;font-size:13px;color:#111827;background:#fff;min-width:260px}
.cc-note{font-size:13px;color:#6b7280}
.cc-search{height:36px;width:100%;box-sizing:border-box;border:1px solid #d1d5db;border-radius:8px;padding:0 12px;font:inherit;font-size:13px;margin-bottom:12px}
.cc-search:focus{outline:none;border-color:#3b49c9;box-shadow:0 0 0 3px rgba(59,73,201,.12)}
.dlg-ct{border:1px solid #eef0f4;border-radius:10px;overflow:hidden}
.dlg-ct table{min-width:0;width:100%}
.dlg-ct thead th{background:#f9fafb;font-size:12px;color:#6b7280;font-weight:500}
.dlg-ct tbody td{padding-top:10px;padding-bottom:10px}
.dlg-ct tr.is-sel td{background:#f5f7ff}
.modal:has(.cc-form){width:min(1040px,calc(100vw - 32px));max-width:none}

/* round 93: campaign overview: no stretched empty space; donut beside its legend; tidy pipeline header */
.cp-two>.dk-compact{display:flex;flex-direction:column}
.cp-split-row{flex:1;display:flex;align-items:center;justify-content:center;gap:24px;flex-wrap:wrap}
.cp-split-row .dk-donut-wrap{flex:none}
.cp-split-row .dk-list{flex:1;min-width:200px}
.cov-head{align-items:center}
.cov-head .ds-section-title small{font-size:13px;font-weight:500;color:#6b7280;margin-left:8px}
.cp-split-row .dk-donut-wrap{margin:0}
.cp-split-row .dk-list{margin-top:0;align-self:center}

/* round 94: create-campaign dialog fills its width; no dead column */
.ds-form>.cc-form{grid-column:1/-1;width:100%;min-width:0}
.cc-grid>.ds-field:first-child{grid-column:1/-1}

/* round 95: create-campaign modal is shorter; creator table scrolls inside it */
.modal:has(.cc-form){max-height:calc(100vh - 48px);display:flex;flex-direction:column}
.modal:has(.cc-form)>*:not(header):not(footer){min-height:0}
.modal:has(.cc-form) .dlg-ct{max-height:min(300px,40vh);overflow:auto}
.modal:has(.cc-form) .ds-page{flex:1 1 auto;min-height:0;overflow-y:auto}
.modal:has(.cc-form) .dlg-ct{max-height:240px}

/* round 96: narrower create-campaign modal */
.modal:has(.cc-form){width:min(860px,calc(100vw - 32px))}

/* round 97: analytics summary as stat cards; single Cancel in dialogs */
.ana-sum{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:0 0 12px}
.ana-stat{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:12px 16px;display:flex;flex-direction:column;gap:2px;min-width:0}
.ana-stat small{font-size:12px;color:#6b7280}
.ana-stat b{font-size:20px;font-weight:600;color:#111827;font-variant-numeric:tabular-nums;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ana-stat span{font-size:12px;color:#6b7280}
@media (max-width:640px){.ana-sum{grid-template-columns:repeat(2,minmax(0,1fr))}}

/* round 98: campaign plan form embedded under the Brief tab, two columns like the dialog */
.cb-plan{margin-top:14px}
.pl-embed{display:grid;grid-template-columns:minmax(0,1fr) 320px;border:1px solid #e5e7eb;border-radius:12px;overflow:hidden;margin-top:12px}
.pl-embed .pl-left{padding:20px 24px;min-width:0;overflow:visible}
.pl-embed .pl-right{padding:20px;background:#f8fafc;border-left:1px solid #eef0f4;min-width:0;overflow:visible;max-height:none}
@media (max-width:900px){.pl-embed{grid-template-columns:1fr}.pl-embed .pl-right{border-left:0;border-top:1px solid #eef0f4}}

/* round 99: campaign overview split card fills its height: larger donut stacked over its legend */
.cp-split-row{flex-direction:column;justify-content:center;gap:18px;align-items:stretch}
.cp-split-row .dk-donut-wrap{width:240px;height:240px;margin:0 auto}
.cp-split-row .dk-list{flex:none;width:100%;max-width:360px;margin:0 auto}

/* round 100: creator side panel chips + Open profile live in the drawer header; link creators uses My creators table */
.cq-chips--head{display:inline-flex;flex-wrap:wrap;gap:6px;align-items:center}
.ds-drawer-actions .ds-btn{white-space:nowrap}
.link-wrap{max-height:52vh;overflow:auto}
.modal:has(#linkTbl){width:min(780px,calc(100vw - 32px));max-width:none}

/* round 101: analytics KPI icons, Boosted only checkbox, plan sections shown open */
.ana-stat{position:relative}
.ana-ico{display:flex;align-items:center;justify-content:center;width:30px;height:30px;border-radius:8px;background:#eef2ff;color:#1e40af;margin-bottom:6px;font-style:normal}
.ana-chk{display:inline-flex;align-items:center;gap:8px;font-size:13px;color:#111827;cursor:pointer;user-select:none;border:1px solid #d1d5db;border-radius:8px;padding:6px 12px;background:#fff}
.ana-chk input{width:16px;height:16px;accent-color:#1e40af;margin:0;cursor:pointer}
.ana-bar{align-items:center}
.pl-embed .pl-sec .pl-chev{display:none}

/* round 102: campaign content can show cards or table */
.ct-cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:14px;margin-top:12px}
.ct-card{padding:14px 16px;cursor:pointer;display:flex;flex-direction:column;gap:10px;min-width:0}
.ct-card:hover{border-color:#c7d2fe}
.ct-card-top{display:flex;align-items:flex-start;gap:10px}
.ct-card-id{display:flex;flex-direction:column;gap:2px;min-width:0;flex:1}
.ct-card-id .ct-product{font-size:13px;color:#111827;font-weight:500}
.ct-card-row{display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:13px;color:#6b7280}
.ct-card-stats{display:grid;grid-template-columns:1fr 1fr;gap:8px 12px;border-top:1px solid #eef0f4;padding-top:10px}
.ct-card-stats small{display:block;font-size:11px;color:#6b7280}
.ct-card-stats b{font-size:14px;color:#111827;font-weight:600;font-variant-numeric:tabular-nums}
.ct-card-foot{display:flex;align-items:center;gap:8px;flex-wrap:wrap}

/* round 103: campaign plan embed: no outer border, sections separated by dividers */
.cb-plan{border:0;box-shadow:none;background:transparent;padding:0;margin-top:0}
.pl-embed{border:0;border-radius:0;overflow:visible;display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:0;margin-top:0}
.pl-embed .pl-left{padding:0 28px 0 0}
.pl-embed .pl-right{padding:0 0 0 28px;background:transparent;border-left:1px solid #eef0f4;border-top:0}
.pl-embed .pl-sec{border-top:1px solid #eef0f4;padding:20px 0}
.pl-embed .pl-sec:first-child{border-top:0;padding-top:0}
.pl-embed .pl-sh{pointer-events:none}
.pl-embed .pl-sec{border:0;box-shadow:none;margin:0}
.pl-embed .pl-sec+.pl-sec{border-top:1px solid #eef0f4;margin-top:20px;padding-top:20px}
.pl-embed .pl-sec .pl-sh{border:0}
.pl-embed .pl-right{overflow:hidden}
.pl-embed .pl-right{padding:0 16px 0 28px}

/* round 104: Link creators uses the Add Creators layout, sized smaller */
.addn.link-addn{width:min(680px,calc(100vw - 32px));max-height:min(600px,calc(100vh - 48px))}
.link-addn .addn-body{min-height:0}
.link-addn .addn-pane{min-height:0;overflow:auto}
.link-addn .link-wrap{max-height:280px;overflow:auto;margin-top:10px}
.link-addn .link-search{margin-top:6px}
.addn-warn{color:#b45309}

/* ── Campaign overview, creators and header (round 52) ── */
.vg{padding:16px 18px;margin-bottom:14px}
.vg-head{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;margin-bottom:6px}
.vg-svg{display:block;width:100%;height:auto;overflow:visible}
.vg-grid{stroke:#eceef3;stroke-width:1}
.vg-tick{font-size:12px;fill:#6b7280}
.vg-end{font-size:12px;font-weight:600;fill:#111827}
.vg-line{stroke:#3d4fb8;stroke-width:2.2;stroke-linejoin:round}
.vg-area{fill:#3d4fb8;opacity:.12}
.vg-dot{fill:#3d4fb8}
.cp-two{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:14px;align-items:start}
@media (max-width:900px){.cp-two{grid-template-columns:1fr}}
.sv{padding:16px 18px}
.sv-total{display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;margin:6px 0 8px}
.sv-total b{font-size:22px;color:#111827}
.sv-total span{font-size:13px;color:#6b7280}
.sv-bar{margin-bottom:10px}
.sv-rows{display:flex;flex-direction:column;max-height:300px;overflow:auto}
.sv-row{display:grid;grid-template-columns:minmax(0,1fr) auto 90px;gap:12px;align-items:center;padding:8px 0;border-top:1px solid #eef0f4;font-size:13px}
.sv-who{display:flex;flex-direction:column;min-width:0;color:#111827}
.sv-who small{color:#6b7280;font-size:12px}
.sv-amt{font-variant-numeric:tabular-nums;font-weight:600;color:#111827}
.sv-share{height:6px;border-radius:99px;background:#eef1f6;overflow:hidden}
.sv-share i{display:block;height:100%;background:#d69e2e;border-radius:99px}
.cr-cost{display:inline-flex;align-items:center;gap:2px}
.cr-cost input{width:104px;text-align:right;padding:6px 8px;border:1px solid #d6dbe4;border-radius:8px;font:inherit;background:#fff}
.cr-cost input:focus{outline:2px solid #1247af;outline-offset:1px}
.cr-rupee{color:#6b7280}
.cr-owner{min-width:118px}
.cr-wrap{overflow-x:auto}
.cr-table{min-width:1180px}
.cr-table td:last-child,.cr-table th:last-child{position:static}
/* ── Unified avatars: 24px rounded square, light gray, like the campaign analytics thumbnails ── */
.ds-avatar,.ds-avatar--sm,.ds-avatar-stack .ds-avatar,.ds-avatar.ds-spoc,.cq-av{width:24px !important;height:24px !important;min-width:24px;border-radius:50% !important;color:#fff !important;font-size:10px !important;font-weight:600 !important;letter-spacing:0 !important;border:0 !important;box-shadow:none !important;margin:0 !important;box-sizing:border-box !important}
.ds-avatar-stack .ds-avatar{margin-left:-4px !important;border:1px solid #fff !important}
.ds-avatar-stack .ds-avatar:first-child{margin-left:0 !important}
.ds-avatar-more{width:24px;height:24px;border-radius:50%;background:#f3f4f6;color:#6b7280;font-size:10px;border:1px solid #e5e7eb}
/* ── Post timeline card (round 54): one period control, area chart, hover detail ── */
.tv{margin:0 0 16px;padding:18px;border:1px solid #e5e7eb;border-radius:14px;background:#fff}
.tv-head{display:flex;justify-content:space-between;align-items:flex-start;gap:14px;flex-wrap:wrap;margin-bottom:14px}
.tv-title{font-size:15px;font-weight:600;color:#111827}
.tv-sub{margin:3px 0 0;font-size:12.5px;color:#6b7280}
.tv-ctrl{display:flex;align-items:center;gap:6px}
.tv-select{display:inline-flex}
select.tv-select{border:1px solid #d6dbe4;border-radius:8px;padding:7px 12px;font:inherit;font-size:13px;font-weight:600;color:#111827;background:#fff;cursor:pointer}
.tv-nav{width:32px;height:32px;border:1px solid #d6dbe4;border-radius:8px;background:#fff;color:#374151;font-size:16px;cursor:pointer}
.tv-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));border:1px solid #eef0f4;border-radius:10px;margin-bottom:14px}
.tv-kpis>div{padding:12px 14px;display:flex;flex-direction:column;gap:2px;border-right:1px solid #eef0f4;min-width:0}
.tv-kpis>div:last-child{border-right:0}
.tv-kpis>div>span{font-size:12px;color:#6b7280}
.tv-kpis b{font-size:20px;color:#111827;font-variant-numeric:tabular-nums}
.tv-kpis small{font-size:12px;color:#6b7280}
.tv-split{display:flex;height:6px;border-radius:99px;overflow:hidden;background:#eef1f6;margin-top:6px}
.tv-split i{display:block;height:100%}
.tv-org{background:#1f3a68}
.tv-boo{background:#d69e2e}
.tv-chart{position:relative}
.tv-svg{display:block;width:100%;height:auto;overflow:visible}
.tv-area-org{fill:#1f3a68;opacity:.88}
.tv-area-boo{fill:#d69e2e;opacity:.88}
.tv-dot-pt{fill:#fff;stroke:#1f3a68;stroke-width:2}
.tv-hit{fill:transparent;cursor:crosshair}
.tv-hit.is-on{fill:rgba(31,58,104,.07)}
.tv-tip{position:absolute;top:0;width:180px;background:#111827;color:#fff;border-radius:10px;padding:10px 12px;font-size:12px;display:flex;flex-direction:column;gap:3px;box-shadow:0 8px 24px rgba(0,0,0,.18);pointer-events:none;z-index:2}
.tv-tip[hidden]{display:none}
.tv-tip b{font-size:13px}
.tv-tip-split{display:flex;align-items:center;gap:6px}
.tv-tip-split i{width:8px;height:8px;border-radius:2px;display:inline-block}
.tv-legend{display:flex;gap:14px;font-size:12px;color:#4b5563;margin:10px 0 0;flex-wrap:wrap}
.tv-legend span{display:inline-flex;align-items:center;gap:6px}
.tv-legend i{width:10px;height:10px;border-radius:3px;display:inline-block}
.tv-legend .tv-dot{background:#fff;border:2px solid #1f3a68;border-radius:50%;width:9px;height:9px}
.tv-chips{display:flex;gap:6px;overflow-x:auto;padding:12px 0 2px;margin-top:10px;border-top:1px solid #eef0f4}
.tv-chip{flex:none;border:1px solid #e5e7eb;background:#fff;border-radius:99px;padding:5px 11px;font:inherit;font-size:12px;color:#374151;cursor:pointer;white-space:nowrap}
.tv-chip.is-on{background:#1f3a68;border-color:#1f3a68;color:#fff}
.tv-chip small{opacity:.7;margin-left:4px}
.tv-empty{font-size:12.5px;color:#6b7280;margin:8px 0 0}
@media (max-width:640px){.tv-kpis{grid-template-columns:1fr 1fr}}
/* round 55: column chart + top controls block */
.tv-top{margin:0 0 14px}
.tv-top .tv-head{margin-bottom:10px}
.tv-col-org{fill:#1f3a68}
.tv-col-boo{fill:#d69e2e}
/* round 56: dashboard header, KPI cards, compact chart */
.tv-bar{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin:0 0 14px}
.tv-bar .tv-sub{font-size:13px;color:#6b7280}
.tv-ctrl{display:flex;align-items:center;gap:6px;flex-wrap:wrap}
.tv-sync{margin-left:4px}
.tv-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px;border:0;margin:0 0 14px}
.tv-kpis>div{border:1px solid #e5e7eb;border-radius:12px;background:#fff;padding:14px 16px;border-right:1px solid #e5e7eb}
.tv{margin:0 0 14px;padding:16px 18px}
.tv-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;flex-wrap:wrap;margin-bottom:8px}
.tv-legend{margin:4px 0 0}
.tv-chips{padding-top:10px;margin-top:10px}
/* round 57: content table */
.ct-wrap{overflow-x:auto}
.ct-table{min-width:1280px}
.ct-post-cell{display:flex;align-items:center;gap:10px;min-width:0}
.ct-post-meta{display:flex;flex-direction:column;gap:3px;min-width:0;max-width:260px}
.ct-kind{font-size:12.5px;font-weight:600;color:#111827}
.ct-link{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11.5px;color:#6b7280}
.ct-open{align-self:flex-start;margin-top:2px}
.ct-thumb{position:relative;display:inline-flex;align-items:center;justify-content:center;flex:none;color:#fff;border-radius:8px}
.ct-reel{width:34px;height:60px;border-radius:8px}
.ct-post{width:44px;height:44px;border-radius:6px}
.ct-carousel{width:40px;height:50px;border-radius:6px;box-shadow:4px -3px 0 -1px rgba(31,58,104,.22),8px -6px 0 -2px rgba(31,58,104,.12)}
.ct-product{max-width:200px;white-space:normal;font-size:12.5px;color:#374151}
.ct-nocost{font-size:11px;color:#6b7280;background:#f3f4f6;border-radius:99px;padding:2px 8px;white-space:nowrap}
.ct-type{font-size:11.5px;font-weight:600;padding:2px 9px;border-radius:99px;white-space:nowrap}
.ct-type.is-boost{background:#fdf3dc;color:#8a5a00}
.ct-type.is-org{background:#e8edf7;color:#1f3a68}
.ct-product{max-width:none;min-width:190px}
.ct-table{min-width:1400px}
/* round 58: compact post column, square thumbnails with short labels */
.ct-table td{padding-top:8px;padding-bottom:8px}
.ct-post-cell{gap:10px;align-items:center}
.ct-post-meta{max-width:240px;gap:1px;min-width:0}
.ct-kind{font-size:13px;font-weight:600;color:#111827}
.ct-link{font-size:12px;color:#6b7280}
.ct-thumb,.ct-thumb.ct-reel,.ct-thumb.ct-post,.ct-thumb.ct-carousel{width:40px;height:40px;border-radius:8px;box-shadow:none;flex-direction:column;justify-content:flex-end;padding-bottom:4px;font-size:9.5px;font-weight:600;line-height:1;letter-spacing:.02em}
.ct-open{width:28px;height:28px;padding:0;display:inline-flex;align-items:center;justify-content:center;border:1px solid #e5e7eb;border-radius:8px;background:#fff;color:#374151;text-decoration:none;flex:none;margin-left:auto}
.ct-open:hover{background:#f3f4f6;color:#111827}
/* round 59: compact campaign header */
.cdh{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:12px 16px 0;margin:0 0 14px}
.cdh-top{display:flex;align-items:center;gap:12px;min-width:0}
.cdh-top .ds-media{width:40px !important;height:40px !important;flex:none}
.cdh-main{min-width:0;flex:1}
.cdh-title{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.cdh-title h1{font-size:17px;font-weight:600;margin:0;color:#111827}
.cdh-chip{font-size:11.5px;padding:2px 8px;border-radius:99px;background:#f3f4f6;color:#374151;white-space:nowrap}
.cdh-chip.is-ok{background:#e8f7ee;color:#15803d}
.cdh-meta{font-size:12.5px;color:#6b7280;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cdh-actions{display:flex;gap:8px;align-items:center;flex:none}
.cdh-tabs{margin-top:8px}
.cdh-tabs .ds-tabrow{border-bottom:0;margin:0}
.cdh + .ds-plan-tags{display:none}
.ds-page>.crumb{margin:0 0 8px}
@media (max-width:760px){.cdh-actions{width:100%;justify-content:flex-end}.cdh-top{flex-wrap:wrap}}
/* round 60: header sits on the page, no card */
.cdh{background:transparent;border:0;border-radius:0;padding:0;margin:0 0 6px}
.cdh-tabs{margin-top:14px;border-bottom:1px solid #e5e7eb}
.cdh-tabs .ds-tabs{border-bottom:0}
/* round 61: dashboard period, layout, advanced filters, consistent chart text */
.dk-head-actions .ds-btn--icon,.tv-sync{width:36px;height:36px;min-width:36px;padding:0;display:inline-flex;align-items:center;justify-content:center;border-radius:8px}
.tv-ctrl{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
select.tv-select{padding-right:34px;min-width:150px;height:36px;border-radius:8px}
.tv-date{display:inline-flex;align-items:center;gap:6px;font-size:12px;color:#6b7280}
.tv-date input{border:1px solid #d6dbe4;border-radius:8px;padding:0 8px;height:36px;font:inherit;font-size:12.5px;color:#111827;background:#fff}
.tv{font-size:12px}
.tv-title{font-size:14px;font-weight:600}
.tv-sub{font-size:12px;color:#6b7280;margin:2px 0 0}
.tv-legend{font-size:12px}
.tv-frame{display:grid;grid-template-columns:40px minmax(0,1fr);gap:8px;height:240px;margin-top:12px}
.tv-yax{position:relative;height:100%}
.tv-yax span{position:absolute;right:0;transform:translateY(50%);font-size:11px;color:#6b7280;line-height:1;font-variant-numeric:tabular-nums}
.tv-plot{position:relative;height:100%;border-bottom:1px solid #e5e7eb}
.tv-gl{position:absolute;left:0;right:0;height:0;border-top:1px solid #eef0f4}
.tv-cols{position:absolute;inset:0;display:flex}
.tv-col{flex:1;height:100%;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;position:relative;border-radius:4px}
.tv-col:hover,.tv-col.is-on{background:rgba(31,58,104,.06)}
.tv-stk{width:min(28px,62%);display:flex;flex-direction:column;border-radius:4px 4px 0 0;overflow:hidden}
.tv-stk i{display:block}
.tv-stk .tv-boo{background:#d69e2e}
.tv-stk .tv-org{background:#1f3a68}
.tv-xax{display:flex;margin:6px 0 0 48px;font-size:11px;color:#6b7280}
.tv-xax span{flex:1;text-align:center;white-space:nowrap;overflow:visible}
.tv-tip{position:absolute;top:0;z-index:3}
.tv--split{display:grid;grid-template-columns:minmax(0,3fr) minmax(220px,1fr);gap:18px;align-items:stretch}
.tv-main{min-width:0}
.tv-side{display:grid;grid-template-columns:1fr 1fr;gap:10px;align-content:start}
.tv-kpi{border:1px solid #e5e7eb;border-radius:10px;padding:12px 14px;display:flex;flex-direction:column;gap:2px;background:#fff}
.tv-kpi span{font-size:12px;color:#6b7280}
.tv-kpi b{font-size:18px;color:#111827;font-variant-numeric:tabular-nums}
.tv-kpi small{font-size:11.5px;color:#6b7280}
@media (max-width:900px){.tv--split{grid-template-columns:1fr}}
.dk-bar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:0 0 14px;position:relative}
.dk-adv{position:relative}
.dk-adv summary{list-style:none;cursor:pointer}
.dk-adv summary::-webkit-details-marker{display:none}
.dk-adv-btn b{margin-left:4px;background:#1f3a68;color:#fff;border-radius:99px;padding:0 6px;font-size:11px}
.dk-adv-panel{position:absolute;top:calc(100% + 6px);left:0;z-index:30;display:grid;grid-template-columns:repeat(2,minmax(170px,1fr));gap:10px;width:440px;background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:14px;box-shadow:0 12px 32px rgba(0,0,0,.12)}
.dk-bar .ds-filter{padding-right:34px}
/* round 62: Live / Lined up switch and add-posts dialog */
.ct-seg{display:inline-flex;gap:4px;padding:3px;border:1px solid #e5e7eb;border-radius:10px;background:#f7f8fb;margin:0 0 10px}
.ct-seg button{border:0;background:transparent;border-radius:8px;padding:6px 12px;font:inherit;font-size:13px;color:#4b5563;cursor:pointer;display:inline-flex;gap:6px;align-items:center}
.ct-seg button span{font-size:11.5px;color:#6b7280;background:#eef0f4;border-radius:99px;padding:0 7px}
.ct-seg button.on{background:#fff;color:#111827;font-weight:600;box-shadow:0 1px 2px rgba(0,0,0,.08)}
.ct-seg button.on span{background:#1f3a68;color:#fff}
.ap-tabs{display:inline-flex;gap:4px;padding:3px;border:1px solid #e5e7eb;border-radius:10px;margin-bottom:12px}
.ap-tabs button{border:0;background:transparent;border-radius:8px;padding:6px 12px;font:inherit;font-size:13px;color:#4b5563;cursor:pointer}
.ap-tabs button.on{background:#1f3a68;color:#fff}
.ap-csv{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:6px}
.ap-tpl{font-size:12px;background:#f7f8fb;border:1px solid #e5e7eb;border-radius:8px;padding:8px 10px;margin:6px 0 0;overflow:auto}
.ap-actions{margin:6px 0 10px}
.ap-wrap{max-height:320px;overflow:auto;margin-top:10px}
.ap-table{min-width:760px}
.ap-table td{padding:6px 8px}
.ap-sel,.ap-in{height:30px;border:1px solid #d6dbe4;border-radius:7px;padding:0 6px;font:inherit;font-size:12.5px;background:#fff}
.ap-num{width:90px}
.ap-x{width:26px;height:26px;border:1px solid #e5e7eb;border-radius:7px;background:#fff;cursor:pointer;font-size:14px;line-height:1}
.ap-empty{margin-top:10px}
/* round 63: compact spend cell, percentage beside the bar */
.cp-table td{padding-top:8px;padding-bottom:8px}
.cp-spend{min-width:190px}
.cp-spend .cp-prog-txt{font-size:12.5px;line-height:1.3}
.cp-bar-row{display:flex;align-items:center;gap:10px;margin-top:4px}
.cp-bar-row .cp-bar{flex:1;min-width:0;margin:0}
.cp-pct{font-size:12px;font-weight:600;color:#374151;min-width:38px;text-align:right;font-variant-numeric:tabular-nums}
.cp-spend.is-over .cp-pct{color:#b42318}
.cp-spend.is-risk .cp-pct{color:#b45309}

/* round 64: dashboard timeline redesign + plain tertiary links */
.tv{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:18px 20px;margin:0 0 16px;box-shadow:none}
.tv-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;flex-wrap:wrap;margin:0}
.tv-title{font-size:15px;font-weight:600;color:#111827;line-height:1.3}
.tv-sub{font-size:12.5px;color:#6b7280;margin:3px 0 0}
.tv-legend{display:flex;gap:14px;font-size:12px;color:#4b5563;margin:2px 0 0;align-items:center}
.tv-legend span{display:inline-flex;align-items:center;gap:6px}
.tv-legend i{width:10px;height:10px;border-radius:3px;display:inline-block}
.tv-org,.tv-stk .tv-org{background:#374882}
.tv-boo,.tv-stk .tv-boo{background:#7aa2f0}
.tv--split{display:grid;grid-template-columns:minmax(0,3fr) minmax(200px,1fr);gap:0;align-items:stretch}
.tv-main{min-width:0;padding-right:22px;border-right:1px solid #eef0f4}
.tv-frame{display:grid;grid-template-columns:34px minmax(0,1fr);gap:10px;height:240px;margin-top:16px}
.tv-yax{position:relative;height:100%}
.tv-yax span{position:absolute;right:0;transform:translateY(50%);font-size:11px;color:#9ca3af;line-height:1;font-variant-numeric:tabular-nums}
.tv-plot{position:relative;height:100%;border-bottom:1px solid #d6dbe4}
.tv-gl{position:absolute;left:0;right:0;height:0;border-top:1px solid #f0f2f6}
.tv-cols{position:absolute;inset:0;display:flex}
.tv-col{flex:1;height:100%;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;position:relative;border-radius:4px;cursor:default}
.tv-col:hover,.tv-col.is-on{background:#f3f6fc}
.tv-stk{width:min(14px,50%);display:flex;flex-direction:column;border-radius:3px 3px 0 0;overflow:hidden}
.tv-stk i{display:block;min-height:0}
.tv-xax{display:flex;margin:8px 0 0 44px;font-size:11px;color:#6b7280}
.tv-xax span{flex:1;text-align:center;white-space:nowrap;overflow:visible}
.tv-tip{position:absolute;top:0;z-index:3}
.tv-side{display:flex;flex-direction:column;padding-left:22px;gap:0}
.tv-kpi{display:flex;flex-direction:column;gap:2px;padding:14px 0;border:0;border-bottom:1px solid #eef0f4;border-radius:0;background:none}
.tv-kpi:first-child{padding-top:0}
.tv-kpi:last-child{border-bottom:0;padding-bottom:0}
.tv-kpi span{font-size:12px;color:#6b7280}
.tv-kpi b{font-size:20px;font-weight:600;color:#111827;line-height:1.2;font-variant-numeric:tabular-nums}
.tv-kpi small{font-size:12px;color:#6b7280}
.tv-empty{font-size:12.5px;color:#6b7280;margin:10px 0 0}
@media (max-width:900px){
  .tv--split{grid-template-columns:1fr}
  .tv-main{border-right:0;padding-right:0}
  .tv-side{padding-left:0;padding-top:14px;margin-top:14px;border-top:1px solid #eef0f4;display:grid;grid-template-columns:1fr 1fr;column-gap:16px}
  .tv-kpi:nth-child(odd){padding-right:0}
}
.my-link,.my-table tbody .my-link{text-decoration:none}
.my-link:hover,.my-table tbody .my-link:hover{text-decoration:underline}

/* round 67: freeze first and last columns in campaign Creators and Content tables */
.ds-table th.cs-first,.ds-table td.cs-first{position:sticky;left:0;z-index:2;background:#fff}
.ds-table th.cs-first{background:var(--v-head);z-index:3}
.ds-table th.cs-last,.ds-table td.cs-last{position:sticky;right:0;z-index:2;background:#fff}
.ds-table th.cs-last{background:var(--v-head);z-index:3}
.ds-table td.cs-first{box-shadow:6px 0 8px -6px rgba(17,24,39,.22)}
.ds-table td.cs-last{box-shadow:-6px 0 8px -6px rgba(17,24,39,.22);border-left:1px solid var(--v-line-soft)}
.ds-table tbody tr:hover td.cs-first,.ds-table tbody tr:hover td.cs-last{background:var(--v-hover)}

/* round 68: cumulative dashboard per PRD v2 — status row, campaign comparison, pagination */
.dk-status{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:0 0 14px}
.dk-stat{all:unset;box-sizing:border-box;cursor:pointer;background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:14px 16px;display:flex;flex-direction:column;gap:2px;transition:border-color .15s,background .15s}
.dk-stat:hover{border-color:#b8c7e6}
.dk-stat:focus-visible{outline:2px solid #2263d5;outline-offset:2px}
.dk-stat.is-on{border-color:#374882;background:#f3f6fc;box-shadow:inset 0 0 0 1px #374882}
.dk-stat-l{display:inline-flex;align-items:center;gap:6px;font-size:12.5px;color:#4b5563;font-weight:500}
.dk-stat b{font-size:22px;font-weight:600;color:#111827;line-height:1.2;font-variant-numeric:tabular-nums}
.dk-stat small{font-size:12px;color:#6b7280}
.dk-info{width:15px;height:15px;border-radius:50%;border:1px solid #c7ccd6;font-size:10px;font-style:normal;display:inline-flex;align-items:center;justify-content:center;color:#6b7280;cursor:help}
.dk-camps{margin:14px 0}
.dk-camps .ds-table td:first-child{min-width:240px}
@media (max-width:820px){.dk-status{grid-template-columns:repeat(2,minmax(0,1fr))}}
.dk-kpis{grid-template-columns:repeat(5,minmax(0,1fr))}
@media (max-width:1180px){.dk-kpis{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media (max-width:820px){.dk-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}

/* round 69: PRD v2 completion — campaign picker, chips, alerts, aggregated views trend */
.dk-cf{position:relative;display:inline-block}
.dk-cf>summary{list-style:none;cursor:pointer}
.dk-cf>summary::-webkit-details-marker{display:none}
.dk-cf-panel{position:absolute;top:calc(100% + 6px);left:0;z-index:40;width:280px;background:#fff;border:1px solid #e5e7eb;border-radius:12px;box-shadow:0 10px 30px rgba(17,24,39,.14);padding:10px;display:flex;flex-direction:column;gap:8px}
.dk-cf-list{max-height:260px;overflow:auto;display:flex;flex-direction:column;gap:2px}
.dk-cf-item{display:flex;align-items:center;gap:8px;padding:6px;border-radius:6px;font-size:13px;color:#111827;cursor:pointer}
.dk-cf-item:hover{background:#f3f6fc}
.dk-cf-foot{display:flex;justify-content:flex-end;border-top:1px solid #eef0f4;padding-top:8px}
.dk-chips{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.dk-trend-ctl{display:flex;gap:6px;flex-wrap:wrap;align-items:center}
.dk-trend-legend{margin:10px 0 0}
.dk-trend .tv-plot{height:100%}
.dk-trend-svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible;pointer-events:none}
.dk-boost{position:absolute;top:-2px;transform:translateX(-50%);font-size:10px;color:#b7791f;line-height:1;cursor:help}
.dk-boost-key{color:#b7791f;margin-right:2px}
.dk-trend-note{margin:10px 0 0}
.dk-row3{grid-template-columns:repeat(2,minmax(0,1fr))}
@media (max-width:900px){.dk-row3{grid-template-columns:1fr}}
.dk-alerts{margin:14px 0}
.dk-alert-list{display:flex;flex-direction:column;gap:6px}
.dk-alert{display:flex;gap:10px;align-items:baseline;font-size:13px;padding:8px 10px;border-radius:8px;background:#f9fafb;border:1px solid #eef0f4}
.dk-alert-tag{flex:none;font-size:11px;font-weight:600;padding:2px 8px;border-radius:99px;background:#eef1f6;color:#374151}
.dk-alert--warn .dk-alert-tag{background:#fff4df;color:#9a6700}
.dk-alert--bad .dk-alert-tag{background:#fde8e8;color:#b42318}
.dk-alert--info .dk-alert-tag{background:#e8f0fe;color:#2d5bb8}
.dk-alert-t{color:#374151}

/* round 71: layout pass per UX brief — trend + organic pair, breakdown grid, flags, alert reasons */
.dk-pair{display:grid;grid-template-columns:minmax(0,2fr) minmax(260px,1fr);gap:14px;margin:14px 0;align-items:stretch}
.dk-pair>.tv{margin:0;height:100%;box-sizing:border-box}
.dk-org{margin:0;display:flex;flex-direction:column;gap:12px;padding:18px 20px}
.dk-org-body{display:grid;grid-template-columns:140px minmax(0,1fr);gap:18px;align-items:center}
.dk-org-body .dk-donut-wrap{width:140px}
.dk-org-table{width:100%;border-collapse:collapse;font-size:13px}
.dk-org-table th{font-size:12px;color:#6b7280;font-weight:500;text-align:left;padding:0 0 6px}
.dk-org-table td{padding:8px 0;border-top:1px solid #eef0f4;color:#111827}
.dk-org-table .ds-num{text-align:right;font-variant-numeric:tabular-nums}
.dk-org-table .dk-org-total td{font-weight:600;border-top:1px solid #d6dbe4}
.dk-org-table .dk-sw{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:8px;vertical-align:middle}
.dk-org-foot{display:flex;justify-content:space-between;gap:10px;font-size:12.5px;color:#4b5563;border-top:1px solid #eef0f4;padding-top:10px;flex-wrap:wrap}
.dk-org-foot b{color:#111827;font-weight:600}
#dash-breakdowns{grid-template-columns:repeat(3,minmax(0,1fr))}
@media (max-width:1100px){.dk-pair{grid-template-columns:1fr}#dash-breakdowns{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:900px){#dash-breakdowns{grid-template-columns:1fr}}
.dk-flag{display:inline-block;font-size:11px;font-weight:600;padding:2px 8px;border-radius:99px;white-space:nowrap}
.dk-flag--good{background:#e3f6ec;color:#17704a}
.dk-flag--bad{background:#fde8e8;color:#b42318}
.dk-alert-why{display:block;font-size:12px;color:#6b7280;margin-top:2px}
.dk-alert-act{flex:none;margin-left:auto;white-space:nowrap}
.dk-status-note{margin:8px 0 0}
.dk-trend .tv-title,.dk-org .ds-section-title{font-size:14px}
.dk-org-body{grid-template-columns:1fr;gap:12px}
.dk-org-body .dk-donut-wrap{width:120px;margin:0 auto}
.dk-camps .ds-table-wrap{overflow-x:auto}
.dk-camps .ds-table th,.dk-camps .ds-table td{padding-left:10px;padding-right:10px}
.dk-camps .ds-table td:first-child{min-width:200px}
.dk-flag-row{margin-top:4px}

/* round 72: trend card fills its row; lighter tooltip so it does not hide the line */
.dk-trend{display:flex;flex-direction:column}
.dk-trend .tv-chart{flex:1;display:flex;flex-direction:column;min-height:0}
.dk-trend .tv-frame{flex:1;height:auto;min-height:240px}
.dk-trend .tv-tip{background:#fff;color:#111827;border:1px solid #e5e7eb;box-shadow:0 6px 18px rgba(17,24,39,.12);width:176px;padding:9px 11px;font-size:12px;gap:2px}
.dk-trend .tv-tip b{color:#111827}
.dk-trend .tv-tip-split i{width:9px;height:9px}
.dk-trend .tv-col:hover,.dk-trend .tv-col.is-on{background:rgba(55,72,130,.06)}
.dk-org .dk-donut-c b{font-size:17px;white-space:nowrap}
.dk-org .dk-donut-c span{font-size:11px}

/* round 73: campaign overview strip and shared performance strip (no per-metric cards) */
.dk-ov{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:6px 0 0;margin:0 0 10px}
.dk-ov-row{display:grid;grid-template-columns:repeat(4,minmax(0,1fr))}
.dk-ov-item{all:unset;box-sizing:border-box;cursor:pointer;display:flex;flex-direction:column;gap:2px;padding:12px 24px 14px;border-left:1px solid #eef0f4;position:relative}
.dk-ov-item:first-child{border-left:0}
.dk-ov-item:focus-visible{outline:2px solid #2263d5;outline-offset:-2px;border-radius:8px}
.dk-ov-l{font-size:12.5px;color:#6b7280;font-weight:500}
.dk-ov-item b{font-size:30px;font-weight:600;color:#111827;line-height:1.15;font-variant-numeric:tabular-nums}
.dk-ov-s{font-size:11.5px;color:#9ca3af}
.dk-ov-item:hover .dk-ov-l{color:#111827}
.dk-ov-item.is-on::after{content:"";position:absolute;left:24px;right:24px;bottom:0;height:2px;background:#374882;border-radius:2px}
.dk-ov-item.is-on b{color:#374882}
.dk-ov .dk-status-note{margin:0;padding:8px 24px 10px;border-top:1px solid #eef0f4}
.dk-perf{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:12px 0;margin:0 0 14px}
.dk-perf-item{padding:4px 24px;display:flex;flex-direction:column;gap:3px;border-left:1px solid #eef0f4;min-width:0}
.dk-perf-item:first-child{border-left:0}
.dk-perf-l{font-size:12.5px;color:#6b7280;font-weight:500;white-space:nowrap}
.dk-perf-v{font-size:22px;font-weight:600;color:#111827;line-height:1.2;font-variant-numeric:tabular-nums;white-space:nowrap}
.dk-perf-s{font-size:11.5px;color:#9ca3af;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
@media (max-width:1180px){.dk-perf{grid-template-columns:repeat(3,minmax(0,1fr));row-gap:12px}.dk-perf-item:nth-child(4){border-left:0}}
@media (max-width:760px){.dk-ov-row{grid-template-columns:repeat(2,minmax(0,1fr))}.dk-ov-item:nth-child(3){border-left:0}.dk-perf{grid-template-columns:repeat(2,minmax(0,1fr))}.dk-perf-item:nth-child(3){border-left:0}}
.dk-perf-s{white-space:normal;line-height:1.35;overflow:visible;text-overflow:clip}
.dk-perf-l,.dk-perf-v{white-space:normal}

/* round 74: overview + performance as tinted panels (reference style) */
.dk-ov{background:#f3f6fb;border:0;border-radius:14px;padding:16px 20px 18px;margin:0 0 6px;box-shadow:none}
.dk-p2{background:#f3f6fb;border:0;border-radius:14px;padding:16px 20px 18px;margin:0 0 14px;box-shadow:none;display:block}
.dk-p2-head{display:flex;align-items:center;gap:10px;margin:0 0 14px}
.dk-p2-tile{width:30px;height:30px;border-radius:8px;background:#dfe7f6;color:#2f4a8a;display:inline-flex;align-items:center;justify-content:center;flex:none}
.dk-p2-title{font-size:15px;font-weight:600;color:#111827}
.dk-p2-sub{margin-left:auto;font-size:12.5px;color:#6b7280}
.dk-ov-row{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}
.dk-ov-item{all:unset;box-sizing:border-box;cursor:pointer;border-radius:12px;padding:12px 16px 14px;display:flex;flex-direction:column;gap:6px;position:relative}
.dk-ov-item::after{display:none}
.dk-ov-item:hover{background:rgba(255,255,255,.6)}
.dk-ov-item.is-on{background:#fff;box-shadow:0 1px 2px rgba(17,24,39,.08)}
.dk-ov-item:focus-visible{outline:2px solid #2263d5;outline-offset:2px}
.dk-ov-l,.dk-perf-l{display:flex;align-items:center;gap:7px;font-size:11.5px;letter-spacing:.06em;text-transform:uppercase;color:#4b5563;font-weight:600}
