/* round 91: analytics group-by tabs with counts; group tabs and Boosted / date on one row; summary line */
.ana-top{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;margin:0 0 14px}
.ana-top .ana-bar{margin:0;justify-content:flex-end;flex-wrap:nowrap}
