/* round 105: content cards show the post visual on top, metrics with icons below */
.ct-cards{grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:16px}
.ct-card{padding:0;overflow:hidden;gap:0}
.ct-media{position:relative;aspect-ratio:4/5;display:flex;align-items:center;justify-content:center;border-bottom:1px solid #eef0f4}
.ct-media-tl{position:absolute;top:10px;left:10px}
