.cr-rupee{color:#6b7280}
.cr-owner{min-width:118px}
.cr-wrap{overflow-x:auto}
.cr-table{min-width:1180px}
.cr-table td:last-child,.cr-table th:last-child{position:static}
/* ── Unified avatars: 24px rounded square, light gray, like the campaign analytics thumbnails ── */
.ds-avatar,.ds-avatar--sm,.ds-avatar-stack .ds-avatar,.ds-avatar.ds-spoc,.cq-av{width:24px !important;height:24px !important;min-width:24px;border-radius:50% !important;color:#fff !important;font-size:10px !important;font-weight:600 !important;letter-spacing:0 !important;border:0 !important;box-shadow:none !important;margin:0 !important;box-sizing:border-box !important}
