.dk-trend .tv-tip{background:#fff;color:#111827;border:1px solid #e5e7eb;box-shadow:0 6px 18px rgba(17,24,39,.12);width:176px;padding:9px 11px;font-size:12px;gap:2px}
.dk-trend .tv-tip b{color:#111827}
.dk-trend .tv-tip-split i{width:9px;height:9px}
.dk-trend .tv-col:hover,.dk-trend .tv-col.is-on{background:rgba(55,72,130,.06)}
.dk-org .dk-donut-c b{font-size:17px;white-space:nowrap}
.dk-org .dk-donut-c span{font-size:11px}

/* round 73: campaign overview strip and shared performance strip (no per-metric cards) */
.dk-ov{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:6px 0 0;margin:0 0 10px}
.dk-ov-row{display:grid;grid-template-columns:repeat(4,minmax(0,1fr))}
.dk-ov-item{all:unset;box-sizing:border-box;cursor:pointer;display:flex;flex-direction:column;gap:2px;padding:12px 24px 14px;border-left:1px solid #eef0f4;position:relative}
.dk-ov-item:first-child{border-left:0}
.dk-ov-item:focus-visible{outline:2px solid #2263d5;outline-offset:-2px;border-radius:8px}
.dk-ov-l{font-size:12.5px;color:#6b7280;font-weight:500}
.dk-ov-item b{font-size:30px;font-weight:600;color:#111827;line-height:1.15;font-variant-numeric:tabular-nums}
.dk-ov-s{font-size:11.5px;color:#9ca3af}
.dk-ov-item:hover .dk-ov-l{color:#111827}
.dk-ov-item.is-on::after{content:"";position:absolute;left:24px;right:24px;bottom:0;height:2px;background:#374882;border-radius:2px}
.dk-ov-item.is-on b{color:#374882}
.dk-ov .dk-status-note{margin:0;padding:8px 24px 10px;border-top:1px solid #eef0f4}
.dk-perf{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:12px 0;margin:0 0 14px}
.dk-perf-item{padding:4px 24px;display:flex;flex-direction:column;gap:3px;border-left:1px solid #eef0f4;min-width:0}
.dk-perf-item:first-child{border-left:0}
.dk-perf-l{font-size:12.5px;color:#6b7280;font-weight:500;white-space:nowrap}
.dk-perf-v{font-size:22px;font-weight:600;color:#111827;line-height:1.2;font-variant-numeric:tabular-nums;white-space:nowrap}
.dk-perf-s{font-size:11.5px;color:#9ca3af;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
@media (max-width:1180px){.dk-perf{grid-template-columns:repeat(3,minmax(0,1fr));row-gap:12px}.dk-perf-item:nth-child(4){border-left:0}}
@media (max-width:760px){.dk-ov-row{grid-template-columns:repeat(2,minmax(0,1fr))}.dk-ov-item:nth-child(3){border-left:0}.dk-perf{grid-template-columns:repeat(2,minmax(0,1fr))}.dk-perf-item:nth-child(3){border-left:0}}
.dk-perf-s{white-space:normal;line-height:1.35;overflow:visible;text-overflow:clip}
.dk-perf-l,.dk-perf-v{white-space:normal}

/* round 74: overview + performance as tinted panels (reference style) */
.dk-ov{background:#f3f6fb;border:0;border-radius:14px;padding:16px 20px 18px;margin:0 0 6px;box-shadow:none}
.dk-p2{background:#f3f6fb;border:0;border-radius:14px;padding:16px 20px 18px;margin:0 0 14px;box-shadow:none;display:block}
.dk-p2-head{display:flex;align-items:center;gap:10px;margin:0 0 14px}
.dk-p2-tile{width:30px;height:30px;border-radius:8px;background:#dfe7f6;color:#2f4a8a;display:inline-flex;align-items:center;justify-content:center;flex:none}
.dk-p2-title{font-size:15px;font-weight:600;color:#111827}
.dk-p2-sub{margin-left:auto;font-size:12.5px;color:#6b7280}
.dk-ov-row{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}
.dk-ov-item{all:unset;box-sizing:border-box;cursor:pointer;border-radius:12px;padding:12px 16px 14px;display:flex;flex-direction:column;gap:6px;position:relative}
.dk-ov-item::after{display:none}
.dk-ov-item:hover{background:rgba(255,255,255,.6)}
.dk-ov-item.is-on{background:#fff;box-shadow:0 1px 2px rgba(17,24,39,.08)}
.dk-ov-item:focus-visible{outline:2px solid #2263d5;outline-offset:2px}
.dk-ov-l,.dk-perf-l{display:flex;align-items:center;gap:7px;font-size:11.5px;letter-spacing:.06em;text-transform:uppercase;color:#4b5563;font-weight:600}
.dk-ov-l svg,.dk-perf-l svg{color:#2f4a8a;flex:none}
.dk-ov-item b{font-size:32px;font-weight:600;color:#1d2a4f;line-height:1.1;font-variant-numeric:tabular-nums}
.dk-ov-item.is-on b{color:#2f4a8a}
.dk-ov-s,.dk-perf-s{font-size:12.5px;color:#6b7280;line-height:1.35}
.dk-p2-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px}
.dk-p2-grid .dk-perf-item{padding:12px 16px 14px;border-left:0;border-radius:12px;gap:6px;background:transparent}
.dk-p2-grid .dk-perf-item:hover{background:rgba(255,255,255,.6)}
.dk-perf-v{font-size:26px;font-weight:600;color:#1d2a4f;line-height:1.15;font-variant-numeric:tabular-nums}
.dk-status-note{margin:8px 4px 0;font-size:12px}
@media (max-width:1180px){.dk-p2-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media (max-width:760px){.dk-ov-row,.dk-p2-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}

/* round 75: revert performance to KPI cards; scrollable lists (10 rows visible); filter on heading line */
.dk-scroll{overflow:auto;position:relative}
.dk-scroll-camps{max-height:560px}
.dk-scroll-posts{max-height:620px}
