/* round 82: KPI row has four cards now (Published posts moved to overview) */
.dk-kpis{grid-template-columns:repeat(4,minmax(0,1fr))}
@media (max-width:1180px){.dk-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:820px){.dk-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}

/* round 83: creator picker in campaign dialogs is a table of the shortlist with all columns */
