.cov-head{align-items:center}
.cov-head .ds-section-title small{font-size:13px;font-weight:500;color:#6b7280;margin-left:8px}
.cp-split-row .dk-donut-wrap{margin:0}
.cp-split-row .dk-list{margin-top:0;align-self:center}

/* round 94: create-campaign dialog fills its width; no dead column */
.ds-form>.cc-form{grid-column:1/-1;width:100%;min-width:0}
