/* round 96: narrower create-campaign modal */
.modal:has(.cc-form){width:min(860px,calc(100vw - 32px))}

/* round 97: analytics summary as stat cards; single Cancel in dialogs */
.ana-sum{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:0 0 12px}
.ana-stat{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:12px 16px;display:flex;flex-direction:column;gap:2px;min-width:0}
.ana-stat small{font-size:12px;color:#6b7280}
