.ct-media-tl{position:absolute;top:10px;left:10px}
.ct-media-tr{position:absolute;top:10px;right:10px;background:#fff;color:#111827;font-size:12px;font-weight:500;border-radius:6px;padding:3px 8px;box-shadow:0 1px 2px rgba(0,0,0,.08)}
.ct-play{width:52px;height:52px;border-radius:999px;background:rgba(255,255,255,.92);color:#111827;display:flex;align-items:center;justify-content:center;padding-left:3px;box-shadow:0 2px 8px rgba(0,0,0,.12)}
.ct-card-body{padding:14px 16px 16px;display:flex;flex-direction:column;gap:10px;min-width:0}
.ct-card-title{font-size:14px;font-weight:600;color:#111827;line-height:1.35}
.ct-card-metrics{display:flex;gap:16px;color:#6b7280;font-size:13px}
