.ct-card-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;border-top:1px solid #eef0f4;padding-top:10px}
.ct-card-stats small{font-size:11px}
.ct-card-stats b{font-size:13px}

/* round 106: dashboard views trend has the organic vs boosted panel in its right column, like the posts timeline */
.dk-trend.tv--split{grid-template-columns:minmax(0,3fr) minmax(220px,1fr)}
.tv-divider{height:1px;background:#eef0f4;margin:16px 0}
.tv-split-donut{display:flex;flex-direction:column;align-items:center;gap:12px}
