.tv-split-rows{width:100%;display:flex;flex-direction:column;gap:6px;font-size:13px;color:#4b5563}
.tv-split-rows>div{display:flex;align-items:center;gap:8px}
.tv-split-rows i{width:9px;height:9px;border-radius:50%;flex:none}
