.dk-trend.tv--split>.tv-main{min-width:0;padding-right:22px;border-right:1px solid #eef0f4;display:flex;flex-direction:column}
.dk-trend.tv--split>.tv-side{padding-left:22px;display:flex;flex-direction:column;gap:0}
@media (max-width:900px){.dk-trend.tv--split{grid-template-columns:1fr}.dk-trend.tv--split>.tv-main{border-right:0;padding-right:0}.dk-trend.tv--split>.tv-side{padding-left:0;padding-top:14px;margin-top:14px;border-top:1px solid #eef0f4}}

/* round 107: cumulative dashboard: 70% main, 30% widget column (needs attention + sentiment) */
.dk-shell{display:grid;grid-template-columns:minmax(0,7fr) minmax(280px,3fr);gap:20px;align-items:start}
