.cw-caret{width:0!important;height:0!important;border-left:6px solid #6b7280!important;border-right:0!important;border-top:4px solid transparent!important;border-bottom:4px solid transparent!important;transform:none!important}
details.cw-cty[open]>summary .cw-caret{transform:rotate(90deg)!important}
