.pl-embed .pl-sec .pl-sh{border:0}
.pl-embed .pl-right{overflow:hidden}
.pl-embed .pl-right{padding:0 16px 0 28px}

/* round 104: Link creators uses the Add Creators layout, sized smaller */
.addn.link-addn{width:min(680px,calc(100vw - 32px));max-height:min(600px,calc(100vh - 48px))}
