/* round 108: creators widget with a segmented Gender / Location / Tier switch */
.dk-cwidget{margin:0}
.dk-cseg{display:flex;background:#f1f3f7;border-radius:10px;padding:3px;gap:2px;margin:6px 0 12px}
.dk-cseg button{flex:1;border:0;background:transparent;border-radius:8px;padding:7px 10px;font-size:13px;color:#4b5563;cursor:pointer;font-weight:500}
.dk-cseg button.on{background:#fff;color:#111827;box-shadow:0 1px 2px rgba(0,0,0,.08);font-weight:600}
.dk-cwidget-body{min-width:0}
/* round 109: creators widget — tabs left, metric radios right, compact bodies, country→state hierarchy */
.dk-cwidget{padding:14px 16px}
.cw-head{display:flex;align-items:baseline;justify-content:space-between;gap:8px;min-width:0}
.cw-head .dk-wt{display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;min-width:0}
.cw-bar-row{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin:8px 0 10px}
.dk-cwidget .dk-cseg{margin:0;flex:0 1 auto}
.dk-cwidget .dk-cseg button{flex:0 0 auto;padding:6px 12px;white-space:nowrap}
.cw-radios{display:flex;align-items:center;gap:4px;background:#f8f9fb;border:1px solid #e5e7eb;border-radius:10px;padding:3px}
