.cw-bar{height:8px;background:#eef1f7;border-radius:999px;overflow:hidden}
.cw-bar i{display:block;height:100%;background:#7aa2f0;border-radius:999px}
.cw-row b{font-variant-numeric:tabular-nums;text-align:right;font-weight:600}
.cw-row small{color:#6b7280;text-align:right;font-variant-numeric:tabular-nums}
.cw-kids{padding:0 0 6px 16px;border-left:2px solid #eef1f7;margin-left:4px}
.cw-child{font-size:12.5px;padding:4px 2px;color:#374151}
.cw-child .cw-bar{height:6px;background:#f3f5fa}
.cw-child .cw-bar i{background:#b9cdf7}
