.cw-row{display:grid;grid-template-columns:minmax(90px,1.1fr) minmax(60px,2fr) auto 42px;align-items:center;gap:10px;padding:6px 2px;font-size:13px;color:#111827}
.cw-name{display:flex;align-items:center;gap:6px;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
