.dk-trend .tv-tip{background:#fff;color:#111827;border:1px solid #e5e7eb;box-shadow:0 6px 18px rgba(17,24,39,.12);width:176px;padding:9px 11px;font-size:12px;gap:2px}
.dk-trend .tv-tip b{color:#111827}
.dk-trend .tv-tip-split i{width:9px;height:9px}
.dk-trend .tv-col:hover,.dk-trend .tv-col.is-on{background:rgba(55,72,130,.06)}
.dk-org .dk-donut-c b{font-size:17px;white-space:nowrap}
.dk-org .dk-donut-c span{font-size:11px}

/* round 73: campaign overview strip and shared performance strip (no per-metric cards) */
.dk-ov{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:6px 0 0;margin:0 0 10px}
.dk-ov-row{display:grid;grid-template-columns:repeat(4,minmax(0,1fr))}
.dk-ov-item{all:unset;box-sizing:border-box;cursor:pointer;display:flex;flex-direction:column;gap:2px;padding:12px 24px 14px;border-left:1px solid #eef0f4;position:relative}
