/* round 101: analytics KPI icons, Boosted only checkbox, plan sections shown open */
.ana-stat{position:relative}
.ana-ico{display:flex;align-items:center;justify-content:center;width:30px;height:30px;border-radius:8px;background:#eef2ff;color:#1e40af;margin-bottom:6px;font-style:normal}
