.cw-n{font-style:normal;font-weight:400;color:#6b7280;font-size:12px;margin-left:4px}
.cw-seg{display:flex;flex-direction:column;gap:12px}
.cw-segbar{display:flex;height:22px;border-radius:8px;overflow:hidden;background:#eef1f7;gap:2px}
.cw-segbar i{display:block;height:100%;min-width:2px;border-radius:4px}
.cw-seg-list{display:flex;flex-direction:column}
.cw-seg-row{display:grid;grid-template-columns:minmax(100px,1.4fr) auto auto auto 56px;gap:12px;align-items:center;padding:8px 2px;border-bottom:1px solid #f0f2f6;font-size:13px}
.cw-seg-row:last-child{border-bottom:0}
.cw-seg-row small{color:#6b7280;font-variant-numeric:tabular-nums;text-align:right;white-space:nowrap}
.cw-seg-row b{font-variant-numeric:tabular-nums;text-align:right;font-weight:600;white-space:nowrap}
.cw-seg-row .cw-pct{font-weight:600;color:#374151}
@media (max-width:640px){.cw-seg-row{grid-template-columns:minmax(90px,1fr) auto auto 52px;}.cw-seg-row small:nth-of-type(2){display:none}}
/* round 110b: caret rotates only for its own row */
.cw-caret{width:0!important;height:0!important;border-left:6px solid #6b7280!important;border-right:0!important;border-top:4px solid transparent!important;border-bottom:4px solid transparent!important;transform:none!important}
details.cw-cty[open]>summary .cw-caret{transform:rotate(90deg)!important}
/* round 111: top creators widget in the widget panel */
.dk-topc .dk-wh{margin-bottom:6px}
.tc-list{display:flex;flex-direction:column}
