.campl-card-menu .ds-more>summary.ds-btn:hover{background:#f1f3f7!important;color:#111827}
.campl-card-menu .ds-more[open]>summary.ds-btn{background:#eef1f7!important}
.campl-card-menu .ds-more-menu{z-index:40}
.campl-card-menu .ds-more-menu button{white-space:nowrap}
.dk-ov-row--camp{grid-template-columns:repeat(2,minmax(0,1fr))}
/* round 116: campaign overview — all six metrics on one line, divider between groups */
.dk-ov-row--all{grid-template-columns:repeat(6,minmax(0,1fr))}
