.cc-search{height:36px;width:100%;box-sizing:border-box;border:1px solid #d1d5db;border-radius:8px;padding:0 12px;font:inherit;font-size:13px;margin-bottom:12px}
.cc-search:focus{outline:none;border-color:#3b49c9;box-shadow:0 0 0 3px rgba(59,73,201,.12)}
.dlg-ct{border:1px solid #eef0f4;border-radius:10px;overflow:hidden}
.dlg-ct table{min-width:0;width:100%}
.dlg-ct thead th{background:#f9fafb;font-size:12px;color:#6b7280;font-weight:500}
