.rq-page{max-width:1180px;margin:0 auto;padding:8px 0 40px}
.rq-head h1{font-size:24px;font-weight:600;margin:0;color:#111827}
.rq-head p{margin:4px 0 0;font-size:14px;color:#6b7280}
.rq-bar{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:20px 0 14px;border-bottom:1px solid #e5e7eb}
.rq-tabs{display:flex;gap:6px}
.rq-tab{background:none;border:0;border-bottom:2px solid transparent;padding:10px 12px;font:inherit;font-size:14px;color:#6b7280;cursor:pointer;display:flex;gap:8px;align-items:center;margin-bottom:-1px}
.rq-tab span{font-size:12px;background:#eef0f4;color:#4b5563;border-radius:999px;padding:1px 8px}
.rq-tab.on{color:#111827;font-weight:600;border-bottom-color:#374882}
.rq-tab.on span{background:#374882;color:#fff}
.rq-sum{font-size:13px;color:#6b7280;white-space:nowrap}
.rq-sec{margin-top:22px}
.rq-sech{display:flex;align-items:center;gap:8px;font-size:13px;font-weight:600;color:#374151;text-transform:uppercase;letter-spacing:.04em;margin-bottom:8px}
.rq-sech span{font-weight:500;color:#6b7280;background:#f1f3f7;border-radius:999px;padding:0 8px;font-size:12px;letter-spacing:0}
.rq-table{width:100%;border-collapse:separate;border-spacing:0;border:1px solid #e5e7eb;border-radius:12px;overflow:hidden;background:#fff}
.rq-table th{text-align:left;font-size:12px;font-weight:600;color:#6b7280;background:#f8fafc;padding:10px 14px;border-bottom:1px solid #e5e7eb}
.rq-table td{padding:12px 14px;border-bottom:1px solid #eef0f4;vertical-align:middle;font-size:14px}
.rq-table tr:last-child td{border-bottom:0}
.rq-pc,.rq-stc,.rq-goc{width:1%;white-space:nowrap}
.rq-goc{text-align:right}
.rq-t{font-weight:600;color:#111827}
.rq-d{font-size:13px;color:#6b7280;margin-top:2px;line-height:1.45}
.rq-p{display:inline-block;font-size:12px;font-weight:600;border-radius:6px;padding:2px 8px;background:#eef0f4;color:#4b5563}
.rq-p P0{background:#fde2e2;color:#b42318}
.rq-p P1{background:#fdf0d5;color:#9a5b00}
.rq-p P2{background:#e3ecff;color:#2446a8}
.rq-p P3{background:#eef0f4;color:#4b5563}
.rq-status{font:inherit;font-size:13px;border:1px solid #d6dbe4;border-radius:8px;padding:5px 8px;background:#fff;color:#111827;cursor:pointer}
.rq-s-in-progress{border-color:#c9a24a;background:#fff9e8}
.
/* round 129: requirement status, solution notes, redirect highlight */
.rq-s-completed{border-color:#7fc4a0;background:#eefaf3;color:#166c44}
.rq-s-not-started{border-color:#d6dbe4}
.rq-how{margin-top:6px;font-size:13px;line-height:1.45;color:#1d4ed8;max-width:620px}
.req-flash{outline:3px solid #2f6fe0 !important;outline-offset:4px;border-radius:12px;box-shadow:0 0 0 8px rgba(47,111,224,.16);transition:outline-color .3s,box-shadow .3s}
/* round 130: serial numbers on requirements */
.rq-noc{width:1%;white-space:nowrap;color:#6b7280;font-variant-numeric:tabular-nums}
.rq-no{font-weight:600;color:#374151}
/* round 131: requirements split into action items */
.rq-parent td{border-bottom:0!important;padding-bottom:4px;background:#fff}
.rq-sub td{background:#fafbfd;padding-top:8px;padding-bottom:12px}
.rq-sub:last-child td{border-bottom:1px solid #eef0f4}
.rq-sn{font-size:12px;color:#6b7280;font-variant-numeric:tabular-nums;padding-left:6px}
.rq-subt{font-size:14px;color:#111827;padding-left:14px;border-left:2px solid #d6dbe4;margin-left:4px}
.rq-sec-tag{font-size:11px;color:#6b7280;margin-top:6px;text-transform:uppercase;letter-spacing:.04em}
.rq-st{font-size:12px;font-weight:600;border-radius:999px;padding:3px 10px;display:inline-block;white-space:nowrap}
.rq-st-completed{background:#eefaf3;color:#166c44}
.rq-st-in-progress{background:#fff9e8;color:#8a5a00}
.rq-st-not-started{background:#f1f3f7;color:#4b5563}
.rq-sub .rq-how{margin-left:14px;margin-top:6px}
/* round 132: creator quick view — avatar header, brand fit metric, scope toggle, variance list, journey cards */
.cq-drawer .ds-drawer-head>div:first-child h2{display:flex;align-items:center;gap:10px}
.cq-hav{width:36px;height:36px;font-size:13px;flex:none}
.cq-kpis{grid-template-columns:repeat(5,minmax(0,1fr))}
.cq-kpi{padding:10px 12px}
.cq-kpi b{font-size:17px}
.cq-scope{align-self:flex-start}
.cq-vp{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:10px 0;border-bottom:1px solid #f1f2f5}
.cq-vp>div:first-child{min-width:0;display:flex;flex-direction:column;gap:2px}
.cq-vp>div:first-child b{font-size:14px;font-weight:600;color:#111827}
.cq-vp>div:first-child span{font-size:12px;color:#6b7280}
.cq-vp-r{display:flex;align-items:center;gap:10px;flex:none}
.cq-vp-r b{font-size:14px;font-variant-numeric:tabular-nums}
.cq-var{font-size:12px;font-weight:600;border-radius:999px;padding:2px 8px;font-variant-numeric:tabular-nums}
.cq-var.is-up{background:#eefaf3;color:#166c44}
.cq-var.is-down{background:#fdecec;color:#b42318}
.cq-jc{border:1px solid #e5e7eb;border-radius:12px;padding:14px;background:#fff;margin-bottom:10px}
.cq-jc.is-current{border-color:#c7d2ea}
.cq-jc-h{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}
.cq-jc-h b{display:block;font-size:14px;color:#111827}
.cq-jc-h span{font-size:12px;color:#6b7280}
.cq-live{font-size:11px;font-weight:600;background:#eaf0ff;color:#2446a8;border-radius:999px;padding:3px 9px;white-space:nowrap}
.cq-jc-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin-top:12px;border:1px solid #eef0f4;border-radius:10px}
.cq-jc-stats>div{padding:8px 10px;border-left:1px solid #eef0f4}
.cq-jc-stats>div:first-child{border-left:0}
.cq-jc-stats span{display:block;font-size:11px;color:#6b7280}
.cq-jc-stats b{display:block;font-size:14px;font-variant-numeric:tabular-nums}
.cq-jc-stats small{font-size:11px;color:#6b7280}
.cq-inst{margin-top:10px;display:flex;flex-direction:column}
.cq-inst-r{display:grid;grid-template-columns:70px minmax(0,1fr) auto auto;gap:10px;align-items:center;font-size:13px;padding:6px 0;border-top:1px solid #f1f2f5}
.cq-inst-r span:nth-child(2){min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.cq-inst-r em{font-style:normal;font-size:11px;color:#2446a8;background:#eaf0ff;border-radius:6px;padding:0 5px;margin-left:4px}
.cq-inst-r b{font-variant-numeric:tabular-nums}
.cq-inst-r>span:last-child{color:#6b7280;font-variant-numeric:tabular-nums}
.cq-jc.is-min{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:10px 14px}
.cq-jc.is-min>div:first-child{min-width:0}
.cq-jc.is-min b{display:block;font-size:13px;color:#111827;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cq-jc.is-min span{font-size:12px;color:#6b7280}
.cq-jc-mini{display:flex;flex-direction:column;align-items:flex-end;gap:2px;flex:none;font-variant-numeric:tabular-nums}
/* round 133: creator quick view — content-tab post rows, campaign cards, timeline, metric strokes */
.cq-stats{gap:8px;border:0;overflow:visible}
.cq-stats>div{border:1px solid #e5e7eb;border-radius:10px;padding:12px 14px}
.cq-stats>div:first-child{border-left:1px solid #e5e7eb}
.cq-kpis{gap:8px;border:0;overflow:visible}
.cq-kpi{border:1px solid #e5e7eb;border-radius:10px}
.cq-pc{display:flex;justify-content:space-between;align-items:center;gap:14px;border:1px solid #e5e7eb;border-radius:12px;padding:12px;background:#fff}
.cq-pc-main{min-width:0;flex:1}
.cq-pc-side{display:flex;flex-direction:column;align-items:flex-end;gap:4px;flex:none;text-align:right}
.cq-pc-v{font-size:13px;color:#6b7280;display:inline-flex;gap:6px;align-items:center}
.cq-pc-v b{color:#111827;font-size:14px;font-variant-numeric:tabular-nums}
.cq-pc-m{font-size:12px;color:#6b7280;display:inline-flex;gap:6px;align-items:center;font-variant-numeric:tabular-nums}
.cq-camp-cards{grid-template-columns:1fr}
.cq-drawer .campl-card{border:1px solid #e5e7eb}
/* round 134: creator quick view — compact post cards with background and shadow */
.cq-sec:has(.cq-pc){gap:10px}
.cq-pc{padding:9px 12px;gap:12px;border:0;border-radius:12px;background:#fff;box-shadow:0 1px 2px rgba(17,24,39,.06),0 4px 12px rgba(17,24,39,.06);transition:box-shadow .15s ease}
.cq-pc:hover{box-shadow:0 2px 4px rgba(17,24,39,.08),0 8px 18px rgba(17,24,39,.09)}
.cq-pc .cq-pc-main .pl-cell{gap:10px}
.cq-pc .pl-thumb{width:40px;height:40px;border-radius:9px;font-size:9px;padding-bottom:4px}
.cq-pc .pl-txt strong{font-size:13px}
.cq-pc .pl-txt a{font-size:11px;max-width:200px}
.cq-pc .pl-go{width:30px;height:30px;border-radius:8px}
.cq-pc .pl-go svg{width:13px;height:13px}
.cq-pc-side{gap:3px}
.cq-pc-v{font-size:12px;gap:5px}
.cq-pc-v b{font-size:13px}
.cq-pc-m{font-size:11px}
.cq-pc .cq-var{font-size:11px;padding:1px 7px}
.cq-pc .cq-pc-main .pl-cell{width:100%}
.cq-pc .pl-txt{flex:1 1 auto;min-width:0}
.cq-pc .pl-go{margin-left:auto}
.cq-pc .cq-pc-side{width:168px;align-items:flex-end}
.cq-pc .cq-pc-m{white-space:nowrap}
/* round 135: lifetime = one timeline of campaigns with Plix */
.cq-th{width:26px;height:26px;border-radius:6px;display:inline-flex;align-items:flex-end;justify-content:center;padding-bottom:3px;color:#fff;text-decoration:none;flex:none}
.cq-th b{font-size:7px;font-weight:600;letter-spacing:.02em;line-height:1}
.cq-th:hover{outline:2px solid rgba(55,72,130,.35);outline-offset:1px}
.cq-strip{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}
.cq-inst-r{grid-template-columns:26px minmax(0,1fr) auto auto auto;gap:10px}
.cq-inst-t{min-width:0;display:flex;flex-direction:column}
.cq-inst-t b{font-size:12px;font-weight:600;color:#111827;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cq-inst-t span{font-size:11px;color:#6b7280}
.cq-inst-n{font-size:12px;color:#6b7280;font-variant-numeric:tabular-nums;white-space:nowrap}
.cs-ev-body .cq-jc{margin-bottom:0;width:100%;box-shadow:0 1px 2px rgba(17,24,39,.06),0 4px 12px rgba(17,24,39,.06);border:0}
.cs-ev-body .cq-jc.is-min{display:block;padding:12px 14px}
/* round 136: creator quick view — three main tabs, SPOC in campaign tab, notes tab, no audience */
.cq-layout--solo{grid-template-columns:1fr}
.cq-spoc{display:flex;flex-direction:column;gap:6px;max-width:320px}
.cq-spoc span{font-size:12px;color:#6b7280;font-weight:600;text-transform:uppercase;letter-spacing:.04em}
.cq-notes-box{width:100%;border:1px solid #d6dbe4;border-radius:12px;padding:12px 14px;font:inherit;font-size:14px;resize:vertical;min-height:160px;background:#fff;box-shadow:0 1px 2px rgba(17,24,39,.05)}
.cq-notes-box:focus{outline:2px solid rgba(55,72,130,.25);border-color:#374882}
.cq-sec .cq-notes-box{margin-top:4px}

/* ── Campaign overview, creators and header (round 52) ── */
.vg{padding:16px 18px;margin-bottom:14px}
.vg-head{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;margin-bottom:6px}
.vg-svg{display:block;width:100%;height:auto;overflow:visible}
.vg-grid{stroke:#eceef3;stroke-width:1}
.vg-tick{font-size:12px;fill:#6b7280}
.vg-end{font-size:12px;font-weight:600;fill:#111827}
.vg-line{stroke:#3d4fb8;stroke-width:2.2;stroke-linejoin:round}
.vg-area{fill:#3d4fb8;opacity:.12}
.vg-dot{fill:#3d4fb8}
.cp-two{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:14px;align-items:start}
@media (max-width:900px){.cp-two{grid-template-columns:1fr}}
.sv{padding:16px 18px}
.sv-total{display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;margin:6px 0 8px}
.sv-total b{font-size:22px;color:#111827}
.sv-total span{font-size:13px;color:#6b7280}
.sv-bar{margin-bottom:10px}
.sv-rows{display:flex;flex-direction:column;max-height:300px;overflow:auto}
.sv-row{display:grid;grid-template-columns:minmax(0,1fr) auto 90px;gap:12px;align-items:center;padding:8px 0;border-top:1px solid #eef0f4;font-size:13px}
.sv-who{display:flex;flex-direction:column;min-width:0;color:#111827}
.sv-who small{color:#6b7280;font-size:12px}
.sv-amt{font-variant-numeric:tabular-nums;font-weight:600;color:#111827}
.sv-share{height:6px;border-radius:99px;background:#eef1f6;overflow:hidden}
.sv-share i{display:block;height:100%;background:#d69e2e;border-radius:99px}
.cr-cost{display:inline-flex;align-items:center;gap:2px}
.cr-cost input{width:104px;text-align:right;padding:6px 8px;border:1px solid #d6dbe4;border-radius:8px;font:inherit;background:#fff}
.cr-cost input:focus{outline:2px solid #1247af;outline-offset:1px}
.cr-rupee{color:#6b7280}
.cr-owner{min-width:118px}
.cr-wrap{overflow-x:auto}
.cr-table{min-width:1180px}
.cr-table td:last-child,.cr-table th:last-child{position:static}
/* ── Unified avatars: 24px rounded square, light gray, like the campaign analytics thumbnails ── */
.ds-avatar,.ds-avatar--sm,.ds-avatar-stack .ds-avatar,.ds-avatar.ds-spoc,.cq-av{width:24px !important;height:24px !important;min-width:24px;border-radius:50% !important;color:#fff !important;font-size:10px !important;font-weight:600 !important;letter-spacing:0 !important;border:0 !important;box-shadow:none !important;margin:0 !important;box-sizing:border-box !important}
.ds-avatar-stack .ds-avatar{margin-left:-4px !important;border:1px solid #fff !important}
.ds-avatar-stack .ds-avatar:first-child{margin-left:0 !important}
.ds-avatar-more{width:24px;height:24px;border-radius:50%;background:#f3f4f6;color:#6b7280;font-size:10px;border:1px solid #e5e7eb}
/* ── Post timeline card (round 54): one period control, area chart, hover detail ── */
.tv{margin:0 0 16px;padding:18px;border:1px solid #e5e7eb;border-radius:14px;background:#fff}
.tv-head{display:flex;justify-content:space-between;align-items:flex-start;gap:14px;flex-wrap:wrap;margin-bottom:14px}
.tv-title{font-size:15px;font-weight:600;color:#111827}
.tv-sub{margin:3px 0 0;font-size:12.5px;color:#6b7280}
.tv-ctrl{display:flex;align-items:center;gap:6px}
.tv-select{display:inline-flex}
select.tv-select{border:1px solid #d6dbe4;border-radius:8px;padding:7px 12px;font:inherit;font-size:13px;font-weight:600;color:#111827;background:#fff;cursor:pointer}
.tv-nav{width:32px;height:32px;border:1px solid #d6dbe4;border-radius:8px;background:#fff;color:#374151;font-size:16px;cursor:pointer}
.tv-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));border:1px solid #eef0f4;border-radius:10px;margin-bottom:14px}
.tv-kpis>div{padding:12px 14px;display:flex;flex-direction:column;gap:2px;border-right:1px solid #eef0f4;min-width:0}
.tv-kpis>div:last-child{border-right:0}
.tv-kpis>div>span{font-size:12px;color:#6b7280}
.tv-kpis b{font-size:20px;color:#111827;font-variant-numeric:tabular-nums}
.tv-kpis small{font-size:12px;color:#6b7280}
.tv-split{display:flex;height:6px;border-radius:99px;overflow:hidden;background:#eef1f6;margin-top:6px}
.tv-split i{display:block;height:100%}
.tv-org{background:#1f3a68}
.tv-boo{background:#d69e2e}
.tv-chart{position:relative}
.tv-svg{display:block;width:100%;height:auto;overflow:visible}
.tv-area-org{fill:#1f3a68;opacity:.88}
.tv-area-boo{fill:#d69e2e;opacity:.88}
.tv-dot-pt{fill:#fff;stroke:#1f3a68;stroke-width:2}
.tv-hit{fill:transparent;cursor:crosshair}
.tv-hit.is-on{fill:rgba(31,58,104,.07)}
.tv-tip{position:absolute;top:0;width:180px;background:#111827;color:#fff;border-radius:10px;padding:10px 12px;font-size:12px;display:flex;flex-direction:column;gap:3px;box-shadow:0 8px 24px rgba(0,0,0,.18);pointer-events:none;z-index:2}
.tv-tip[hidden]{display:none}
.tv-tip b{font-size:13px}
.tv-tip-split{display:flex;align-items:center;gap:6px}
.tv-tip-split i{width:8px;height:8px;border-radius:2px;display:inline-block}
.tv-legend{display:flex;gap:14px;font-size:12px;color:#4b5563;margin:10px 0 0;flex-wrap:wrap}
.tv-legend span{display:inline-flex;align-items:center;gap:6px}
.tv-legend i{width:10px;height:10px;border-radius:3px;display:inline-block}
.tv-legend .tv-dot{background:#fff;border:2px solid #1f3a68;border-radius:50%;width:9px;height:9px}
.tv-chips{display:flex;gap:6px;overflow-x:auto;padding:12px 0 2px;margin-top:10px;border-top:1px solid #eef0f4}
.tv-chip{flex:none;border:1px solid #e5e7eb;background:#fff;border-radius:99px;padding:5px 11px;font:inherit;font-size:12px;color:#374151;cursor:pointer;white-space:nowrap}
.tv-chip.is-on{background:#1f3a68;border-color:#1f3a68;color:#fff}
.tv-chip small{opacity:.7;margin-left:4px}
.tv-empty{font-size:12.5px;color:#6b7280;margin:8px 0 0}
@media (max-width:640px){.tv-kpis{grid-template-columns:1fr 1fr}}
/* round 55: column chart + top controls block */
.tv-top{margin:0 0 14px}
.tv-top .tv-head{margin-bottom:10px}
.tv-col-org{fill:#1f3a68}
.tv-col-boo{fill:#d69e2e}
/* round 56: dashboard header, KPI cards, compact chart */
.tv-bar{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin:0 0 14px}
.tv-bar .tv-sub{font-size:13px;color:#6b7280}
.tv-ctrl{display:flex;align-items:center;gap:6px;flex-wrap:wrap}
.tv-sync{margin-left:4px}
.tv-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px;border:0;margin:0 0 14px}
.tv-kpis>div{border:1px solid #e5e7eb;border-radius:12px;background:#fff;padding:14px 16px;border-right:1px solid #e5e7eb}
.tv{margin:0 0 14px;padding:16px 18px}
.tv-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;flex-wrap:wrap;margin-bottom:8px}
.tv-legend{margin:4px 0 0}
.tv-chips{padding-top:10px;margin-top:10px}
/* round 57: content table */
.ct-wrap{overflow-x:auto}
.ct-table{min-width:1280px}
.ct-post-cell{display:flex;align-items:center;gap:10px;min-width:0}
.ct-post-meta{display:flex;flex-direction:column;gap:3px;min-width:0;max-width:260px}
.ct-kind{font-size:12.5px;font-weight:600;color:#111827}
.ct-link{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11.5px;color:#6b7280}
.ct-open{align-self:flex-start;margin-top:2px}
.ct-thumb{position:relative;display:inline-flex;align-items:center;justify-content:center;flex:none;color:#fff;border-radius:8px}
.ct-reel{width:34px;height:60px;border-radius:8px}
.ct-post{width:44px;height:44px;border-radius:6px}
.ct-carousel{width:40px;height:50px;border-radius:6px;box-shadow:4px -3px 0 -1px rgba(31,58,104,.22),8px -6px 0 -2px rgba(31,58,104,.12)}
.ct-product{max-width:200px;white-space:normal;font-size:12.5px;color:#374151}
.ct-nocost{font-size:11px;color:#6b7280;background:#f3f4f6;border-radius:99px;padding:2px 8px;white-space:nowrap}
.ct-type{font-size:11.5px;font-weight:600;padding:2px 9px;border-radius:99px;white-space:nowrap}
.ct-type.is-boost{background:#fdf3dc;color:#8a5a00}
.ct-type.is-org{background:#e8edf7;color:#1f3a68}
.ct-product{max-width:none;min-width:190px}
.ct-table{min-width:1400px}
