.tv-side{display:flex;flex-direction:column;padding-left:22px;gap:0}
.tv-kpi{display:flex;flex-direction:column;gap:2px;padding:14px 0;border:0;border-bottom:1px solid #eef0f4;border-radius:0;background:none}
