.cq-more>summary:hover{background:#f3f5f9}
.cq-more[open]>summary{margin-bottom:4px}
.cq-inst--rest{margin-top:0}
/* round 139: creator quick view — tabs stay visible while scrolling; divider runs edge to edge */
.cq-tabs{position:sticky;top:0;z-index:20;background:#fff;margin:20px -28px 0;padding:6px 28px 0;border-bottom:1px solid #e5e7eb}
.cq-tabs button{margin-bottom:-1px}

/* ── Campaign overview, creators and header (round 52) ── */
.vg{padding:16px 18px;margin-bottom:14px}
.vg-head{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;margin-bottom:6px}
.vg-svg{display:block;width:100%;height:auto;overflow:visible}
.vg-grid{stroke:#eceef3;stroke-width:1}
.vg-tick{font-size:12px;fill:#6b7280}
