.tc-more{font-style:normal;font-size:11px;background:#eef1f7;color:#374882;border-radius:999px;padding:0 6px;margin-left:2px;font-weight:600}
.tc-note{margin:6px 0 0}
/* round 112: campaign overview — status + published vs planned, divider, performance KPIs */
.dk-ov-row--camp{grid-template-columns:repeat(4,minmax(0,1fr))}
.dk-ov-row--kpi{grid-template-columns:repeat(4,minmax(0,1fr))}
.dk-ov-hr{height:1px;background:#eef0f4;margin:0 24px}
