.ds-more-menu button{white-space:nowrap}
.campl-card.is-done{background:#f2f2f2}
/* round 115: ⋯ menu on campaign cards */
.campl-card-top{position:relative}
.campl-card-menu{margin-left:auto;flex:0 0 auto;align-self:flex-start;display:flex;align-items:center;gap:6px}
.campl-card-menu .ds-more>summary.ds-btn{border:0!important;background:transparent!important;box-shadow:none!important;color:#4b5563}
.campl-card-menu .ds-more>summary.ds-btn:hover{background:#f1f3f7!important;color:#111827}
.campl-card-menu .ds-more[open]>summary.ds-btn{background:#eef1f7!important}
