/* round 61: dashboard period, layout, advanced filters, consistent chart text */
.dk-head-actions .ds-btn--icon,.tv-sync{width:36px;height:36px;min-width:36px;padding:0;display:inline-flex;align-items:center;justify-content:center;border-radius:8px}
