/* Shortlist lists: status lifecycle, comments, row actions */
.pl-stage{appearance:none;-webkit-appearance:none;border:1px solid transparent;border-radius:999px;padding:4px 26px 4px 10px;font-size:12px;font-weight:600;line-height:1.2;background-color:#f3f4f6;color:#374151;background-image:linear-gradient(45deg,transparent 50%,currentColor 50%),linear-gradient(135deg,currentColor 50%,transparent 50%);background-position:calc(100% - 13px) 55%,calc(100% - 9px) 55%;background-size:4px 4px;background-repeat:no-repeat;cursor:pointer;white-space:nowrap}
.pl-stage-pill{display:inline-block;border-radius:999px;padding:3px 10px;font-size:12px;font-weight:600;line-height:1.2;background:#f3f4f6;color:#374151;white-space:nowrap}
