.pl-stage:hover{border-color:#cbd5e1}
.pl-stage:focus-visible{outline:2px solid #93c5fd;outline-offset:2px}
.pl-note{border:1px solid transparent;border-radius:8px;padding:6px 8px;margin:-6px -8px;cursor:text;min-height:34px;transition:background .15s,border-color .15s,box-shadow .15s}
.pl-note:hover,.pl-note:focus-visible{background:#fff;border-color:#cbd5e1;box-shadow:0 1px 2px rgba(15,23,42,.06);outline:none}
