.pl-hero{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px;margin-bottom:12px}
.pl-hero-i{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:12px 14px;min-width:0}
