/* CRM sidebar group: match the weight of the other Creator rows */
.nav-exp.crm-nav .nav-toggle{font-weight:500}
/* sidebar toggles: same weight as top-level rows; one label per group */
.nav-exp .nav-toggle{font-weight:500}
.nav-exp{margin-top:6px}
/* sidebar spacing: clear gaps between sections, breathing room between rows */
.nav-exp{margin-top:14px}
.nav .nav-row:not(.sub){margin-bottom:0px}
.nav .nav-row.sub{margin-bottom:0px}
.nav .nav-group{padding-top:14px;padding-bottom:4px}
/* sidebar rows must not shrink to fit the viewport height (cramped selected state) */
.nav>*{flex-shrink:0}
.nav .nav-row{flex-shrink:0}
@media(max-width:1100px){.crm-split{grid-template-columns:1fr}}

/* CRM outreach detail: 70 / 30 split */
.crm-split{grid-template-columns:minmax(0,7fr) minmax(300px,3fr)}
