.crm-past summary::after{content:"▾";color:#9ca3af;position:absolute;right:2px;top:0}
.crm-past[open] summary::after{content:"▴"}
.crm-past[open] summary .cq-sec-head{margin-bottom:10px}
.crm-qv .cq-stats{grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:8px}
