.brand-row.on{background:#e6edfb}
.brand-av{width:26px;height:26px;border-radius:50%;background:#2a3c7d;color:#fff;font-weight:600;font-size:9.5px;display:flex;align-items:center;justify-content:center;flex:none}
.brand-meta{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px}
.brand-meta b{font-size:12.5px;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.brand-meta em{font-style:normal;font-size:8.5px;font-weight:600;letter-spacing:.03em;background:#fff;border-radius:4px;padding:1px 4px;align-self:flex-start;max-width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#374151}
.brand-radio{width:14px;height:14px;border-radius:50%;border:1.5px solid #cbd2dc;flex:none;background:#fff}
.brand-radio.on{background:#2a3c7d;border-color:#2a3c7d;box-shadow:inset 0 0 0 3px #fff}
.brand-none{padding:10px;color:#6b7280;font-size:12px;margin:0}
.rp-tabs{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #e5e7eb;padding:0 10px}
.rp-tabwrap{display:flex;gap:14px}
.alert-tab{background:none;border:0;padding:10px 0 8px;font:inherit;font-size:12.5px;color:#6b7280;cursor:pointer;border-bottom:2px solid transparent;margin-bottom:-1px}
.alert-tab.on{color:#1d4ed8;border-color:#1d4ed8;font-weight:500}
.rp-acts{display:flex;gap:10px;color:#9ca3af}
.rp-acts .ico{width:13px;height:13px}
.alert-empty{padding:12px 10px;display:flex;flex-direction:column;align-items:flex-start;gap:4px}
.alert-ico{width:30px;height:30px;border-radius:8px;background:#f1f3f6;display:flex;align-items:center;justify-content:center;color:#374151;margin-bottom:4px}
.alert-ico .ico{width:15px;height:15px}
.alert-empty b{font-size:12.5px;font-weight:600}
.alert-empty p{color:#6b7280;font-size:12px;line-height:1.4;margin:0 0 6px}
.rp-btn{height:26px;padding:0 10px;border:1px solid #d1d5db;border-radius:6px;background:#fff;font:inherit;font-size:11.5px;font-weight:500;cursor:pointer;color:#111827}
.ru-head{display:flex;align-items:center;gap:8px;padding:6px 6px 6px}
.ru-head b{display:block;font-size:12.5px;font-weight:600}
.ru-head small{display:block;font-size:10.5px;color:#6b7280;word-break:break-all}
.ru-av{width:28px;height:28px;border-radius:50%;background:#e8ecf6;color:#2a3c7d;display:flex;align-items:center;justify-content:center;flex:none}
.ru-av .ico{width:14px;height:14px}
.ru-sep{height:1px;background:#e5e7eb;margin:4px 6px}
.ru-row{width:100%;height:28px;display:flex;align-items:center;gap:8px;padding:0 6px;border:0;background:none;border-radius:6px;font:inherit;font-size:12.5px;color:#374151;cursor:pointer;text-align:left}
.ru-row:hover{background:#f1f3f7}
.ru-row .ico{width:14px;height:14px;color:#4b5563;flex:none}
.ru-out,.ru-out .ico{color:#e5484d}
.nav-row.plan-row{height:30px}
.nav-row.plan-row span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}

/* Ads Performance secondary nav */
.ap-head{display:flex;align-items:center;justify-content:space-between;gap:8px}
.ap-connect{height:28px;padding:0 10px;border:1px solid #d1d5db;border-radius:8px;background:#fff;font:inherit;font-size:12px;font-weight:500;cursor:pointer;color:#111827}
.ap-sel-l{font-size:12px;color:#6b7280;margin:12px 0 6px}
.ap-select select{width:100%;height:36px;border:1px solid #d1d5db;border-radius:8px;background:#fff;font:inherit;font-size:13px;padding:0 8px;color:#111827}
.ap-demo{font-size:11px;color:#9ca3af;margin:4px 0 10px}
.ap-rep-h{display:flex;justify-content:space-between;align-items:center;font-size:12px;font-weight:600;color:#6b7280;margin:12px 0 4px 6px}
.ap-plus{width:24px;height:24px;border:0;background:none;cursor:pointer;color:#6b7280;font-size:16px;line-height:1}
.ap-grp-h{width:100%;display:flex;align-items:center;gap:8px;height:34px;border:0;background:none;font:inherit;font-size:13px;font-weight:600;color:#111827;cursor:pointer;padding:0 6px;border-radius:6px;text-align:left}
.ap-grp-h:hover{background:#eceff6}
.ap-chev{width:12px;display:inline-block;transition:transform .15s;color:#6b7280;font-size:14px;line-height:1}
.ap-grp.open .ap-chev{transform:rotate(90deg)}
.ap-kids{display:none;margin-left:12px;padding-left:8px;border-left:1px solid #e5e7eb}
.ap-grp.open .ap-kids{display:block}
.nav-row.ap-kid{height:30px;font-size:12.5px}

/* Dashboard: product performance spans the full row when it is the only card in the row */
.dk-row2>.dk-w:only-child{grid-column:1/-1}

/* Dashboard stats: icon before each label, value directly under it, no empty caption line */
.tv-m3>span,.tv-kpi>span{display:flex;align-items:center;gap:6px}
.tv-m3>span svg,.tv-kpi>span svg{width:14px;height:14px;color:#9aa3b5;flex:none}
.tv-m3>b,.tv-kpi>b{margin-top:4px}
.tv-m3>small,.tv-kpi>small{display:none}
.tv-m3>span{white-space:nowrap}

/* Top creators · ranked leaderboard */
.dk-topc .tl-head{margin-bottom:10px}
.tl-sub{font-size:12px;color:#6b7280;margin:2px 0 0}
.tl-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:14px}
.tl-row{display:grid;grid-template-columns:16px 32px minmax(0,1fr);gap:10px;align-items:center}
.tl-rank{font-size:12px;font-weight:600;color:#9aa3b5;text-align:center;font-variant-numeric:tabular-nums}
.tl-av{width:32px;height:32px;border-radius:50%;color:#fff;font-size:11px;font-weight:600;display:flex;align-items:center;justify-content:center;flex:none}
.tl-main{min-width:0;display:flex;flex-direction:column;gap:5px}
.tl-l1{display:flex;align-items:baseline;justify-content:space-between;gap:10px;min-width:0}
.tl-name{font-size:13px;font-weight:600;color:#111827;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
.tl-views{font-size:13px;font-weight:600;color:#111827;white-space:nowrap;font-variant-numeric:tabular-nums}
.tl-bar{height:4px;border-radius:999px;background:#eef1f7;overflow:hidden}
.tl-bar i{display:block;height:100%;border-radius:999px;background:#374882}
.tl-l2{display:flex;align-items:center;justify-content:space-between;gap:8px;min-width:0}
.tl-meta{font-size:11.5px;color:#6b7280;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
.tl-delta{font-size:11px;font-weight:600;white-space:nowrap;font-variant-numeric:tabular-nums}
.tl-delta.is-up{color:#15803d}
.tl-delta.is-down{color:#b91c1c}
.tc-more{font-style:normal;font-size:10.5px;background:#eef1f7;color:#374882;border-radius:999px;padding:0 5px;margin-left:2px;font-weight:600}

/* Needs attention: compact range filter, and plain dividers between items (no grey fill or box per item) */
.dk-wh--row .dk-wa .ds-filter{height:28px;min-height:0;padding:0 8px 0 10px;font-size:12px;font-weight:500;gap:4px;border-radius:8px}
.dk-wh--row .dk-wa .ds-filter span{font-size:12px}
.dk-wh--row .dk-wa .ds-filter-x{font-size:12px}
.dk-wh--row .dk-wa .ds-filter svg{width:12px;height:12px}
.dk-alert-list{gap:0}
.dk-alert-list .dk-alert{background:none;border:0;border-radius:0;padding:10px 0;border-bottom:1px solid #eef0f4}
.dk-alert-list .dk-alert:last-child{border-bottom:0}

/* Dashboard: Posts timeline and Views trend stacked, one full-width widget per row */
.dk-pair--stack{grid-template-columns:minmax(0,1fr)!important;gap:14px}
.dk-pair--stack .tv-side{grid-template-columns:repeat(4,minmax(0,1fr))!important}
.dk-pair--stack .tv-m3row{grid-template-columns:repeat(3,minmax(0,1fr))!important}
@media (max-width:900px){.dk-pair--stack .tv-side{grid-template-columns:repeat(2,minmax(0,1fr))!important}}

/* Dashboard campaign overview: two labelled groups (Delivery, Performance) on the same light blue panel, separated by rules */
.dk-ov-cells{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,4fr);align-items:stretch}
.dk-ov-grp{display:flex;flex-direction:column;min-width:0}
.dk-ov-grp+.dk-ov-grp{border-left:1px solid #d6dee9}
.dk-ov-gl{font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:#6b7280;padding:6px 18px 0}
.dk-ov-row--2,.dk-ov-row--4{flex:1}
.dk-ov-row--2{grid-template-columns:repeat(2,minmax(0,1fr))}
.dk-ov-row--4{grid-template-columns:repeat(4,minmax(0,1fr))}
.dk-ov-row--2 .dk-ov-item+.dk-ov-item,.dk-ov-row--4 .dk-ov-item+.dk-ov-item{border-left:1px solid #d6dee9;border-radius:0}
.dk-ov-row--2 .dk-ov-item,.dk-ov-row--4 .dk-ov-item{border-radius:0}
@media (max-width:1100px){.dk-ov-cells{grid-template-columns:1fr}.dk-ov-grp+.dk-ov-grp{border-left:0;border-top:1px solid #d6dee9}.dk-ov-row--4{grid-template-columns:repeat(2,minmax(0,1fr))}.dk-ov-row--4 .dk-ov-item:nth-child(3){border-left:0}}
@media (max-width:760px){.dk-ov-row--2{grid-template-columns:repeat(2,minmax(0,1fr))}}

/* Dashboard stacked trend: stats spread across the full card width */
.dk-pair--stack .dk-trend.tv--split>.tv-sidex{width:100%}
.dk-pair--stack .tv-seg-bar{width:100%}
.dk-pair--stack .tv-seg{width:100%}
.dk-pair--stack .tv-m3row{width:100%;grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:24px}
.dk-pair--stack .tv-seg-leg{justify-content:flex-start;gap:28px}

/* Day activity panel (opened by clicking a day on the posts timeline) */
.da-sum{display:flex;gap:18px;font-size:12.5px;color:#6b7280;padding:2px 0 12px;border-bottom:1px solid #eef0f4}
.da-sum b{color:#111827;font-weight:600}
.da-list{display:flex;flex-direction:column}
.da-row{display:grid;grid-template-columns:32px minmax(0,1fr) auto auto;gap:12px;align-items:center;padding:10px 0;border-bottom:1px solid #eef0f4}
.da-row:last-child{border-bottom:0}
.da-av{width:32px;height:32px;border-radius:50%;color:#fff;font-size:11px;font-weight:600;display:flex;align-items:center;justify-content:center}
.da-main{min-width:0;display:flex;flex-direction:column;gap:2px}
.da-main b{font-size:13px;font-weight:600;color:#111827;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.da-main small{font-size:11.5px;color:#6b7280;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.da-tag{font-size:11px;font-weight:600;color:#6b7280;background:#f1f3f7;border-radius:999px;padding:2px 8px;white-space:nowrap}
.da-tag.is-b{color:#0f766e;background:#e6f4f1}
.da-v{font-size:13px;font-weight:600;color:#111827;text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}
.da-v small{display:block;font-size:10.5px;font-weight:500;color:#9ca3af}
.da-empty{font-size:13px;color:#6b7280;margin:8px 0}

/* Campaign table: bold first column, tighter rows */
.dk-camps .ds-table td:first-child .ds-namebtn{font-weight:600;font-size:13.5px}
.dk-camps .ds-table td{padding-top:7px;padding-bottom:7px}
.dk-camps .ds-table td:first-child .life{margin-top:2px}
/* All posts table: shorter rows, smaller post thumbnail */
#dash-posts .ds-table td{padding-top:6px;padding-bottom:6px}
#dash-posts .pl-thumb{width:44px;height:44px;border-radius:8px}
#dash-posts .pl-thumb b{font-size:9px}
#dash-posts .pl-cell{gap:10px}

/* Campaign overview: each figure is its own bordered card with an icon tile, label, value and caption (dashboard and campaign page) */
.dk-ov .dk-ov-row{gap:10px}
.dk-ov-cells{gap:18px}
.dk-ov-gl{padding:0 2px 8px}
.dk-ov .dk-ov-row .dk-ov-item{background:#fff;border:1px solid #e3e8f0;border-radius:12px;padding:12px 14px 13px;gap:8px;box-shadow:0 1px 2px rgba(17,24,39,.04);min-width:0}
.dk-ov .dk-ov-row .dk-ov-item:hover{background:#fff;border-color:#cdd6e4}
.dk-ov .dk-ov-row .dk-ov-item.is-on{border-color:#374882;box-shadow:inset 0 0 0 1px #374882}
.dk-ov .dk-ov-row .dk-ov-item.is-on::after{display:none}
.dk-ov .dk-ov-l{font-size:12px;color:#374151;font-weight:500;gap:8px;align-items:center;line-height:1.3;text-transform:none;letter-spacing:0}
.dk-ov .dk-ov-l svg{width:28px;height:28px;padding:6px;box-sizing:border-box;border-radius:8px;background:#eef3fb;color:#374882;flex:none}
.dk-ov .dk-ov-item b{font-size:22px;line-height:1.1;margin-top:2px}
.dk-ov .dk-ov-item small,.dk-ov .dk-ov-s{font-size:11.5px;color:#6b7280;line-height:1.35}
.dk-ov-grp+.dk-ov-grp{border-left:0}
.dk-ov.cp-ov .dk-ov-row{grid-template-columns:repeat(3,minmax(0,1fr))!important;row-gap:10px}

/* Needs attention: short rows, a tone dot, bold name, one short line */
.na-row{display:flex;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid #eef0f4}
.na-row:last-child{border-bottom:0}
.na-dot{width:8px;height:8px;border-radius:50%;flex:none}
.na-dot--bad{background:#dc2626}
.na-dot--warn{background:#d97706}
.na-dot--info{background:#2563eb}
.na-main{min-width:0;flex:1;display:flex;flex-direction:column;gap:2px}
.na-name{font-size:13px;font-weight:600;color:#111827;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-align:left;max-width:100%}
.na-name.ds-namebtn{color:#111827}
.na-text{font-size:12px;color:#6b7280}
.na-tag{font-size:11.5px;color:#9ca3af;white-space:nowrap}
.na-act{font-size:12px;white-space:nowrap}

/* Campaign overview: one clean strip, no per-figure boxes, short labels and values, thin rules between figures */
.dk-ov .dk-ov-gl,.dk-ov-gl{display:none}
.dk-ov .dk-ov-item small,.dk-ov .dk-ov-s{display:none}
.dk-ov-cells{display:block;gap:0}
.dk-ov-grp{display:block}
.dk-ov .dk-ov-row,.dk-ov-row--2,.dk-ov-row--4,.dk-ov.cp-ov .dk-ov-row{display:grid;gap:0;grid-template-columns:repeat(6,minmax(0,1fr))!important;align-items:start;padding:2px 0 4px}
.dk-ov-row--2,.dk-ov-row--4{grid-template-columns:none}
.dk-ov .dk-ov-row .dk-ov-item,.dk-ov .dk-ov-row--all .dk-ov-item{background:transparent;border:0;border-radius:0;box-shadow:none;padding:6px 16px;gap:6px;min-width:0}
.dk-ov .dk-ov-row .dk-ov-item:hover{background:transparent}
.dk-ov .dk-ov-row .dk-ov-item:first-child{padding-left:0}
.dk-ov .dk-ov-row .dk-ov-item+.dk-ov-item{border-left:1px solid #dfe5ef}
.dk-ov .dk-ov-row .dk-ov-item.is-on{box-shadow:inset 0 -2px 0 #374882}
.dk-ov .dk-ov-l{font-size:12px;color:#6b7280;font-weight:500;gap:6px}
.dk-ov .dk-ov-l svg{width:15px;height:15px;padding:0;background:none;border-radius:0;color:#6b7280}
.dk-ov .dk-ov-item b{font-size:22px;margin-top:0}
.dk-ov.cp-ov .dk-ov-row{grid-template-columns:repeat(3,minmax(0,1fr))!important;row-gap:10px}
.dk-ov.cp-ov .dk-ov-row .dk-ov-item{padding:6px 16px}
.dk-ov.cp-ov .dk-ov-row .dk-ov-item:nth-child(3n+1){padding-left:0;border-left:0}
.dk-ov.cp-ov .dk-ov-item b{font-size:20px;white-space:nowrap}
@media (max-width:1100px){.dk-ov .dk-ov-row,.dk-ov.cp-ov .dk-ov-row{grid-template-columns:repeat(3,minmax(0,1fr))!important;row-gap:12px}.dk-ov .dk-ov-row .dk-ov-item:nth-child(3n+1){padding-left:0}.dk-ov .dk-ov-row .dk-ov-item:nth-child(3n+1){border-left:0}}

/* Campaign overview v2 (dashboard): two lines. Line 1 = key figures, large. Line 2 = supporting figures, compact. */
.dk-ov:not(.cp-ov) .dk-ov-cells{display:grid!important;grid-template-columns:repeat(6,minmax(0,1fr));gap:0;align-items:stretch}
.dk-ov:not(.cp-ov) .dk-ov-grp,.dk-ov:not(.cp-ov) .dk-ov-row{display:contents}
.dk-ov:not(.cp-ov) .dk-ov-gl{display:none}
.dk-ov:not(.cp-ov) .dk-ov-item{background:transparent!important;border:0;border-radius:0;box-shadow:none;padding:12px 18px;gap:4px;min-width:0;grid-column:span 2}
.dk-ov:not(.cp-ov) .dk-ov-item:hover{background:transparent!important}
.dk-ov:not(.cp-ov) .dk-ov-l{font-size:13px;color:#475569;font-weight:500;gap:7px}
.dk-ov:not(.cp-ov) .dk-ov-l svg{width:16px;height:16px;padding:0;background:none;border-radius:0;color:#6b7280}
.dk-ov:not(.cp-ov) .dk-ov-item b{font-size:30px;font-weight:600;line-height:1.1;margin-top:2px;white-space:nowrap}
/* line 1: Published posts | Total views | Total spent */
.dk-ov:not(.cp-ov) .dk-ov-row--2 .dk-ov-item:last-child{grid-row:1;grid-column:1 / 3;padding-left:0}
.dk-ov:not(.cp-ov) .dk-ov-row--4 .dk-ov-item:nth-child(1){grid-row:1;grid-column:3 / 5;border-left:1px solid #dfe5ef}
.dk-ov:not(.cp-ov) .dk-ov-row--4 .dk-ov-item:nth-child(2){grid-row:1;grid-column:5 / 7;border-left:1px solid #dfe5ef}
/* line 2: supporting figures, smaller */
.dk-ov:not(.cp-ov) .dk-ov-row--2 .dk-ov-item:first-child{grid-row:2;grid-column:1 / 3;padding-left:0;border-top:1px solid #e6ebf3}
.dk-ov:not(.cp-ov) .dk-ov-row--4 .dk-ov-item:nth-child(3){grid-row:2;grid-column:3 / 5;border-left:1px solid #dfe5ef;border-top:1px solid #e6ebf3}
.dk-ov:not(.cp-ov) .dk-ov-row--4 .dk-ov-item:nth-child(4){grid-row:2;grid-column:5 / 7;border-left:1px solid #dfe5ef;border-top:1px solid #e6ebf3}
.dk-ov:not(.cp-ov) .dk-ov-row--2 .dk-ov-item:first-child b,.dk-ov:not(.cp-ov) .dk-ov-row--4 .dk-ov-item:nth-child(n+3) b{font-size:18px;font-weight:600}
.dk-ov:not(.cp-ov) .dk-ov-row--2 .dk-ov-item:first-child .dk-ov-l,.dk-ov:not(.cp-ov) .dk-ov-row--4 .dk-ov-item:nth-child(n+3) .dk-ov-l{font-size:12px;color:#6b7280}
.dk-ov:not(.cp-ov) .dk-ov-row--2 .dk-ov-item:first-child .dk-ov-l svg,.dk-ov:not(.cp-ov) .dk-ov-row--4 .dk-ov-item:nth-child(n+3) .dk-ov-l svg{width:14px;height:14px}
@media (max-width:900px){
 .dk-ov:not(.cp-ov) .dk-ov-cells{grid-template-columns:repeat(2,minmax(0,1fr))}
 .dk-ov:not(.cp-ov) .dk-ov-item{grid-column:auto!important;grid-row:auto!important;border-left:0!important;border-top:0!important;padding-left:0}
 .dk-ov:not(.cp-ov) .dk-ov-item b{font-size:24px}
}
@media (max-width:900px){
 .dk-ov:not(.cp-ov) .dk-ov-row--2 .dk-ov-item:last-child{order:1}
 .dk-ov:not(.cp-ov) .dk-ov-row--4 .dk-ov-item:nth-child(1){order:2}
 .dk-ov:not(.cp-ov) .dk-ov-row--4 .dk-ov-item:nth-child(2){order:3}
 .dk-ov:not(.cp-ov) .dk-ov-row--2 .dk-ov-item:first-child{order:4}
 .dk-ov:not(.cp-ov) .dk-ov-row--4 .dk-ov-item:nth-child(3){order:5}
 .dk-ov:not(.cp-ov) .dk-ov-row--4 .dk-ov-item:nth-child(4){order:6}
}

/* Campaign overview v3: icon tiles and trend sparklines on key figures; stray divider fixed */
.dk-ov:not(.cp-ov) .dk-ov-row--2 .dk-ov-item:last-child{border-left:0!important}
.dk-ov:not(.cp-ov) .dk-ov-row--2 .dk-ov-item:first-child{border-left:0!important}
