/* v60 — add-posts CSV: loaded file shows its name with delete; preview keeps at least five rows visible */
.ap-file{display:flex;align-items:center;gap:10px;border:1px solid #e5e7eb;border-radius:12px;background:#fff;padding:10px 12px;margin-bottom:10px}
.ap-file-ico{flex:0 0 auto;width:32px;height:32px;border-radius:9px;background:#eef2ff;color:#3451b2;display:flex;align-items:center;justify-content:center}
.ap-file-ico svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.ap-file-name{flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:600;color:#1f2937}
.ap-file .ap-x{flex:0 0 auto}
.ap-dlg .ap-wrap,.ap-dlg .ap-wrap--bad{min-height:300px;max-height:330px}
.ap-dlg .addn-body{height:auto;min-height:440px}
/* v61 — confirmation dialogs: note and field stack in one column */
.dl-stack{grid-column:1/-1;display:flex;flex-direction:column;gap:12px;min-width:0}
/* v62 — My campaign table: selection checkbox column */
.cp-sel-th,.cp-sel-td{width:40px;min-width:40px;max-width:40px;padding-left:12px!important;padding-right:0!important}
