.rq-ov-list{list-style:none;margin:0;padding:0}
.rq-ov-item{padding:9px 0;border-bottom:1px solid #f1f2f5}
.rq-ov-top{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.rq-ov-t{font-weight:500;color:#111827;flex:1;min-width:0}
.rq-ov-d{color:#6b7280;font-size:12px;margin:3px 0 0;line-height:1.45}
.rq-ov-subs{list-style:none;margin:6px 0 0;padding:0 0 0 22px;border-left:1px solid #e5e7eb}
.rq-ov-sub{padding:5px 0}
.rq-ov-sr{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.rq-ov-sn{font-size:11px;color:#9ca3af;width:12px}
.rq-ov-st{flex:1;min-width:0;color:#374151}
.rq-ov-cta{border:1px solid #d6dbe4;background:#fff;border-radius:6px;padding:2px 8px;font:inherit;font-size:11.5px;color:#1247af;cursor:pointer;white-space:nowrap}
.rq-ov-cta:hover{background:#f3f6fd}
.rq-ov-how{font-size:11.5px;color:#1e3a8a;background:#eef4ff;border-radius:6px;padding:5px 8px;margin:4px 0 0 20px;line-height:1.45}
.rq-ov-note2{font-size:11.5px;color:#92400e;background:#fff7e6;border-radius:6px;padding:5px 8px;margin:4px 0 0 20px;line-height:1.45}
.rq-ov-note{color:#6b7280;margin:8px 0 0}
.rq-ov-links{list-style:none;margin:0;padding:0}
.rq-ov-link{width:100%;display:flex;justify-content:space-between;align-items:center;gap:8px;padding:8px 6px;border:0;background:none;border-radius:6px;font:inherit;font-size:13px;color:#1f2937;cursor:pointer;text-align:left}
