.my-chip-tip{display:none;position:absolute;left:0;top:calc(100% + 6px);z-index:30;min-width:180px;max-width:280px;padding:8px 10px;border-radius:8px;background:#1f2330;color:#fff;font-size:12px;line-height:1.4;box-shadow:0 8px 20px rgba(15,23,42,.25);white-space:normal}
