/* v88: one search-and-pick control for the add-to-campaign and add-to-list modals */
.ac-stack{display:flex;flex-direction:column;gap:16px;width:100%;min-width:0}
.ac-f{display:flex;flex-direction:column;gap:6px;width:100%}
.ac-l{font-size:13px;font-weight:500;color:#374151}
.ac-hint{font-size:12px;color:#6b7280;margin:0}
.cb{position:relative;width:100%}
.cb-in{width:100%;height:40px;box-sizing:border-box;padding:0 12px;border:1px solid #d6dbe4;border-radius:10px;font:inherit;font-size:14px;color:#111827;background:#fff}
