.cc-pane .cc-note{margin:0;font-size:12px;color:#6b7280}
.cc-drop{display:flex;flex-direction:column;align-items:center;gap:4px;padding:24px 16px;border:1px dashed #cfd5e0;border-radius:10px;background:#fafbfd;cursor:pointer;text-align:center}
