.cp-table tbody tr.is-done:hover>td.ds-sticky-l2{background:#fff}


/* v121: post sheet Remove is an outline button with red text (readable contrast, no filled red); analytics breakdown first column has a set width */
.ps-remove{background:#fff!important;color:#b42318!important;border:1px solid #f0b4ae!important}
.ps-remove:hover{background:#fef3f2!important;border-color:#d92d20!important;color:#912018!important}
.ps-remove:focus-visible{outline:2px solid #fca5a5;outline-offset:2px}
.ana-table th:first-child,.ana-table td:first-child{width:260px;min-width:220px;max-width:300px}


/* v122: CSV import dialogs share the drop zone and tag pattern: labelled sections, columns as tags, template link in a footer row */
.imp{display:flex;flex-direction:column;gap:18px}
.imp-intro{margin:0;font-size:13px;color:#4b5563;line-height:1.5}
.imp-sec{display:flex;flex-direction:column;gap:8px}
.imp-h{font-size:12px;font-weight:600;color:#6b7280;text-transform:uppercase;letter-spacing:.04em}
.imp-cols{display:flex;flex-wrap:wrap;gap:6px}
.imp-drop{background:#fff}
.imp-preview{font-size:13px;color:#6b7280;min-height:20px}
.imp-tpl{display:flex;align-items:center;gap:8px;font-size:13px;color:#6b7280;padding-top:12px;border-top:1px solid #eef0f4}


/* v123: first column reads the same at every level: campaign first, child rows name themselves with a level tag, campaign name is not repeated; header says what comes after Campaign */
.ac-lvl{display:inline-block;font-size:10.5px;font-weight:600;letter-spacing:.04em;text-transform:uppercase;color:#4b5563;background:#f3f4f6;border:1px solid #e3e7ef;border-radius:4px;padding:0 6px;line-height:16px;margin-bottom:2px;align-self:flex-start}
.ac-then{display:block;font-size:11px;font-weight:500;color:#6b7280;text-transform:none;letter-spacing:0;margin-top:2px}


/* v124: a collapsed group is one solid tint in its own colour (no grey hatch), and its vertical label is the group's full name, as in the expanded header */
.ac-table tbody td.ac-hatch{background:var(--gt,#f8f9fc)!important;border-left:2px solid var(--g,#c5cad6)!important;border-right:2px solid var(--g,#c5cad6)!important}


/* v125: brief summary as two clear rows (tags + View brief, then labelled stats); status filter uses the pill filter pattern */
.pl-strip{flex-direction:column;align-items:stretch;gap:12px;padding:14px 16px}
.pl-strip-top{display:flex;align-items:center;gap:12px}
.pl-strip-top .pl-strip-tags{flex:1;min-width:0}
.pl-strip-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin:0;padding-top:12px;border-top:1px solid #eef0f4;font-size:inherit;color:inherit;gap:0}
.pl-strip-stats>div{padding:0 16px;border-left:1px solid #eef0f4;min-width:0}
.pl-strip-stats>div:first-child{padding-left:0;border-left:0}
.pl-strip-stats dt{font-size:12px;color:#6b7280;margin:0}
.pl-strip-stats dd{margin:3px 0 0;font-size:15px;font-weight:600;color:#111827;overflow-wrap:anywhere}
