.lnch-grp h5 small{text-transform:none;letter-spacing:0;font-weight:400}
.lnch-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px 14px}
.lnch-f{display:flex;flex-direction:column;gap:5px;font-size:12px;color:#6b7280;min-width:0}
