.lnch-f input:focus{outline:none;border-color:#3b49c9;box-shadow:0 0 0 3px rgba(59,73,201,.12)}
.lnch-wide{grid-column:1 / -1}
.lnch-chips{display:flex;flex-wrap:wrap;gap:6px}
.lnch-chip{border:1px solid #d6dbe4;background:#f8fafc;color:#374151;border-radius:4px;padding:2px 9px;font:inherit;font-size:12px;cursor:pointer;line-height:18px}
.lnch-chip.is-on{background:#eef2ff;border-color:#3b49c9;color:#1e2a78;font-weight:600}
