@media (max-width:760px){.lnch-grid{grid-template-columns:1fr}.lnch-goals{grid-template-columns:repeat(2,minmax(0,1fr))}}


/* v127: colour by meaning, not blue everywhere: lists are violet, campaigns are teal, each creator status has its own colour */
.my-table .my-list-tag.is-list,.mq-tag.is-list{background:#f3efff;border-color:#d9cdfb;color:#4c2fa0}
