.my-status.is-shortlisted svg{color:#1f6b45}
.my-status.is-in-discussion svg{color:#8a5300}
.my-status.is-collaborated svg{color:#8a2b5c}
.my-status.is-rejected svg{color:#9b2c2c}


/* v128: campaigns and shortlists in the creator panel are a list (one row each, name left, status right) instead of pills */
.mq-rows{display:flex;flex-direction:column;border:1px solid #e3e7ef;border-radius:10px;overflow:hidden;background:#fff}
.mq-row{display:flex;align-items:center;gap:12px;width:100%;padding:10px 14px;border:0;border-top:1px solid #eef0f4;background:#fff;text-align:left;font:inherit;cursor:pointer;color:#111827}
.mq-row:first-child{border-top:0}
.mq-row:hover{background:#f8fafc}
.mq-row:focus-visible{outline:2px solid #93c5fd;outline-offset:-2px}
.mq-row::before{content:"";width:8px;height:8px;border-radius:50%;flex:none;background:var(--rowc,#9ca3af)}
