.mqq-kpi[data-k=teal] .mqq-kl .ico-sm,.cq-kpi:nth-child(3) .mqq-kl .ico-sm{background:#dcf7ee;color:#0f7a4a}
.mqq-kpi[data-k=indigo] .mqq-kl .ico-sm,.cq-kpi:nth-child(4) .mqq-kl .ico-sm{background:#e6e9ff;color:#3b49c9}
